CREATE OR REPLACE FUNCTION private.archive_team_context_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.archived_at is null and new.archived_at is not null and new.workspace_event_id is not null then
    update public.events set archived_at = new.archived_at, updated_by = auth.uid()
      where workspace_id = new.workspace_id and id = new.workspace_event_id and archived_at is null;
    insert into public.activity_logs(workspace_id,actor_id,entity_type,entity_id,action)
      values(new.workspace_id,auth.uid(),'event',new.workspace_event_id,'event.archived_with_team');
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.assignees_after_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.task_assignees%rowtype; v_action text; v_notify boolean := false;
begin
  if tg_op = 'DELETE' then
    v_row := old;
    v_action := 'task.assignee_removed';
  elsif tg_op = 'UPDATE' then
    v_row := new;
    v_action := 'task.assignee_changed';
    v_notify := new.is_primary and not old.is_primary;
  else
    v_row := new;
    v_action := 'task.assignee_added';
    v_notify := true;
  end if;
  insert into public.activity_logs (workspace_id, actor_id, entity_type, entity_id, action, metadata_json)
  values (v_row.workspace_id, coalesce(auth.uid(), v_row.assigned_by), 'task', v_row.task_id, v_action,
    jsonb_build_object('user_id', v_row.user_id, 'is_primary', v_row.is_primary));
  if v_notify and v_row.user_id is distinct from auth.uid() then
    insert into public.notifications (
      workspace_id, user_id, actor_id, notification_type, entity_type, entity_id, title, body, dedupe_key
    ) values (
      v_row.workspace_id, v_row.user_id, auth.uid(), 'task_assigned', 'task', v_row.task_id,
      'Nova demanda atribuída', 'Uma demanda foi atribuída a você.',
      format('task_assigned:%s:%s:%s', v_row.task_id, v_row.user_id, extract(epoch from v_row.assigned_at)::bigint)
    ) on conflict do nothing;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.can_delete_task_attachment_object(p_object_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_role public.workspace_role;
  v_task_id uuid;
  v_uploaded_by uuid;
begin
  select attachment.task_id, attachment.uploaded_by
  into v_task_id, v_uploaded_by
  from public.task_attachments attachment
  where attachment.bucket_id = 'task-attachments'
    and attachment.object_path = p_object_path
    and attachment.state = 'deleting'::public.task_attachment_state
    and attachment.delete_requested_by = v_actor
    and attachment.removal_lease_expires_at > clock_timestamp()
  for share;

  if not found then
    return false;
  end if;

  v_role := private.task_collaboration_role(v_task_id);
  return v_role in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role
  ) or (
    v_role = 'member'::public.workspace_role
    and v_uploaded_by = v_actor
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.can_read_task_attachment_object(p_object_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_role public.workspace_role;
  v_task_id uuid;
  v_uploaded_by uuid;
begin
  if exists (
    select 1
    from public.task_attachments attachment
    where attachment.bucket_id = 'task-attachments'
      and attachment.object_path = p_object_path
      and attachment.state = 'ready'::public.task_attachment_state
      and private.task_collaboration_role(attachment.task_id) is not null
  ) then
    return true;
  end if;

  select attachment.task_id, attachment.uploaded_by
  into v_task_id, v_uploaded_by
  from public.task_attachments attachment
  where attachment.bucket_id = 'task-attachments'
    and attachment.object_path = p_object_path
    and attachment.state = 'deleting'::public.task_attachment_state
    and attachment.delete_requested_by = v_actor
    and attachment.removal_lease_expires_at > clock_timestamp()
  for share;

  if not found then
    return false;
  end if;

  v_role := private.task_collaboration_role(v_task_id);
  return v_role in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role
  ) or (
    v_role = 'member'::public.workspace_role
    and v_uploaded_by = v_actor
  );
end;
$function$

