CREATE OR REPLACE FUNCTION private.enforce_workspace_active_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace_id uuid;
begin
  if tg_op = 'DELETE' then
    v_workspace_id := old.workspace_id;
  else
    v_workspace_id := new.workspace_id;
  end if;

  if exists (
    select 1
    from public.workspaces workspace
    where workspace.id = v_workspace_id
      and workspace.archived_at is null
  ) and not exists (
    select 1
    from public.workspace_members member
    join public.profiles profile
      on profile.id = member.user_id
      and profile.is_active
    where member.workspace_id = v_workspace_id
      and member.role = 'owner'::public.workspace_role
      and member.status = 'active'::public.membership_status
      and member.removed_at is null
  ) then
    raise exception using errcode = '23514', message = 'PTA_LAST_OWNER_REQUIRED';
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.event_milestones_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  new.title := btrim(new.title);
  if tg_op = 'UPDATE' then
    new.id := old.id;
    new.workspace_id := old.workspace_id;
    new.event_id := old.event_id;
    new.created_by := old.created_by;
    new.created_at := old.created_at;
    new.version := old.version + 1;
  end if;
  new.updated_at := clock_timestamp();
  return new;
end;
$function$

