CREATE OR REPLACE FUNCTION private.events_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  new.name := btrim(new.name);
  new.summary := nullif(btrim(new.summary), '');
  new.objective := nullif(btrim(new.objective), '');
