$function$

CREATE OR REPLACE FUNCTION private.guard_project_team()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.primary_team_id is not null then
    perform 1 from public.teams where workspace_id = new.workspace_id
      and id = new.primary_team_id and archived_at is null for share;
    if not found then raise exception using errcode = '23514', message = 'PTA_TEAM_NOT_ACTIVE'; end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_resource_restriction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role public.workspace_role;
begin
  v_role := private.current_workspace_role(new.workspace_id);

  if tg_op = 'INSERT'
    and (
      v_role is null
      or v_role not in (
        'owner'::public.workspace_role,
        'admin'::public.workspace_role,
        'manager'::public.workspace_role
      )
      or (
        new.is_restricted
        and v_role not in (
          'owner'::public.workspace_role,
          'admin'::public.workspace_role
        )
      )
    ) then
    raise exception using errcode = 'P0002', message = 'PTA_WORKSPACE_NOT_FOUND';
  end if;

  if tg_op = 'UPDATE'
    and new.is_restricted is distinct from old.is_restricted
    and (
      v_role is null
      or v_role not in ('owner'::public.workspace_role, 'admin'::public.workspace_role)
    ) then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_NOT_FOUND';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_team_context_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rows jsonb[] := array[]::jsonb[];
  v_row jsonb;
  v_key text;
  v_id uuid;
begin
  -- Trusted maintenance/service operations have no user identity. User RPCs
  -- already require auth.uid(); never grant a user an RLS-bypass exception.
  if auth.uid() is null then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;
  -- Only the archive cascade may write its internal event after membership
  -- removal. Its initiating team RPC is membership-guarded below.
  if tg_table_name = 'events' and tg_op = 'UPDATE' and pg_trigger_depth() > 1 then
    if old.archived_at is null and new.archived_at is not null
      and new.primary_team_id is not distinct from old.primary_team_id
      and exists(select 1 from public.teams t where t.workspace_id = old.workspace_id
        and t.workspace_event_id = old.id and t.id = old.primary_team_id
        and t.archived_at = new.archived_at) then
      return new;
    end if;
  end if;
  if tg_op <> 'INSERT' then v_rows := array_append(v_rows, to_jsonb(old)); end if;
  if tg_op <> 'DELETE' then v_rows := array_append(v_rows, to_jsonb(new)); end if;
  foreach v_row in array v_rows loop
    if tg_table_name = 'events' then
      -- New events have no existing row yet. Their intended primary team must
      -- be visible; updates/deletes also verify the previous context below.
      if nullif(v_row ->> 'primary_team_id', '') is not null
        and not private.can_read_team((v_row ->> 'primary_team_id')::uuid) then
        raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
      end if;
      if tg_op <> 'INSERT' and not private.can_read_event((old.id)::uuid) then
        raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
      end if;
    else
      foreach v_key in array array['event_id','task_id','parent_task_id','child_task_id','blocking_task_id','blocked_task_id','source_task_id','target_task_id'] loop
        v_id := nullif(v_row ->> v_key, '')::uuid;
        if v_id is not null and (
          (v_key = 'event_id' and not private.can_read_event(v_id)) or
          (v_key <> 'event_id' and not private.can_read_task(v_id))
        ) then
          raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
        end if;
      end loop;
      if tg_table_name = 'tasks' then
        if nullif(v_row ->> 'team_id', '') is not null
          and not private.can_read_team((v_row ->> 'team_id')::uuid) then
          raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
        end if;
        if tg_op <> 'INSERT' and not private.can_read_task(old.id) then
          raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
        end if;
      end if;
    end if;
  end loop;
  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_team_project_archive()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.archived_at is null and new.archived_at is not null then
    if exists(select 1 from public.events where workspace_id = new.workspace_id and primary_team_id = new.id
      and id is distinct from new.workspace_event_id and archived_at is null) then
      raise exception using errcode = '23514', message = 'PTA_TEAM_HAS_ACTIVE_PROJECTS';
    end if;
    if exists(select 1 from public.tasks where workspace_id = new.workspace_id
      and event_id = new.workspace_event_id and archived_at is null) then
      raise exception using errcode = '23514', message = 'PTA_TEAM_HAS_ACTIVE_TASKS';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_team_workspace_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' and old.workspace_event_id is not null
    and new.workspace_event_id is distinct from old.workspace_event_id then
    raise exception using errcode = '23514', message = 'PTA_TEAM_WORKSPACE_IMMUTABLE';
  end if;
  if new.workspace_event_id is not null then
    perform 1 from public.events where workspace_id = new.workspace_id and id = new.workspace_event_id
      and primary_team_id = new.id and archived_at is null for share;
    if not found then raise exception using errcode = '23514', message = 'PTA_TEAM_WORKSPACE_INVALID'; end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.is_valid_task_description(p_description jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare
  v_block jsonb;
  v_node_count integer;
begin
  if jsonb_typeof(p_description) <> 'object'
    or not private.jsonb_has_only_keys(p_description, array['type', 'content'])
    or (p_description ->> 'type') is distinct from 'doc'
    or jsonb_typeof(p_description -> 'content') <> 'array' then
    return false;
  end if;

  select count(*)
  into v_node_count
  from jsonb_path_query(p_description, 'strict $.** ? (@.type() == "object")');

  if v_node_count > 3000 then
    return false;
  end if;

  for v_block in
    select block_node.value
    from jsonb_array_elements(p_description -> 'content') as block_node(value)
  loop
    if v_block ->> 'type' not in (
      'paragraph',
      'heading',
      'bulletList',
      'orderedList',
      'taskList',
      'blockquote'
    ) or not private.is_valid_task_description_node(v_block, 0) then
      return false;
    end if;
  end loop;

  return true;
exception
  when others then
    return false;
end;
$function$

CREATE OR REPLACE FUNCTION private.is_valid_task_description_mark(p_mark jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare
  v_type text := p_mark ->> 'type';
  v_attrs jsonb := p_mark -> 'attrs';
  v_href text;
begin
  if jsonb_typeof(p_mark) <> 'object' then
    return false;
  end if;

  if v_type in ('bold', 'italic', 'strike', 'code') then
    return private.jsonb_has_only_keys(p_mark, array['type']);
  end if;

  if v_type <> 'link'
    or not private.jsonb_has_only_keys(p_mark, array['type', 'attrs'])
    or jsonb_typeof(v_attrs) <> 'object'
    or not private.jsonb_has_only_keys(
      v_attrs,
      array['href', 'target', 'rel', 'class']
    ) then
    return false;
  end if;

  v_href := v_attrs ->> 'href';
  if not private.is_valid_resource_url(v_href) then
    return false;
  end if;
  if v_attrs ? 'target'
    and jsonb_typeof(v_attrs -> 'target') not in ('string', 'null') then
    return false;
  end if;
  if coalesce(v_attrs ->> 'target', '_blank') <> '_blank' then
    return false;
  end if;
  if v_attrs ? 'rel'
    and jsonb_typeof(v_attrs -> 'rel') not in ('string', 'null') then
    return false;
  end if;
  if v_attrs ? 'class'
    and jsonb_typeof(v_attrs -> 'class') not in ('string', 'null') then
    return false;
  end if;
  if char_length(coalesce(v_attrs ->> 'rel', '')) > 120
    or char_length(coalesce(v_attrs ->> 'class', '')) > 120 then
    return false;
  end if;

  return true;
exception
  when others then
    return false;
end;
$function$

CREATE OR REPLACE FUNCTION private.is_valid_task_description_node(p_node jsonb, p_depth integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare
  v_type text := p_node ->> 'type';
  v_content jsonb := p_node -> 'content';
  v_attrs jsonb := p_node -> 'attrs';
  v_child jsonb;
  v_mark jsonb;
begin
  if p_depth > 10 or jsonb_typeof(p_node) <> 'object' then
    return false;
  end if;

  if v_type = 'text' then
    if not private.jsonb_has_only_keys(p_node, array['type', 'text', 'marks'])
      or jsonb_typeof(p_node -> 'text') <> 'string'
      or char_length(p_node ->> 'text') > 50000 then
      return false;
    end if;
    if p_node ? 'marks' then
      if jsonb_typeof(p_node -> 'marks') <> 'array'
        or jsonb_array_length(p_node -> 'marks') > 12 then
        return false;
      end if;
      for v_mark in
        select mark.value
        from jsonb_array_elements(p_node -> 'marks') as mark(value)
      loop
        if not private.is_valid_task_description_mark(v_mark) then
          return false;
        end if;
      end loop;
    end if;
    return true;
  end if;

  if v_type = 'hardBreak' then
    return private.jsonb_has_only_keys(p_node, array['type']);
  end if;

  if v_type = 'heading' then
    if not private.jsonb_has_only_keys(p_node, array['type', 'attrs', 'content'])
      or jsonb_typeof(v_attrs) <> 'object'
      or not private.jsonb_has_only_keys(v_attrs, array['level'])
      or jsonb_typeof(v_attrs -> 'level') <> 'number'
      or (v_attrs ->> 'level')::integer not between 1 and 3 then
      return false;
    end if;
  elsif v_type = 'orderedList' then
    if not private.jsonb_has_only_keys(p_node, array['type', 'attrs', 'content']) then
      return false;
    end if;
    if v_attrs is not null then
      if jsonb_typeof(v_attrs) <> 'object'
        or not private.jsonb_has_only_keys(v_attrs, array['start', 'type']) then
        return false;
      end if;
      if v_attrs ? 'start'
        and (
          jsonb_typeof(v_attrs -> 'start') <> 'number'
          or (v_attrs ->> 'start')::integer < 1
        ) then
        return false;
      end if;
      if v_attrs ? 'type'
        and jsonb_typeof(v_attrs -> 'type') not in ('string', 'null') then
        return false;
      end if;
      if v_attrs ->> 'type' is not null
        and v_attrs ->> 'type' not in ('1', 'a', 'A', 'i', 'I') then
        return false;
      end if;
    end if;
  elsif v_type = 'taskItem' then
    if not private.jsonb_has_only_keys(p_node, array['type', 'attrs', 'content'])
      or jsonb_typeof(v_attrs) <> 'object'
      or not private.jsonb_has_only_keys(v_attrs, array['checked'])
      or jsonb_typeof(v_attrs -> 'checked') <> 'boolean' then
      return false;
    end if;
  elsif v_type in ('paragraph', 'bulletList', 'listItem', 'taskList', 'blockquote') then
    if not private.jsonb_has_only_keys(p_node, array['type', 'content']) then
      return false;
    end if;
  else
    return false;
  end if;

  if v_content is null then
    return v_type in ('paragraph', 'heading');
  end if;
  if jsonb_typeof(v_content) <> 'array' then
    return false;
  end if;

  for v_child in
    select child.value
    from jsonb_array_elements(v_content) as child(value)
  loop
    if v_type in ('paragraph', 'heading')
      and v_child ->> 'type' not in ('text', 'hardBreak') then
      return false;
    end if;
    if v_type in ('bulletList', 'orderedList')
      and v_child ->> 'type' <> 'listItem' then
      return false;
    end if;
    if v_type = 'taskList' and v_child ->> 'type' <> 'taskItem' then
      return false;
    end if;
    if v_type in ('listItem', 'taskItem')
      and v_child ->> 'type' not in (
        'paragraph',
        'bulletList',
        'orderedList',
        'taskList',
        'blockquote'
      ) then
      return false;
    end if;
    if v_type = 'blockquote'
      and v_child ->> 'type' not in (
        'paragraph',
        'heading',
        'bulletList',
        'orderedList',
        'taskList',
        'blockquote'
      ) then
      return false;
    end if;
    if not private.is_valid_task_description_node(v_child, p_depth + 1) then
      return false;
    end if;
  end loop;

  return true;
exception
  when others then
    return false;
end;
$function$

CREATE OR REPLACE FUNCTION private.job_functions_before_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.id is distinct from old.id
     or new.workspace_id is distinct from old.workspace_id
     or new.system_key is distinct from old.system_key
     or new.is_system is distinct from old.is_system
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at then
    raise exception using errcode = '22023', message = 'PTA_JOB_FUNCTION_IDENTITY_IMMUTABLE';
  end if;

  new.name := btrim(new.name);
  new.category := btrim(new.category);
  new.description := nullif(btrim(new.description), '');
  new.updated_at := statement_timestamp();
  new.version := old.version + 1;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.jsonb_uuid_array(p_patch jsonb, p_key text)
 RETURNS uuid[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_value jsonb := p_patch -> p_key;
  v_result uuid[];
begin
  if jsonb_typeof(v_value) <> 'array'
    or exists (
      select 1
      from jsonb_array_elements(v_value) item
      where jsonb_typeof(item) <> 'string'
        or trim(both '"' from item::text) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_PATCH';
  end if;

  select coalesce(array_agg(distinct value::uuid), '{}'::uuid[])
  into v_result
  from jsonb_array_elements_text(v_value) item(value);

  return v_result;
end;
$function$

