CREATE OR REPLACE FUNCTION private.tasks_after_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_changes jsonb := '{}'::jsonb;
begin
  if tg_op = 'INSERT' then
    insert into public.activity_logs (
      workspace_id,
      actor_id,
      entity_type,
      entity_id,
      action,
      metadata_json
    ) values (
      new.workspace_id,
      new.created_by,
      'task',
      new.id,
      'task.created',
      jsonb_build_object('task_number', new.task_number)
    );

    insert into public.notifications (
      workspace_id,
      user_id,
      actor_id,
      notification_type,
      entity_type,
      entity_id,
      title,
      body,
      dedupe_key
    ) values (
      new.workspace_id,
      new.created_by,
      new.created_by,
      'task_created',
      'task',
      new.id,
      'Demanda criada',
      new.title,
      format('task_created:%s:%s', new.id, new.created_by)
    ) on conflict do nothing;

    return new;
  end if;

  if new.title is distinct from old.title then
    v_changes := v_changes || jsonb_build_object(
      'title',
      jsonb_build_object('old', old.title, 'new', new.title)
    );
  end if;

  if new.status_id is distinct from old.status_id then
    v_changes := v_changes || jsonb_build_object(
      'status_id',
      jsonb_build_object('old', old.status_id, 'new', new.status_id)
    );
  end if;

  if new.priority is distinct from old.priority then
    v_changes := v_changes || jsonb_build_object(
      'priority',
      jsonb_build_object('old', old.priority, 'new', new.priority)
    );
  end if;

  if new.due_date is distinct from old.due_date
     or new.due_time is distinct from old.due_time then
    v_changes := v_changes || jsonb_build_object(
      'due',
      jsonb_build_object(
        'old', jsonb_build_object('date', old.due_date, 'time', old.due_time),
        'new', jsonb_build_object('date', new.due_date, 'time', new.due_time)
      )
    );
  end if;

  if new.type_id is distinct from old.type_id then
    v_changes := v_changes || jsonb_build_object(
      'type_id',
      jsonb_build_object('old', old.type_id, 'new', new.type_id)
    );
  end if;

  if new.product_id is distinct from old.product_id then
    v_changes := v_changes || jsonb_build_object(
      'product_id',
      jsonb_build_object('old', old.product_id, 'new', new.product_id)
    );
  end if;

  if new.event_id is distinct from old.event_id then
    v_changes := v_changes || jsonb_build_object(
      'event_id',
      jsonb_build_object('old', old.event_id, 'new', new.event_id)
    );
  end if;

  if v_changes <> '{}'::jsonb then
    insert into public.activity_logs (
      workspace_id,
      actor_id,
      entity_type,
      entity_id,
      action,
      changes_json
    ) values (
      new.workspace_id,
      new.updated_by,
      'task',
      new.id,
      'task.updated',
      v_changes
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.tasks_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_timezone text;
  v_default_due_time time without time zone;
  v_status_category public.task_status_category;
  v_status_active boolean;
  v_event_product_id uuid;
begin
  new.title := btrim(new.title);

  if tg_op = 'INSERT' then
    new.task_number := private.next_task_number(new.workspace_id);
    new.created_by := coalesce(new.created_by, v_actor);
    new.updated_by := coalesce(new.updated_by, v_actor);
    new.version := 1;
  else
    new.id := old.id;
    new.workspace_id := old.workspace_id;
    new.task_number := old.task_number;
    new.created_by := old.created_by;
    new.created_at := old.created_at;
    new.updated_by := coalesce(v_actor, new.updated_by, old.updated_by);
    new.updated_at := clock_timestamp();
    new.version := old.version + 1;
  end if;

  select ts.system_category, ts.is_active into v_status_category, v_status_active
  from public.task_statuses ts
  where ts.workspace_id = new.workspace_id and ts.id = new.status_id;
  if not found then raise exception using errcode = '23503', message = 'PTA_INVALID_TASK_STATUS'; end if;
  if (tg_op = 'INSERT' or new.status_id is distinct from old.status_id) and not v_status_active then
    raise exception using errcode = '23514', message = 'PTA_INACTIVE_TASK_STATUS';
  end if;

  if new.event_id is not null then
    select e.product_id into v_event_product_id from public.events e
    where e.workspace_id = new.workspace_id and e.id = new.event_id and e.archived_at is null;
    if not found then raise exception using errcode = '23503', message = 'PTA_INVALID_TASK_EVENT'; end if;
    if v_event_product_id is not null and new.product_id is null then new.product_id := v_event_product_id; end if;
    if v_event_product_id is not null and new.product_id <> v_event_product_id then
      raise exception using errcode = '23514', message = 'PTA_EVENT_PRODUCT_MISMATCH';
    end if;
  end if;

  if new.product_id is not null and not exists (
    select 1 from public.products p
    where p.workspace_id = new.workspace_id and p.id = new.product_id and p.archived_at is null
  ) then
    raise exception using errcode = '23503', message = 'PTA_INVALID_TASK_PRODUCT';
  end if;

  select w.timezone, w.default_due_time into v_timezone, v_default_due_time
  from public.workspaces w where w.id = new.workspace_id and w.archived_at is null;
  if not found then raise exception using errcode = '23503', message = 'PTA_INVALID_WORKSPACE'; end if;

  if new.due_date is null then
    new.due_time := null;
    new.due_at := null;
  else
    new.due_at := (new.due_date + coalesce(new.due_time, v_default_due_time)) at time zone v_timezone;
  end if;

  if v_status_category = 'done' then
    new.completed_at := coalesce(new.completed_at, clock_timestamp());
    new.completed_by := coalesce(new.completed_by, v_actor, new.updated_by);
  else
    new.completed_at := null;
    new.completed_by := null;
  end if;

  if v_status_category = 'blocked' then
    new.blocked_reason := nullif(btrim(new.blocked_reason), '');
    if new.blocked_reason is null then
      raise exception using errcode = '23514', message = 'PTA_BLOCKED_REASON_REQUIRED';
    end if;
  else
    new.blocked_reason := null;
  end if;

  new.search_vector :=
    setweight(to_tsvector('pg_catalog.portuguese'::regconfig, coalesce(new.title, '')), 'A')
    || setweight(to_tsvector('pg_catalog.simple'::regconfig, new.task_number::text), 'A');
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.tasks_operating_model_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.team_id is null then
      select team.id
      into new.team_id
      from public.teams team
      where team.workspace_id = new.workspace_id
        and team.is_default
        and team.archived_at is null
      order by team.created_at, team.id
      limit 1;
    end if;
    new.requester_id := coalesce(new.requester_id, new.created_by, auth.uid());
  end if;

  if tg_op = 'INSERT'
     or new.team_id is distinct from old.team_id then
    if not exists (
      select 1
      from public.teams team
      where team.workspace_id = new.workspace_id
        and team.id = new.team_id
        and team.archived_at is null
    ) then
      raise exception using errcode = '23514', message = 'PTA_TASK_TEAM_NOT_ACTIVE';
    end if;

    if tg_op = 'UPDATE' and exists (
      select 1
      from public.task_assignees assignee
      where assignee.workspace_id = new.workspace_id
        and assignee.task_id = new.id
        and not exists (
          select 1
          from public.team_members team_member
          where team_member.workspace_id = new.workspace_id
            and team_member.team_id = new.team_id
            and team_member.user_id = assignee.user_id
            and team_member.removed_at is null
        )
    ) then
      raise exception using errcode = '23514', message = 'PTA_TASK_ASSIGNEE_TEAM_MISMATCH';
    end if;
  end if;

  if tg_op = 'INSERT'
     or new.requester_id is distinct from old.requester_id then
    if not exists (
      select 1
      from public.workspace_members member
      join public.profiles profile on profile.id = member.user_id and profile.is_active
      where member.workspace_id = new.workspace_id
        and member.user_id = new.requester_id
        and member.status = 'active'::public.membership_status
        and member.removed_at is null
    ) then
      raise exception using errcode = '23514', message = 'PTA_TASK_REQUESTER_NOT_ACTIVE';
    end if;
  end if;

  return new;
end;
$function$

