CREATE OR REPLACE FUNCTION public.accept_workspace_invitation(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_email text;
  v_token_hash text;
  v_workspace_id uuid;
  v_workspace_name text;
  v_invitation public.workspace_invitations%rowtype;
  v_member public.workspace_members%rowtype;
  v_already_accepted boolean := false;
  v_member_existed boolean := false;
  v_membership_activated boolean := false;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;

  select lower(btrim(auth_user.email))
  into v_actor_email
  from auth.users auth_user
  join public.profiles profile
    on profile.id = auth_user.id
    and profile.is_active
  where auth_user.id = v_actor;

  if v_actor_email is null then
    raise exception using errcode = '42501', message = 'PTA_PROFILE_INACTIVE';
  end if;
  if p_token is null or btrim(p_token) !~* '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'PTA_INVITATION_INVALID';
  end if;

  v_token_hash := encode(extensions.digest(lower(btrim(p_token)), 'sha256'), 'hex');
  select invitation.workspace_id
  into v_workspace_id
  from public.workspace_invitations invitation
  where invitation.token_hash = v_token_hash;

  if v_workspace_id is null then
    raise exception using errcode = '22023', message = 'PTA_INVITATION_INVALID';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:workspace-team:' || v_workspace_id::text, 0)
  );

  select invitation.*
  into v_invitation
  from public.workspace_invitations invitation
  where invitation.token_hash = v_token_hash
  for update;

  if not found then
    raise exception using errcode = '22023', message = 'PTA_INVITATION_INVALID';
  end if;
  if v_invitation.email <> v_actor_email then
    raise exception using errcode = '42501', message = 'PTA_INVITATION_EMAIL_MISMATCH';
  end if;

  select workspace.name
  into v_workspace_name
  from public.workspaces workspace
  where workspace.id = v_workspace_id
    and workspace.archived_at is null;

  if v_workspace_name is null then
    raise exception using errcode = '22023', message = 'PTA_INVITATION_INVALID';
  end if;

  if v_invitation.accepted_at is not null then
    if v_invitation.accepted_by is distinct from v_actor then
      raise exception using errcode = '42501', message = 'PTA_INVITATION_ALREADY_USED';
    end if;
    v_already_accepted := true;
  else
    if v_invitation.cancelled_at is not null then
      raise exception using errcode = '23514', message = 'PTA_INVITATION_CANCELLED';
    end if;
    if v_invitation.expires_at <= statement_timestamp() then
      raise exception using errcode = '23514', message = 'PTA_INVITATION_EXPIRED';
    end if;
  end if;

  select member.*
  into v_member
  from public.workspace_members member
  where member.workspace_id = v_workspace_id
    and member.user_id = v_actor
  for update;
  v_member_existed := found;

  if v_already_accepted then
    if not v_member_existed then
      raise exception using errcode = '23514', message = 'PTA_INVITATION_STATE_INVALID';
    end if;
    if v_member.status <> 'active'::public.membership_status
       or v_member.removed_at is not null then
      raise exception using errcode = '23514', message = 'PTA_INVITATION_ALREADY_USED';
    end if;
  elsif not v_member_existed then
    insert into public.workspace_members (
      workspace_id,
      user_id,
      role,
      status,
      joined_at
    ) values (
      v_workspace_id,
      v_actor,
      v_invitation.role,
      'active'::public.membership_status,
      statement_timestamp()
    )
    returning * into v_member;
    v_membership_activated := true;
  elsif v_member.status = 'suspended'::public.membership_status
        or v_member.removed_at is not null then
    update public.workspace_members member
    set
      role = v_invitation.role,
      status = 'active'::public.membership_status,
      suspended_at = null,
      removed_at = null,
      removed_by = null
    where member.workspace_id = v_workspace_id
      and member.user_id = v_actor
    returning member.* into v_member;
    v_membership_activated := true;
  end if;

  if not v_already_accepted then
    update public.workspace_invitations invitation
    set
      accepted_at = statement_timestamp(),
      accepted_by = v_actor
    where invitation.id = v_invitation.id;

    insert into public.activity_logs (
      workspace_id,
      actor_id,
      entity_type,
      entity_id,
      action,
      metadata_json
    ) values (
      v_workspace_id,
      v_actor,
      'workspace_invitation',
      v_invitation.id,
      'workspace.invitation_accepted',
      jsonb_build_object('role', v_member.role)
    );

    if v_membership_activated then
      insert into public.activity_logs (
        workspace_id,
        actor_id,
        entity_type,
        entity_id,
        action,
        changes_json
      ) values (
        v_workspace_id,
        v_actor,
        'workspace_member',
        v_actor,
        case when v_member_existed then 'workspace.member_reactivated' else 'workspace.member_joined' end,
        jsonb_build_object(
          'role', jsonb_build_object('to', v_member.role),
          'status', jsonb_build_object('to', 'active')
        )
      );
    end if;
  end if;

  return jsonb_build_object(
    'workspace_id', v_workspace_id,
    'workspace_name', v_workspace_name,
    'user_id', v_actor,
    'role', v_member.role,
    'status', v_member.status,
    'membership_state', case
      when v_member.removed_at is not null then 'removed'
      else v_member.status::text
    end,
    'version', v_member.version,
    'already_accepted', v_already_accepted
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.add_task_checklist_item(p_checklist_id uuid, p_content text, p_position numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_workspace_id uuid;
  v_task_id uuid;
  v_role public.workspace_role;
  v_position numeric;
  v_item public.task_checklist_items%rowtype;
begin
  select checklist.workspace_id, checklist.task_id
  into v_workspace_id, v_task_id
  from public.task_checklists checklist
  where checklist.id = p_checklist_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_CHECKLIST_NOT_FOUND';
  end if;
  v_role := private.task_collaboration_role(v_task_id);
  if v_role is null then
    raise exception using errcode = 'P0002', message = 'PTA_CHECKLIST_NOT_FOUND';
  end if;
  if not private.can_edit_task(v_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_content is null or char_length(btrim(p_content)) not between 1 and 500 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_CHECKLIST_ITEM';
  end if;
  if p_position is not null and p_position < 0 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_CHECKLIST_POSITION';
  end if;

  select coalesce(
    p_position,
    coalesce(max(item.position), 0) + 1000
  )
  into v_position
  from public.task_checklist_items item
  where item.workspace_id = v_workspace_id
    and item.task_id = v_task_id
    and item.checklist_id = p_checklist_id;

  insert into public.task_checklist_items (
    workspace_id,
    task_id,
    checklist_id,
    content,
    position,
    created_by
  ) values (
    v_workspace_id,
    v_task_id,
    p_checklist_id,
    btrim(p_content),
    v_position,
    v_actor
  )
  returning * into v_item;

  update public.task_checklists checklist
  set updated_at = clock_timestamp()
  where checklist.workspace_id = v_workspace_id
    and checklist.task_id = v_task_id
    and checklist.id = p_checklist_id;

  return jsonb_build_object(
    'id', v_item.id,
    'checklist_id', v_item.checklist_id,
    'task_id', v_item.task_id,
    'content', v_item.content,
    'position', v_item.position,
    'is_completed', v_item.is_completed,
    'created_by', v_item.created_by,
    'created_at', v_item.created_at,
    'updated_at', v_item.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.add_task_checklist_item_to_task(p_task_id uuid, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_workspace_id uuid;
  v_checklist public.task_checklists%rowtype;
  v_item public.task_checklist_items%rowtype;
  v_position numeric;
begin
  select task.workspace_id
  into v_workspace_id
  from public.tasks task
  where task.id = p_task_id
    and task.archived_at is null;

  if v_workspace_id is null or not private.can_edit_task(p_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_content is null or char_length(btrim(p_content)) not between 1 and 500 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_CHECKLIST_ITEM';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:task-default-checklist:' || p_task_id::text, 0)
  );

  select checklist.*
  into v_checklist
  from public.task_checklists checklist
  where checklist.workspace_id = v_workspace_id
    and checklist.task_id = p_task_id
    and checklist.is_default
  for update;

  if not found then
    insert into public.task_checklists (
      workspace_id, task_id, title, position, created_by, is_default
    ) values (
      v_workspace_id, p_task_id, 'Checklist', 0, v_actor, true
    )
    returning * into v_checklist;
  end if;

  select coalesce(max(item.position), 0) + 1000
  into v_position
  from public.task_checklist_items item
  where item.workspace_id = v_workspace_id
    and item.task_id = p_task_id
    and item.checklist_id = v_checklist.id;

  insert into public.task_checklist_items (
    workspace_id, task_id, checklist_id, content, position, created_by
  ) values (
    v_workspace_id, p_task_id, v_checklist.id, btrim(p_content), v_position, v_actor
  )
  returning * into v_item;

  update public.task_checklists checklist
  set updated_at = clock_timestamp()
  where checklist.workspace_id = v_workspace_id
    and checklist.task_id = p_task_id
    and checklist.id = v_checklist.id;

  return jsonb_build_object(
    'id', v_item.id,
    'checklist_id', v_item.checklist_id,
    'task_id', v_item.task_id,
    'content', v_item.content,
    'position', v_item.position,
    'is_completed', v_item.is_completed,
    'created_by', v_item.created_by,
    'created_at', v_item.created_at,
    'updated_at', v_item.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.add_task_comment(p_task_id uuid, p_body text, p_parent_comment_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_workspace_id uuid;
  v_role public.workspace_role;
  v_comment public.task_comments%rowtype;
begin
  select task.workspace_id
  into v_workspace_id
  from public.tasks task
  where task.id = p_task_id
    and task.archived_at is null;

  v_role := private.task_collaboration_role(p_task_id);
  if v_workspace_id is null or v_role is null then
    raise exception using errcode = 'P0002', message = 'PTA_TASK_NOT_FOUND';
  end if;
  if v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role,
    'member'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_body is null or char_length(btrim(p_body)) not between 1 and 10000 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_COMMENT';
  end if;
  if p_parent_comment_id is not null and not exists (
    select 1
    from public.task_comments parent_comment
    where parent_comment.workspace_id = v_workspace_id
      and parent_comment.task_id = p_task_id
      and parent_comment.id = p_parent_comment_id
      and parent_comment.deleted_at is null
  ) then
    raise exception using errcode = 'P0002', message = 'PTA_COMMENT_NOT_FOUND';
  end if;

  insert into public.task_comments (
    workspace_id,
    task_id,
    parent_comment_id,
    body,
    created_by
  ) values (
    v_workspace_id,
    p_task_id,
    p_parent_comment_id,
    btrim(p_body),
    v_actor
  )
  returning * into v_comment;

  return jsonb_build_object(
    'id', v_comment.id,
    'task_id', v_comment.task_id,
    'parent_comment_id', v_comment.parent_comment_id,
    'body', v_comment.body,
    'created_by', v_comment.created_by,
    'created_at', v_comment.created_at,
    'updated_at', v_comment.updated_at,
    'edited_at', v_comment.edited_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.add_task_link(p_task_id uuid, p_url text, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_workspace_id uuid;
  v_role public.workspace_role;
  v_url text := btrim(p_url);
  v_label text := nullif(btrim(p_label), '');
  v_link public.task_links%rowtype;
begin
  select task.workspace_id
  into v_workspace_id
  from public.tasks task
  where task.id = p_task_id
    and task.archived_at is null;

  v_role := private.task_collaboration_role(p_task_id);
  if v_workspace_id is null or v_role is null then
    raise exception using errcode = 'P0002', message = 'PTA_TASK_NOT_FOUND';
  end if;
  if v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role,
    'member'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_url is null
    or char_length(v_url) not between 8 and 2048
    or v_url !~* '^https://[a-z0-9]([a-z0-9.-]*[a-z0-9])?(:[0-9]{1,5})?([/?#][^[:space:]]*)?$'
    or v_url ~* '%0d|%0a' then
    raise exception using errcode = '22023', message = 'PTA_INVALID_LINK_URL';
  end if;
  if v_label is not null and char_length(v_label) > 200 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_LINK_LABEL';
  end if;

  insert into public.task_links (
    workspace_id,
    task_id,
    url,
    label,
    provider,
    created_by
  ) values (
    v_workspace_id,
    p_task_id,
    v_url,
    v_label,
    private.task_link_provider(v_url),
    v_actor
  )
  returning * into v_link;

  return jsonb_build_object(
    'id', v_link.id,
    'task_id', v_link.task_id,
    'url', v_link.url,
    'label', v_link.label,
    'provider', v_link.provider,
    'created_by', v_link.created_by,
    'created_at', v_link.created_at,
    'updated_at', v_link.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_event_phase(p_workspace_id uuid, p_phase_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_phase public.event_phases%rowtype;
begin
  if v_actor is null
     or coalesce(private.current_workspace_role(p_workspace_id) not in ('owner', 'admin', 'manager'), true) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  select phase.* into v_phase
  from public.event_phases phase
  where phase.workspace_id = p_workspace_id
    and phase.id = p_phase_id
    and phase.archived_at is null
  for update;
  if not found then raise exception using errcode = 'P0002', message = 'PTA_PHASE_NOT_FOUND'; end if;
  if v_phase.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  update public.tasks task
  set event_phase_id = null, updated_by = v_actor
  where task.workspace_id = p_workspace_id and task.event_phase_id = p_phase_id;
  update public.event_milestones milestone
  set event_phase_id = null, updated_by = v_actor
  where milestone.workspace_id = p_workspace_id and milestone.event_phase_id = p_phase_id;
  update public.event_phases phase
  set archived_at = clock_timestamp(), updated_by = v_actor
  where phase.workspace_id = p_workspace_id
    and phase.id = p_phase_id
    and phase.version = p_expected_version
  returning * into v_phase;
  if not found then raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT'; end if;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    p_workspace_id, v_actor, 'event_phase', v_phase.id, 'event.phase_archived',
    jsonb_build_object('event_id', v_phase.event_id)
  );
  return jsonb_build_object('id', v_phase.id, 'version', v_phase.version);
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_job_function(p_job_function_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_function public.job_functions%rowtype;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;

  select job_function.*
  into v_function
  from public.job_functions job_function
  where job_function.id = p_job_function_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_JOB_FUNCTION_NOT_FOUND';
  end if;
  if not private.can_manage_operating_model(v_function.workspace_id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;
  if v_function.archived_at is not null then
    return jsonb_build_object(
      'id', v_function.id,
      'version', v_function.version,
      'archived_at', v_function.archived_at
    );
  end if;
  if v_function.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if v_function.is_system then
    raise exception using errcode = '23514', message = 'PTA_SYSTEM_JOB_FUNCTION_REQUIRED';
  end if;

  update public.team_member_functions assignment
  set
    is_primary = false,
    archived_at = statement_timestamp(),
    archived_by = v_actor
  where assignment.workspace_id = v_function.workspace_id
    and assignment.job_function_id = v_function.id
    and assignment.archived_at is null;

  update public.job_functions job_function
  set archived_at = statement_timestamp(), archived_by = v_actor
  where job_function.id = v_function.id
  returning job_function.* into v_function;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action
  ) values (
    v_function.workspace_id,
    v_actor,
    'job_function',
    v_function.id,
    'job_function.archived'
  );

  return jsonb_build_object(
    'id', v_function.id,
    'version', v_function.version,
    'archived_at', v_function.archived_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_operating_team(p_team_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_team public.teams%rowtype;
begin
  if auth.uid() is null or not private.can_read_team(p_team_id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;

  select team.*
  into v_team
  from public.teams team
  where team.id = p_team_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_TEAM_NOT_FOUND';
  end if;
  if not private.can_manage_operating_model(v_team.workspace_id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:operating-model:' || v_team.workspace_id::text, 0)
  );

  if v_team.archived_at is not null then
    return jsonb_build_object('id', v_team.id, 'version', v_team.version, 'archived_at', v_team.archived_at);
  end if;
  if v_team.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if v_team.is_default then
    raise exception using errcode = '23514', message = 'PTA_DEFAULT_TEAM_REQUIRED';
  end if;
  if exists (
    select 1 from public.tasks task
    where task.workspace_id = v_team.workspace_id
      and task.team_id = v_team.id
      and task.archived_at is null
  ) then
    raise exception using errcode = '23514', message = 'PTA_TEAM_HAS_ACTIVE_TASKS';
  end if;
  if exists (
    select 1
    from public.team_members member
    where member.workspace_id = v_team.workspace_id
      and member.team_id = v_team.id
      and member.removed_at is null
      and not exists (
        select 1
        from public.team_members other_membership
        join public.teams other_team
          on other_team.workspace_id = other_membership.workspace_id
          and other_team.id = other_membership.team_id
          and other_team.archived_at is null
        where other_membership.workspace_id = member.workspace_id
          and other_membership.user_id = member.user_id
          and other_membership.team_id <> member.team_id
          and other_membership.removed_at is null
      )
  ) then
    raise exception using errcode = '23514', message = 'PTA_MEMBER_REQUIRES_ACTIVE_TEAM';
  end if;

  update public.team_member_functions assignment
  set
    is_primary = false,
    archived_at = statement_timestamp(),
    archived_by = v_actor
  where assignment.workspace_id = v_team.workspace_id
    and assignment.team_id = v_team.id
    and assignment.archived_at is null;

  update public.team_members member
  set
    is_primary = false,
    removed_at = statement_timestamp(),
    removed_by = v_actor
  where member.workspace_id = v_team.workspace_id
    and member.team_id = v_team.id
    and member.removed_at is null;

  update public.team_members replacement
  set is_primary = true
  where replacement.workspace_id = v_team.workspace_id
    and replacement.removed_at is null
    and exists (
      select 1
      from public.team_members removed_membership
      where removed_membership.workspace_id = replacement.workspace_id
        and removed_membership.team_id = v_team.id
        and removed_membership.user_id = replacement.user_id
        and removed_membership.removed_at is not null
    )
    and not exists (
      select 1
      from public.team_members current_primary
      where current_primary.workspace_id = replacement.workspace_id
        and current_primary.user_id = replacement.user_id
        and current_primary.is_primary
        and current_primary.removed_at is null
    )
    and replacement.team_id = (
      select candidate.team_id
      from public.team_members candidate
      join public.teams candidate_team
        on candidate_team.workspace_id = candidate.workspace_id
        and candidate_team.id = candidate.team_id
        and candidate_team.archived_at is null
      where candidate.workspace_id = replacement.workspace_id
        and candidate.user_id = replacement.user_id
        and candidate.removed_at is null
      order by candidate_team.is_default desc, candidate.joined_at, candidate.team_id
      limit 1
    );

  update public.teams team
  set archived_at = statement_timestamp(), archived_by = v_actor
  where team.id = v_team.id
  returning team.* into v_team;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action
  ) values (
    v_team.workspace_id, v_actor, 'team', v_team.id, 'team.archived'
  );

  return jsonb_build_object('id', v_team.id, 'version', v_team.version, 'archived_at', v_team.archived_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_resource(p_resource_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_resource public.resources%rowtype;
begin
  if p_resource_id is null or not private.can_edit_resource(p_resource_id) then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_NOT_FOUND';
  end if;

  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;

  select * into v_resource
  from public.resources resource
  where resource.id = p_resource_id
    and resource.archived_at is null;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_NOT_FOUND';
  end if;

  if v_resource.version is distinct from p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  perform private.lock_resource_category_write(
    v_resource.workspace_id,
    v_resource.category_id
  );

  update public.resources
  set archived_at = clock_timestamp(), archived_by = (select auth.uid())
  where id = p_resource_id
    and archived_at is null
    and version = p_expected_version;

  if not found then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  return public.get_resource_detail(p_resource_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_resource_category(p_category_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_category public.resource_categories%rowtype;
  v_role public.workspace_role;
  v_detached_count integer;
begin
  select * into v_category
  from public.resource_categories category
  where category.id = p_category_id
    and category.archived_at is null;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_CATEGORY_NOT_FOUND';
  end if;

  v_role := private.current_workspace_role(v_category.workspace_id);
  if v_role is null
    or v_role not in (
      'owner'::public.workspace_role,
      'admin'::public.workspace_role
    ) then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_CATEGORY_NOT_FOUND';
  end if;

  if p_expected_updated_at is null
    or v_category.updated_at is distinct from p_expected_updated_at then
    raise exception using errcode = '40001', message = 'PTA_RESOURCE_CATEGORY_CONFLICT';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_category.workspace_id::text, 0)
  );
  perform private.lock_resource_category_write(
    v_category.workspace_id,
    v_category.id
  );

  update public.resource_categories category
  set archived_at = clock_timestamp(), updated_at = clock_timestamp()
  where category.id = v_category.id
    and category.updated_at = p_expected_updated_at
  returning * into v_category;

  if not found then
    raise exception using errcode = '40001', message = 'PTA_RESOURCE_CATEGORY_CONFLICT';
  end if;

  update public.resources resource
  set category_id = null
  where resource.workspace_id = v_category.workspace_id
    and resource.category_id = v_category.id;
  get diagnostics v_detached_count = row_count;

  with ordered as (
    select
      category.id,
      (
        row_number() over (order by category.position, category.name, category.id) - 1
      )::integer as next_position
    from public.resource_categories category
    where category.workspace_id = v_category.workspace_id
      and category.archived_at is null
  )
  update public.resource_categories category
  set position = ordered.next_position, updated_at = clock_timestamp()
  from ordered
  where category.id = ordered.id
    and category.position is distinct from ordered.next_position;

  return jsonb_build_object(
    'id', v_category.id,
    'archived_at', v_category.archived_at,
    'detached_resources', v_detached_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_remove_task_attachment(p_attachment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_role public.workspace_role;
  v_attachment public.task_attachments%rowtype;
  v_now timestamptz := clock_timestamp();
  v_removal_token uuid;
begin
  select attachment.*
  into v_attachment
  from public.task_attachments attachment
  where attachment.id = p_attachment_id
    and attachment.deleted_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_ATTACHMENT_NOT_FOUND';
  end if;

  v_role := private.task_collaboration_role(v_attachment.task_id);
  if v_role is null then
    raise exception using errcode = 'P0002', message = 'PTA_ATTACHMENT_NOT_FOUND';
  end if;

  if not (
    v_role in (
      'owner'::public.workspace_role,
      'admin'::public.workspace_role,
      'manager'::public.workspace_role
    )
    or (
      v_role = 'member'::public.workspace_role
      and v_attachment.uploaded_by = v_actor
    )
  ) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  if v_attachment.state = 'deleting'::public.task_attachment_state
    and v_attachment.removal_lease_expires_at > v_now then
    if v_attachment.delete_requested_by = v_actor then
      return jsonb_build_object(
        'id', v_attachment.id,
        'bucket_id', v_attachment.bucket_id,
        'object_path', v_attachment.object_path,
        'state', v_attachment.state,
        'removal_token', v_attachment.removal_token,
        'removal_lease_expires_at', v_attachment.removal_lease_expires_at
      );
    end if;

    raise exception using errcode = '55000', message = 'PTA_ATTACHMENT_REMOVAL_BUSY';
  end if;

  v_removal_token := gen_random_uuid();

  update public.task_attachments attachment
  set
    state = 'deleting'::public.task_attachment_state,
    delete_requested_by = v_actor,
    delete_requested_at = v_now,
    removal_token = v_removal_token,
    removal_lease_expires_at = v_now + interval '5 minutes'
  where attachment.id = p_attachment_id
  returning * into v_attachment;

  perform realtime.send(
    jsonb_build_object(
      'task_id', v_attachment.task_id,
      'attachment_id', v_attachment.id
    ),
    'attachment_changed',
    'task:' || v_attachment.task_id::text,
    true
  );

  return jsonb_build_object(
    'id', v_attachment.id,
    'bucket_id', v_attachment.bucket_id,
    'object_path', v_attachment.object_path,
    'state', v_attachment.state,
    'removal_token', v_attachment.removal_token,
    'removal_lease_expires_at', v_attachment.removal_lease_expires_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.bootstrap_user_workspace(p_name text, p_slug text, p_task_prefix text DEFAULT 'PTA'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user_id uuid := auth.uid(); v_workspace_id uuid;
begin
  if v_user_id is null then raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED'; end if;
  if not coalesce((select enabled from private.runtime_flags where key = 'allow_self_bootstrap'), false) then
    raise exception using errcode = '42501', message = 'PTA_BOOTSTRAP_DISABLED';
  end if;
  insert into public.profiles (id, full_name, email, locale)
  select
    u.id,
    coalesce(nullif(btrim(u.raw_user_meta_data ->> 'full_name'), ''), nullif(split_part(u.email, '@', 1), ''), 'Usuário'),
    u.email,
    coalesce(nullif(u.raw_user_meta_data ->> 'locale', ''), 'pt-BR')
  from auth.users u
  where u.id = v_user_id
  on conflict (id) do nothing;
  if not exists (select 1 from public.profiles where id = v_user_id and is_active) then
    raise exception using errcode = '42501', message = 'PTA_PROFILE_INACTIVE';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_user_id::text, 0));
  if exists (select 1 from public.workspace_members where user_id = v_user_id) then
    raise exception using errcode = '23514', message = 'PTA_WORKSPACE_ALREADY_BOOTSTRAPPED';
  end if;
  insert into public.workspaces (name, slug, task_prefix, created_by)
  values (p_name, lower(btrim(p_slug)), upper(btrim(p_task_prefix)), v_user_id)
  returning id into v_workspace_id;
  insert into public.workspace_members (workspace_id, user_id, role)
  values (v_workspace_id, v_user_id, 'owner');
  insert into public.workspace_preferences (workspace_id) values (v_workspace_id);
  insert into public.task_statuses (workspace_id, name, system_category, color, position, is_default)
  values
    (v_workspace_id, 'A fazer', 'todo', 'stone', 10, true),
    (v_workspace_id, 'Em andamento', 'in_progress', 'blue', 20, false),
    (v_workspace_id, 'Em revisão', 'review', 'violet', 30, false),
    (v_workspace_id, 'Bloqueada', 'blocked', 'red', 40, false),
    (v_workspace_id, 'Concluída', 'done', 'green', 50, false),
    (v_workspace_id, 'Cancelada', 'cancelled', 'stone', 60, false);
  insert into public.task_types (workspace_id, name, position)
  values (v_workspace_id, 'Operação', 10), (v_workspace_id, 'Criativo', 20), (v_workspace_id, 'Gestão', 30);
  return v_workspace_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_task_attachment_removal(p_attachment_id uuid, p_removal_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_role public.workspace_role;
  v_attachment public.task_attachments%rowtype;
  v_object_exists boolean;
  v_object_matches boolean;
begin
  select attachment.*
  into v_attachment
  from public.task_attachments attachment
  where attachment.id = p_attachment_id
    and attachment.deleted_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_ATTACHMENT_NOT_FOUND';
  end if;

  v_role := private.task_collaboration_role(v_attachment.task_id);
  if v_role is null
    or not (
      v_role in (
        'owner'::public.workspace_role,
        'admin'::public.workspace_role,
        'manager'::public.workspace_role
      )
      or (
        v_role = 'member'::public.workspace_role
        and v_attachment.uploaded_by = v_actor
      )
    ) then
    raise exception using errcode = 'P0002', message = 'PTA_ATTACHMENT_NOT_FOUND';
  end if;

  if v_attachment.state in (
    'pending'::public.task_attachment_state,
    'ready'::public.task_attachment_state
  ) then
    return jsonb_build_object(
      'id', v_attachment.id,
      'state', v_attachment.state
    );
  end if;

  if v_attachment.state <> 'deleting'::public.task_attachment_state
    or v_attachment.removal_token is distinct from p_removal_token
    or not (
      v_attachment.delete_requested_by = v_actor
      or v_role in (
        'owner'::public.workspace_role,
        'admin'::public.workspace_role,
        'manager'::public.workspace_role
      )
    ) then
    raise exception using errcode = 'P0002', message = 'PTA_ATTACHMENT_NOT_FOUND';
  end if;

  select
    count(*) > 0,
    coalesce(bool_and(
      case
        when object.metadata ->> 'size' ~ '^[0-9]+$' then
          (object.metadata ->> 'size')::bigint = v_attachment.file_size
          and lower(coalesce(object.metadata ->> 'mimetype', '')) = v_attachment.mime_type
        else false
      end
    ), false)
  into v_object_exists, v_object_matches
  from storage.objects object
  where object.bucket_id = v_attachment.bucket_id
    and object.name = v_attachment.object_path;

  if not v_object_exists or not v_object_matches then
    raise exception using
      errcode = '55000',
      message = 'PTA_ATTACHMENT_CANNOT_RESTORE';
  end if;

  update public.task_attachments attachment
  set
    state = case
      when ready_at is null then 'pending'::public.task_attachment_state
      else 'ready'::public.task_attachment_state
    end,
    delete_requested_by = null,
    delete_requested_at = null,
    removal_token = null,
    removal_lease_expires_at = null
  where attachment.id = p_attachment_id
  returning * into v_attachment;

  perform realtime.send(
    jsonb_build_object(
      'task_id', v_attachment.task_id,
      'attachment_id', v_attachment.id
    ),
    'attachment_changed',
    'task:' || v_attachment.task_id::text,
    true
  );

  return jsonb_build_object(
    'id', v_attachment.id,
    'state', v_attachment.state
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_workspace_invitation(p_invitation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_workspace_id uuid;
  v_actor_role public.workspace_role;
  v_invitation public.workspace_invitations%rowtype;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;

  select invitation.workspace_id
  into v_workspace_id
  from public.workspace_invitations invitation
  where invitation.id = p_invitation_id;

  if v_workspace_id is null then
    raise exception using errcode = 'P0002', message = 'PTA_INVITATION_NOT_FOUND';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:workspace-team:' || v_workspace_id::text, 0)
  );

  select invitation.*
  into v_invitation
  from public.workspace_invitations invitation
  where invitation.id = p_invitation_id
  for update;

  v_actor_role := private.current_workspace_role(v_workspace_id);
  if v_actor_role is null or v_actor_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;

  if v_invitation.accepted_at is not null then
    raise exception using errcode = '23514', message = 'PTA_INVITATION_ALREADY_ACCEPTED';
  end if;
  if v_invitation.cancelled_at is not null then
    return jsonb_build_object(
      'invitation', private.workspace_invitation_management_json(v_invitation.id)
    );
  end if;

  update public.workspace_invitations invitation
  set
    cancelled_at = statement_timestamp(),
    cancelled_by = v_actor
  where invitation.id = v_invitation.id
  returning invitation.* into v_invitation;

  insert into public.activity_logs (
    workspace_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    metadata_json
  ) values (
    v_workspace_id,
    v_actor,
    'workspace_invitation',
    v_invitation.id,
    'workspace.invitation_cancelled',
    jsonb_build_object('role', v_invitation.role)
  );

  return jsonb_build_object(
    'invitation', private.workspace_invitation_management_json(v_invitation.id)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.change_workspace_member_role(p_workspace_id uuid, p_user_id uuid, p_role workspace_role, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_role public.workspace_role;
  v_member public.workspace_members%rowtype;
  v_old_role public.workspace_role;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;
  if p_role is null or p_role = 'owner'::public.workspace_role then
    raise exception using errcode = '22023', message = 'PTA_INVALID_MEMBER_ROLE';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:workspace-team:' || p_workspace_id::text, 0)
  );
  v_actor_role := private.current_workspace_role(p_workspace_id);
  if v_actor_role is null or v_actor_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;

  select member.*
  into v_member
  from public.workspace_members member
  where member.workspace_id = p_workspace_id
    and member.user_id = p_user_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_MEMBER_NOT_FOUND';
  end if;
  if v_member.role = 'owner'::public.workspace_role then
    raise exception using errcode = '23514', message = 'PTA_LAST_OWNER_REQUIRED';
  end if;
  if v_member.removed_at is not null then
    raise exception using errcode = '23514', message = 'PTA_MEMBER_REMOVED';
  end if;
  if v_member.role = p_role then
    return jsonb_build_object(
      'member', private.workspace_member_management_json(p_workspace_id, p_user_id)
    );
  end if;
  if v_member.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  v_old_role := v_member.role;
  update public.workspace_members member
  set role = p_role
  where member.workspace_id = p_workspace_id
    and member.user_id = p_user_id
  returning member.* into v_member;

  insert into public.activity_logs (
    workspace_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    changes_json
  ) values (
    p_workspace_id,
    v_actor,
    'workspace_member',
    p_user_id,
    'workspace.member_role_changed',
    jsonb_build_object(
      'role', jsonb_build_object('from', v_old_role, 'to', p_role)
    )
  );

  return jsonb_build_object(
    'member', private.workspace_member_management_json(p_workspace_id, p_user_id)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_task_attachment(p_attachment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_role public.workspace_role;
  v_attachment public.task_attachments%rowtype;
  v_object_size bigint;
  v_object_mime_type text;
begin
  select attachment.*
  into v_attachment
  from public.task_attachments attachment
  where attachment.id = p_attachment_id
    and attachment.state in (
      'pending'::public.task_attachment_state,
      'ready'::public.task_attachment_state
    )
    and attachment.uploaded_by = v_actor
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_ATTACHMENT_NOT_FOUND';
  end if;

  v_role := private.task_collaboration_role(v_attachment.task_id);
  if v_role is null or v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role,
    'member'::public.workspace_role
  ) then
    raise exception using errcode = 'P0002', message = 'PTA_ATTACHMENT_NOT_FOUND';
  end if;

  if v_attachment.state = 'ready'::public.task_attachment_state then
    return jsonb_build_object(
      'id', v_attachment.id,
      'task_id', v_attachment.task_id,
      'state', v_attachment.state,
      'ready_at', v_attachment.ready_at
    );
  end if;

  select
    case
      when object.metadata ->> 'size' ~ '^[0-9]+$'
        then (object.metadata ->> 'size')::bigint
      else null
    end,
    lower(coalesce(object.metadata ->> 'mimetype', ''))
  into v_object_size, v_object_mime_type
  from storage.objects object
  where object.bucket_id = v_attachment.bucket_id
    and object.name = v_attachment.object_path
  limit 1;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_ATTACHMENT_OBJECT_NOT_FOUND';
  end if;
  if v_object_size is distinct from v_attachment.file_size
    or v_object_mime_type is distinct from v_attachment.mime_type then
    raise exception using errcode = '22023', message = 'PTA_ATTACHMENT_OBJECT_MISMATCH';
  end if;

  update public.task_attachments attachment
  set
    state = 'ready'::public.task_attachment_state,
    ready_at = clock_timestamp()
  where attachment.id = p_attachment_id
  returning * into v_attachment;

  perform realtime.send(
    jsonb_build_object(
      'task_id', v_attachment.task_id,
      'attachment_id', v_attachment.id
    ),
    'attachment_changed',
    'task:' || v_attachment.task_id::text,
    true
  );

  return jsonb_build_object(
    'id', v_attachment.id,
    'task_id', v_attachment.task_id,
    'state', v_attachment.state,
    'ready_at', v_attachment.ready_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.connect_week_board_column(p_workspace_id uuid, p_week_lane_key text, p_status_id uuid, p_expected_board_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role public.workspace_role := private.current_workspace_role(p_workspace_id);
  v_version integer;
  v_previous uuid;
  v_result jsonb;
begin
  if auth.uid() is null or v_role is null or v_role not in ('owner','admin','manager') then raise exception using errcode='42501',message='PTA_BOARD_CONFIGURATION_FORBIDDEN'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('pta:task-board:' || p_workspace_id::text,0));
  select version into v_version from public.task_board_settings where workspace_id=p_workspace_id and board_kind='status' for update;
  if v_version is null or v_version is distinct from p_expected_board_version then raise exception using errcode='40001',message='PTA_VERSION_CONFLICT'; end if;
  if p_status_id is not null and exists(select 1 from public.task_status_week_lane_links where workspace_id=p_workspace_id and status_id=p_status_id and week_lane_key<>p_week_lane_key) then raise exception 'PTA_BOARD_LANE_ALREADY_CONNECTED'; end if;
  select status_id into v_previous from public.task_status_week_lane_links where workspace_id=p_workspace_id and week_lane_key=p_week_lane_key;
  if v_previous is not null and v_previous is distinct from p_status_id then
    v_result := public.set_task_board_lane_link(p_workspace_id,v_previous,p_week_lane_key,'both',false,v_version);
    v_version := (v_result#>>'{status_board,version}')::integer;
  end if;
  if p_status_id is not null then
    return public.set_task_board_lane_link(p_workspace_id,p_status_id,p_week_lane_key,'both',true,v_version);
  end if;
  return public.get_task_board_configuration(p_workspace_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_context_task(p_workspace_id uuid, p_context_type text, p_context_id uuid, p_title text, p_status_id uuid DEFAULT NULL::uuid, p_priority task_priority DEFAULT 'medium'::task_priority, p_due_date date DEFAULT NULL::date, p_primary_assignee_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_status_id uuid;
  v_product_id uuid;
  v_event_id uuid;
  v_task public.tasks%rowtype;
begin
  v_role := private.current_workspace_role(p_workspace_id);
  if v_actor is null or v_role is null or v_role = 'viewer' then raise exception using errcode = '42501', message = 'PTA_FORBIDDEN'; end if;
  if p_context_type = 'product' then
    select id into v_product_id from public.products where id = p_context_id and workspace_id = p_workspace_id and archived_at is null;
    if v_product_id is null then raise exception using errcode = '23514', message = 'PTA_PRODUCT_NOT_ACTIVE'; end if;
  elsif p_context_type = 'event' then
    select id, product_id into v_event_id, v_product_id from public.events where id = p_context_id and workspace_id = p_workspace_id and archived_at is null;
    if v_event_id is null then raise exception using errcode = '23514', message = 'PTA_EVENT_NOT_ACTIVE'; end if;
  else
    raise exception using errcode = '22023', message = 'PTA_CONTEXT_INVALID';
  end if;
  select coalesce(p_status_id, (select id from public.task_statuses where workspace_id = p_workspace_id and is_default and is_active order by position limit 1)) into v_status_id;
  if v_status_id is null then raise exception using errcode = '23514', message = 'PTA_DEFAULT_STATUS_REQUIRED'; end if;
  if not exists (
    select 1 from public.task_statuses
    where id = v_status_id and workspace_id = p_workspace_id and is_active
  ) then raise exception using errcode = '23514', message = 'PTA_STATUS_NOT_ACTIVE'; end if;
  if p_primary_assignee_id is not null then
    if v_role = 'member' and p_primary_assignee_id <> v_actor then raise exception using errcode = '42501', message = 'PTA_FORBIDDEN'; end if;
    if not exists (
      select 1 from public.workspace_members wm
      join public.profiles profile on profile.id = wm.user_id and profile.is_active
      where wm.workspace_id = p_workspace_id
        and wm.user_id = p_primary_assignee_id
        and wm.status = 'active'
        and wm.role <> 'viewer'
    ) then raise exception using errcode = '23514', message = 'PTA_ASSIGNEE_NOT_ACTIVE_MEMBER'; end if;
  end if;
  insert into public.tasks (workspace_id, title, status_id, priority, product_id, event_id, due_date, created_by, updated_by)
  values (p_workspace_id, p_title, v_status_id, p_priority, v_product_id, v_event_id, p_due_date, v_actor, v_actor)
  returning * into v_task;
  if p_primary_assignee_id is not null then
    insert into public.task_assignees (workspace_id, task_id, user_id, is_primary, assigned_by)
    values (p_workspace_id, v_task.id, p_primary_assignee_id, true, v_actor);
  end if;
  return jsonb_build_object('id', v_task.id, 'task_number', v_task.task_number, 'version', v_task.version);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_event_milestone(p_event_id uuid, p_title text, p_due_date date DEFAULT NULL::date, p_phase text DEFAULT 'preparation'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_event public.events%rowtype;
  v_milestone public.event_milestones%rowtype;
  v_role public.workspace_role;
begin
  select * into v_event from public.events where id = p_event_id and archived_at is null;
  if not found then raise exception using errcode = 'P0002', message = 'PTA_EVENT_NOT_FOUND'; end if;
  v_role := private.current_workspace_role(v_event.workspace_id);
  if v_actor is null or v_role is null or v_role not in ('owner', 'admin', 'manager') then raise exception using errcode = '42501', message = 'PTA_FORBIDDEN'; end if;
  insert into public.event_milestones (workspace_id, event_id, title, due_date, phase, position, created_by, updated_by)
  values (v_event.workspace_id, v_event.id, p_title, p_due_date, p_phase,
    coalesce((select max(position) + 1000 from public.event_milestones where event_id = v_event.id), 1000), v_actor, v_actor)
  returning * into v_milestone;
  insert into public.activity_logs (workspace_id, actor_id, entity_type, entity_id, action, metadata_json)
  values (v_event.workspace_id, v_actor, 'event_milestone', v_milestone.id, 'event.milestone_created', jsonb_build_object('event_id', v_event.id));
  return jsonb_build_object('id', v_milestone.id, 'version', v_milestone.version);
end;
$function$

