CREATE OR REPLACE FUNCTION public.create_global_task(p_workspace_id uuid, p_title text, p_status_id uuid DEFAULT NULL::uuid, p_priority task_priority DEFAULT 'medium'::task_priority, p_due_date date DEFAULT NULL::date, p_due_time time without time zone DEFAULT NULL::time without time zone, p_primary_assignee_id uuid DEFAULT NULL::uuid, p_type_id uuid DEFAULT NULL::uuid, p_product_id uuid DEFAULT NULL::uuid, p_event_id uuid DEFAULT NULL::uuid, p_description jsonb DEFAULT NULL::jsonb, p_blocked_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_status_id uuid;
  v_status_category public.task_status_category;
  v_type_id uuid;
  v_product_id uuid;
  v_event_id uuid;
  v_event_product_id uuid;
  v_description_json jsonb := coalesce(
    p_description,
    jsonb_build_object('type', 'doc', 'content', jsonb_build_array())
  );
  v_task public.tasks%rowtype;
begin
  v_role := private.current_workspace_role(p_workspace_id);
  if v_actor is null
     or v_role is null
     or v_role not in (
       'owner'::public.workspace_role,
       'admin'::public.workspace_role,
       'manager'::public.workspace_role,
       'member'::public.workspace_role
     ) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  if p_title is null or char_length(btrim(p_title)) not between 3 and 180 then
    raise exception using errcode = '22023', message = 'PTA_TASK_TITLE_INVALID';
  end if;

  if p_due_time is not null and p_due_date is null then
    raise exception using errcode = '22023', message = 'PTA_DUE_DATE_REQUIRED_FOR_TIME';
  end if;

  if p_status_id is null then
    select status.id, status.system_category
    into v_status_id, v_status_category
    from public.task_statuses status
    where status.workspace_id = p_workspace_id
      and status.is_default
      and status.is_active
    order by status.position, status.id
    limit 1;

    if v_status_id is null then
      raise exception using errcode = '23514', message = 'PTA_DEFAULT_STATUS_REQUIRED';
    end if;
  else
    select status.id, status.system_category
    into v_status_id, v_status_category
    from public.task_statuses status
    where status.workspace_id = p_workspace_id
      and status.id = p_status_id
      and status.is_active;

    if v_status_id is null then
      raise exception using errcode = '23514', message = 'PTA_STATUS_NOT_ACTIVE';
    end if;
  end if;

  if v_status_category = 'blocked'::public.task_status_category then
    if nullif(btrim(p_blocked_reason), '') is null then
      raise exception using errcode = '23514', message = 'PTA_BLOCKED_REASON_REQUIRED';
    end if;
    if char_length(btrim(p_blocked_reason)) > 1000 then
      raise exception using errcode = '22023', message = 'PTA_BLOCKED_REASON_TOO_LONG';
    end if;
  end if;

  if p_type_id is not null then
    select task_type.id
    into v_type_id
    from public.task_types task_type
    where task_type.workspace_id = p_workspace_id
      and task_type.id = p_type_id
      and task_type.is_active;

    if v_type_id is null then
      raise exception using errcode = '23514', message = 'PTA_TYPE_NOT_ACTIVE';
    end if;
  end if;

  if p_product_id is not null then
    select product.id
    into v_product_id
    from public.products product
    where product.workspace_id = p_workspace_id
      and product.id = p_product_id
      and product.archived_at is null;

    if v_product_id is null then
      raise exception using errcode = '23514', message = 'PTA_PRODUCT_NOT_ACTIVE';
    end if;
  end if;

  if p_event_id is not null then
    select event.id, event.product_id
    into v_event_id, v_event_product_id
    from public.events event
    where event.workspace_id = p_workspace_id
      and event.id = p_event_id
      and event.archived_at is null;

    if v_event_id is null then
      raise exception using errcode = '23514', message = 'PTA_EVENT_NOT_ACTIVE';
    end if;

    if v_event_product_id is not null then
      if v_product_id is null then
        v_product_id := v_event_product_id;
      elsif v_product_id <> v_event_product_id then
        raise exception using errcode = '23514', message = 'PTA_EVENT_PRODUCT_MISMATCH';
      end if;
    end if;
  end if;

  if v_product_id is not null and not exists (
    select 1
    from public.products product
    where product.workspace_id = p_workspace_id
      and product.id = v_product_id
      and product.archived_at is null
  ) then
    raise exception using errcode = '23514', message = 'PTA_PRODUCT_NOT_ACTIVE';
  end if;

  if p_primary_assignee_id is not null then
    if v_role = 'member'::public.workspace_role
       and p_primary_assignee_id <> v_actor then
      raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
    end if;

    if not exists (
      select 1
      from public.workspace_members member
      join public.profiles profile
        on profile.id = member.user_id
        and profile.is_active
      where member.workspace_id = p_workspace_id
        and member.user_id = p_primary_assignee_id
        and member.status = 'active'
        and member.role <> 'viewer'::public.workspace_role
    ) then
      raise exception using errcode = '23514', message = 'PTA_ASSIGNEE_NOT_ACTIVE_MEMBER';
    end if;
  end if;

  if not private.is_valid_task_description(v_description_json) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_TASK_DESCRIPTION';
  end if;

  if octet_length(v_description_json::text) > 256000 then
    raise exception using errcode = '22023', message = 'PTA_DESCRIPTION_TOO_LARGE';
  end if;

  insert into public.tasks (
    workspace_id,
    title,
    description_json,
    status_id,
    type_id,
    priority,
    product_id,
    event_id,
    due_date,
    due_time,
    blocked_reason,
    created_by,
    updated_by
  ) values (
    p_workspace_id,
    btrim(p_title),
    v_description_json,
    v_status_id,
    v_type_id,
    coalesce(p_priority, 'medium'::public.task_priority),
    v_product_id,
    v_event_id,
    p_due_date,
    p_due_time,
    case
      when v_status_category = 'blocked'::public.task_status_category
        then btrim(p_blocked_reason)
      else null
    end,
    v_actor,
    v_actor
  )
  returning * into v_task;

  if p_primary_assignee_id is not null then
    insert into public.task_assignees (
      workspace_id,
      task_id,
      user_id,
      is_primary,
      assigned_by
    ) values (
      p_workspace_id,
      v_task.id,
      p_primary_assignee_id,
      true,
      v_actor
    );
  end if;

  return jsonb_build_object(
    'id', v_task.id,
    'task_number', v_task.task_number,
    'version', v_task.version,
    'status_id', v_task.status_id,
    'priority', v_task.priority,
    'due_date', v_task.due_date,
    'due_time', v_task.due_time,
    'primary_assignee_id', p_primary_assignee_id,
    'type_id', v_task.type_id,
    'product_id', v_task.product_id,
    'event_id', v_task.event_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_operating_team(p_workspace_id uuid, p_name text, p_slug text, p_description text DEFAULT NULL::text, p_color text DEFAULT 'blue'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_team public.teams%rowtype;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if not private.can_manage_operating_model(p_workspace_id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 2 and 100 then
    raise exception using errcode = '22023', message = 'PTA_TEAM_NAME_INVALID';
  end if;
  if p_slug is null or lower(btrim(p_slug)) !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then
    raise exception using errcode = '22023', message = 'PTA_TEAM_SLUG_INVALID';
  end if;
  if p_color is null or lower(btrim(p_color)) !~ '^[a-z][a-z0-9-]{1,31}$' then
    raise exception using errcode = '22023', message = 'PTA_TEAM_COLOR_INVALID';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:operating-model:' || p_workspace_id::text, 0)
  );

  insert into public.teams (
    workspace_id,
    name,
    slug,
    description,
    color,
    created_by
  ) values (
    p_workspace_id,
    btrim(p_name),
    lower(btrim(p_slug)),
    nullif(btrim(p_description), ''),
    lower(btrim(p_color)),
    v_actor
  )
  returning * into v_team;

  insert into public.team_members (
    workspace_id,
    team_id,
    user_id,
    role,
    is_primary,
    added_by
  ) values (
    p_workspace_id,
    v_team.id,
    v_actor,
    'lead'::public.team_member_role,
    false,
    v_actor
  );

  insert into public.activity_logs (
    workspace_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    metadata_json
  ) values (
    p_workspace_id,
    v_actor,
    'team',
    v_team.id,
    'team.created',
    jsonb_build_object('name', v_team.name, 'slug', v_team.slug)
  );

  return jsonb_build_object(
    'id', v_team.id,
    'workspace_id', v_team.workspace_id,
    'name', v_team.name,
    'slug', v_team.slug,
    'description', v_team.description,
    'color', v_team.color,
    'is_default', v_team.is_default,
    'version', v_team.version
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_operating_team_workspace(p_workspace_id uuid, p_name text, p_slug text, p_description text DEFAULT NULL::text, p_color text DEFAULT 'blue'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_team jsonb; v_event jsonb; v_version integer;
begin
  v_team := public.create_operating_team(p_workspace_id,p_name,p_slug,p_description,p_color);
  v_event := public.create_team_project(p_workspace_id,(v_team->>'id')::uuid,p_name);
  update public.teams set workspace_event_id = (v_event->>'id')::uuid
    where workspace_id = p_workspace_id and id = (v_team->>'id')::uuid returning version into v_version;
  return jsonb_build_object('team', v_team || jsonb_build_object('workspace_event_id',v_event->>'id','version',v_version));
end;
$function$

CREATE OR REPLACE FUNCTION public.create_product_operational(p_workspace_id uuid, p_name text, p_owner_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'active'::text, p_description text DEFAULT NULL::text, p_member_ids uuid[] DEFAULT ARRAY[]::uuid[])
