CREATE OR REPLACE FUNCTION public.create_resource(p_workspace_id uuid, p_title text, p_external_url text, p_resource_type resource_type DEFAULT 'link'::resource_type, p_description text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_is_restricted boolean DEFAULT false, p_task_ids uuid[] DEFAULT '{}'::uuid[], p_product_ids uuid[] DEFAULT '{}'::uuid[], p_event_ids uuid[] DEFAULT '{}'::uuid[], p_tag_ids uuid[] DEFAULT '{}'::uuid[], p_permissions jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_role public.workspace_role;
  v_resource_id uuid;
  v_task_ids uuid[] := array(select distinct value from unnest(coalesce(p_task_ids, '{}'::uuid[])) value);
  v_product_ids uuid[] := array(select distinct value from unnest(coalesce(p_product_ids, '{}'::uuid[])) value);
  v_event_ids uuid[] := array(select distinct value from unnest(coalesce(p_event_ids, '{}'::uuid[])) value);
  v_tag_ids uuid[] := array(select distinct value from unnest(coalesce(p_tag_ids, '{}'::uuid[])) value);
begin
  v_role := private.current_workspace_role(p_workspace_id);

  if p_workspace_id is null or v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role
  ) then
    raise exception using errcode = 'P0002', message = 'PTA_WORKSPACE_NOT_FOUND';
  end if;

  if char_length(btrim(coalesce(p_title, ''))) not between 2 and 180 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_TITLE';
  end if;

  if p_description is not null and char_length(p_description) > 5000 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_DESCRIPTION';
  end if;

  if not private.is_valid_resource_url(p_external_url) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_URL';
  end if;

  if p_permissions is null
    or jsonb_typeof(p_permissions) is distinct from 'array' then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_PERMISSIONS';
  end if;

  if v_role = 'manager'::public.workspace_role and jsonb_array_length(p_permissions) > 0 then
    raise exception using errcode = 'P0002', message = 'PTA_WORKSPACE_NOT_FOUND';
  end if;

  insert into public.resources (
    workspace_id,
    category_id,
    resource_type,
    title,
    description,
    external_url,
    is_restricted,
    created_by,
    updated_by
  ) values (
    p_workspace_id,
    p_category_id,
    p_resource_type,
    p_title,
    p_description,
    p_external_url,
    p_is_restricted,
    v_actor,
    v_actor
  ) returning id into v_resource_id;

  perform private.replace_resource_relations(
    p_workspace_id,
    v_resource_id,
    v_task_ids,
    v_product_ids,
    v_event_ids,
    v_tag_ids,
    p_permissions
  );

  return public.get_resource_detail(v_resource_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_resource_category(p_workspace_id uuid, p_name text, p_color text DEFAULT 'stone'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_role public.workspace_role;
  v_name text := btrim(coalesce(p_name, ''));
  v_color text := lower(btrim(coalesce(p_color, 'stone')));
  v_base_slug text;
  v_slug text;
  v_suffix integer := 2;
  v_position integer;
  v_category public.resource_categories%rowtype;
begin
  v_role := private.current_workspace_role(p_workspace_id);

  if p_workspace_id is null
    or v_role is null
    or v_role not in (
      'owner'::public.workspace_role,
      'admin'::public.workspace_role,
      'manager'::public.workspace_role
    ) then
    raise exception using errcode = 'P0002', message = 'PTA_WORKSPACE_NOT_FOUND';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_workspace_id::text, 0)
  );

  if char_length(v_name) not between 2 and 80 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_CATEGORY_NAME';
  end if;

  if v_color not in (
    'stone',
    'blue',
    'cyan',
    'green',
    'lime',
    'orange',
    'pink',
    'purple',
    'red',
    'yellow'
  ) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_CATEGORY_COLOR';
  end if;

  if exists (
    select 1
    from public.resource_categories category
    where category.workspace_id = p_workspace_id
      and lower(category.name) = lower(v_name)
  ) then
    raise exception using errcode = '23505', message = 'PTA_RESOURCE_CATEGORY_EXISTS';
  end if;

  v_base_slug := trim(
    both '-' from regexp_replace(
      lower(extensions.unaccent(v_name)),
      '[^a-z0-9]+',
      '-',
      'g'
    )
  );

  if v_base_slug = '' then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_CATEGORY_NAME';
  end if;

  v_slug := v_base_slug;
  while exists (
    select 1
    from public.resource_categories category
    where category.workspace_id = p_workspace_id
      and category.slug = v_slug
  ) loop
    v_slug := v_base_slug || '-' || v_suffix::text;
    v_suffix := v_suffix + 1;
  end loop;

  select coalesce(max(category.position), -1) + 1
  into v_position
  from public.resource_categories category
  where category.workspace_id = p_workspace_id
    and category.archived_at is null;

  insert into public.resource_categories (
    workspace_id,
    name,
    slug,
    color,
    position,
    created_by
  ) values (
    p_workspace_id,
    v_name,
    v_slug,
    v_color,
    v_position,
    v_actor
  )
  returning * into v_category;

  return jsonb_build_object(
    'id', v_category.id,
    'name', v_category.name,
    'color', v_category.color
  );
exception
  when unique_violation then
    raise exception using errcode = '23505', message = 'PTA_RESOURCE_CATEGORY_EXISTS';
end;
$function$

CREATE OR REPLACE FUNCTION public.create_resource_tag(p_workspace_id uuid, p_name text, p_color text DEFAULT 'stone'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_role public.workspace_role;
  v_name text := btrim(coalesce(p_name, ''));
  v_color text := lower(btrim(coalesce(p_color, 'stone')));
  v_tag public.tags%rowtype;
begin
  v_role := private.current_workspace_role(p_workspace_id);

  if p_workspace_id is null
    or v_role is null
    or v_role not in (
      'owner'::public.workspace_role,
      'admin'::public.workspace_role,
      'manager'::public.workspace_role
    ) then
    raise exception using errcode = 'P0002', message = 'PTA_WORKSPACE_NOT_FOUND';
  end if;

  if char_length(v_name) not between 1 and 60 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_TAG_NAME';
  end if;

  if v_color not in (
    'stone', 'blue', 'cyan', 'green', 'lime',
    'orange', 'pink', 'purple', 'red', 'yellow'
  ) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_TAG_COLOR';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('resource-tag:' || p_workspace_id::text, 0)
  );

  if exists (
    select 1
    from public.tags tag
    where tag.workspace_id = p_workspace_id
      and lower(tag.name) = lower(v_name)
  ) then
    raise exception using errcode = '23505', message = 'PTA_RESOURCE_TAG_EXISTS';
  end if;

  insert into public.tags (workspace_id, name, color, created_by)
  values (p_workspace_id, v_name, v_color, v_actor)
  returning * into v_tag;

  return jsonb_build_object(
    'id', v_tag.id,
    'label', v_tag.name,
    'meta', null,
    'color', v_tag.color
  );
exception
  when unique_violation then
    raise exception using errcode = '23505', message = 'PTA_RESOURCE_TAG_EXISTS';
end;
$function$

CREATE OR REPLACE FUNCTION public.create_task(p_workspace_id uuid, p_title text, p_status_id uuid DEFAULT NULL::uuid, p_priority task_priority DEFAULT 'medium'::task_priority, p_due_date date DEFAULT NULL::date, p_due_time time without time zone DEFAULT NULL::time without time zone, p_primary_assignee_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user_id uuid := auth.uid(); v_status_id uuid; v_task public.tasks%rowtype;
begin
  if v_user_id is null or not private.can_create_tasks(p_workspace_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  select coalesce(p_status_id, (
    select id from public.task_statuses
    where workspace_id = p_workspace_id and is_default and is_active
    order by position limit 1
  )) into v_status_id;
  if v_status_id is null then
    raise exception using errcode = '23514', message = 'PTA_DEFAULT_STATUS_REQUIRED';
  end if;
  if p_primary_assignee_id is not null then
    if private.current_workspace_role(p_workspace_id) = 'member'
       and p_primary_assignee_id <> v_user_id then
      raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
    end if;
    if not exists (
      select 1 from public.workspace_members wm
      join public.profiles p on p.id = wm.user_id and p.is_active
      where wm.workspace_id = p_workspace_id
        and wm.user_id = p_primary_assignee_id
        and wm.status = 'active'
        and wm.role <> 'viewer'
    ) then
      raise exception using errcode = '23514', message = 'PTA_ASSIGNEE_NOT_ACTIVE_MEMBER';
    end if;
  end if;
  insert into public.tasks (
    workspace_id, title, status_id, priority, due_date, due_time, created_by, updated_by
  ) values (
    p_workspace_id, p_title, v_status_id, p_priority, p_due_date, p_due_time, v_user_id, v_user_id
  ) returning * into v_task;
  if p_primary_assignee_id is not null then
    insert into public.task_assignees (workspace_id, task_id, user_id, is_primary, assigned_by)
    values (p_workspace_id, v_task.id, p_primary_assignee_id, true, v_user_id);
  end if;
  return jsonb_build_object('id', v_task.id, 'task_number', v_task.task_number, 'version', v_task.version);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_task_checklist(p_task_id uuid, p_title text, p_position numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_workspace_id uuid;
  v_role public.workspace_role;
  v_position numeric;
  v_checklist public.task_checklists%rowtype;
begin
  select task.workspace_id
  into v_workspace_id
  from public.tasks task
  where task.id = p_task_id
    and task.archived_at is null;

  v_role := private.task_collaboration_role(p_task_id);
  if v_workspace_id is null or v_role is null then
    raise exception using errcode = 'P0002', message = 'PTA_TASK_NOT_FOUND';
  end if;
  if not private.can_edit_task(p_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_title is null or char_length(btrim(p_title)) not between 1 and 200 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_CHECKLIST_TITLE';
  end if;
  if p_position is not null and p_position < 0 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_CHECKLIST_POSITION';
  end if;

  select coalesce(
    p_position,
    coalesce(max(checklist.position), 0) + 1000
  )
  into v_position
  from public.task_checklists checklist
  where checklist.workspace_id = v_workspace_id
    and checklist.task_id = p_task_id;

  insert into public.task_checklists (
    workspace_id,
    task_id,
    title,
    position,
    created_by
  ) values (
    v_workspace_id,
    p_task_id,
    btrim(p_title),
    v_position,
    v_actor
  )
  returning * into v_checklist;

  return jsonb_build_object(
    'id', v_checklist.id,
    'task_id', v_checklist.task_id,
    'title', v_checklist.title,
    'position', v_checklist.position,
    'created_by', v_checklist.created_by,
    'created_at', v_checklist.created_at,
    'updated_at', v_checklist.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_task_custom_field(p_workspace_id uuid, p_name text, p_field_type task_custom_field_type, p_options text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_field public.task_custom_field_definitions%rowtype;
  v_option text;
  v_index integer := 0;
begin
  if v_actor is null
    or private.current_workspace_role(p_workspace_id) not in ('owner', 'admin', 'manager') then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 2 and 60 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_CUSTOM_FIELD_NAME';
  end if;
  if (
    select count(*)
    from public.task_custom_field_definitions field
    where field.workspace_id = p_workspace_id and field.archived_at is null
  ) >= 12 then
    raise exception using errcode = '23514', message = 'PTA_CUSTOM_FIELD_LIMIT';
  end if;
  if p_field_type = 'single_select' and coalesce(array_length(p_options, 1), 0) not between 1 and 30 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_CUSTOM_FIELD_OPTIONS';
  end if;
  if p_field_type <> 'single_select' and coalesce(array_length(p_options, 1), 0) > 0 then
    raise exception using errcode = '22023', message = 'PTA_OPTIONS_NOT_ALLOWED';
  end if;

  insert into public.task_custom_field_definitions (
    workspace_id, name, field_type, position, created_by, updated_by
  ) values (
    p_workspace_id,
    btrim(p_name),
    p_field_type,
    coalesce((select max(field.position) + 1000 from public.task_custom_field_definitions field where field.workspace_id = p_workspace_id), 1000),
    v_actor,
    v_actor
  ) returning * into v_field;

  foreach v_option in array coalesce(p_options, '{}'::text[]) loop
    v_index := v_index + 1;
    if char_length(btrim(v_option)) not between 1 and 60 then
      raise exception using errcode = '22023', message = 'PTA_INVALID_CUSTOM_FIELD_OPTION';
    end if;
    insert into public.task_custom_field_options (workspace_id, field_id, label, position)
    values (p_workspace_id, v_field.id, btrim(v_option), v_index * 1000);
  end loop;

  return jsonb_build_object('id', v_field.id, 'name', v_field.name, 'type', v_field.field_type);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_task_subtask(p_parent_task_id uuid, p_title text, p_status_id uuid DEFAULT NULL::uuid, p_priority task_priority DEFAULT 'medium'::task_priority, p_due_date date DEFAULT NULL::date, p_due_time time without time zone DEFAULT NULL::time without time zone, p_primary_assignee_id uuid DEFAULT NULL::uuid, p_type_id uuid DEFAULT NULL::uuid, p_product_id uuid DEFAULT NULL::uuid, p_event_id uuid DEFAULT NULL::uuid, p_description jsonb DEFAULT NULL::jsonb, p_blocked_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_parent public.tasks%rowtype;
  v_created jsonb;
  v_child_id uuid;
begin
  select task.* into v_parent
  from public.tasks task
  where task.id = p_parent_task_id
    and task.archived_at is null
  for update;

  if not found or v_actor is null or not private.can_edit_task(p_parent_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  if p_primary_assignee_id is not null and not exists (
    select 1
    from public.workspace_members member
    join public.profiles profile
      on profile.id = member.user_id and profile.is_active
    where member.workspace_id = v_parent.workspace_id
      and member.user_id = p_primary_assignee_id
      and member.status = 'active'
      and member.removed_at is null
      and member.role <> 'viewer'::public.workspace_role
  ) then
    raise exception using errcode = '23514', message = 'PTA_ASSIGNEE_NOT_ACTIVE_MEMBER';
  end if;

  v_created := public.create_global_task(
    p_workspace_id => v_parent.workspace_id,
    p_title => p_title,
    p_status_id => p_status_id,
    p_priority => p_priority,
    p_due_date => p_due_date,
    p_due_time => p_due_time,
    p_primary_assignee_id => null,
    p_type_id => p_type_id,
    p_product_id => p_product_id,
    p_event_id => p_event_id,
    p_description => p_description,
    p_blocked_reason => p_blocked_reason
  );
  v_child_id := (v_created ->> 'id')::uuid;

  if p_primary_assignee_id is not null then
    insert into public.task_assignees (
      workspace_id, task_id, user_id, is_primary, assigned_by
    ) values (
      v_parent.workspace_id, v_child_id, p_primary_assignee_id, true, v_actor
    );
  end if;

  insert into public.task_subtasks (
    workspace_id, parent_task_id, child_task_id, created_by
  ) values (
    v_parent.workspace_id, v_parent.id, v_child_id, v_actor
  );

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    v_parent.workspace_id,
    v_actor,
    'task',
    v_parent.id,
    'task.subtask_created',
    jsonb_build_object('child_task_id', v_child_id, 'title', btrim(p_title))
  );

  return v_created || jsonb_build_object(
    'parent_task_id', v_parent.id,
    'primary_assignee_id', p_primary_assignee_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_team_project(p_workspace_id uuid, p_team_id uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_project jsonb;
begin
  if auth.uid() is null or not private.can_manage_operating_model(p_workspace_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_name is null or length(btrim(p_name)) < 2 or length(btrim(p_name)) > 200 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_NAME';
  end if;
  if p_team_id is not null then
    perform 1 from public.teams where workspace_id = p_workspace_id and id = p_team_id
      and archived_at is null for share;
    if not found then raise exception using errcode = '23514', message = 'PTA_TEAM_NOT_ACTIVE'; end if;
  end if;
  v_project := public.create_event_operational(p_workspace_id => p_workspace_id, p_name => btrim(p_name));
  if p_team_id is not null then
    v_project := public.set_project_team(p_workspace_id,(v_project->>'id')::uuid,p_team_id,(v_project->>'version')::integer);
  end if;
  return v_project;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_workspace_invitation(p_workspace_id uuid, p_email text, p_role workspace_role, p_expires_in_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_role public.workspace_role;
  v_email text := lower(btrim(p_email));
  v_raw_token text;
  v_token_hash text;
  v_invitation public.workspace_invitations%rowtype;
  v_was_existing boolean := false;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if p_workspace_id is null
     or v_email is null
     or char_length(v_email) not between 3 and 320
     or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception using errcode = '22023', message = 'PTA_INVALID_INVITATION_EMAIL';
  end if;
  if p_role is null or p_role = 'owner'::public.workspace_role then
    raise exception using errcode = '22023', message = 'PTA_INVALID_INVITATION_ROLE';
  end if;
  if p_expires_in_days is null or p_expires_in_days not between 1 and 30 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_INVITATION_EXPIRY';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:workspace-team:' || p_workspace_id::text, 0)
  );
  v_actor_role := private.current_workspace_role(p_workspace_id);
  if v_actor_role is null or v_actor_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;

  if exists (
    select 1
    from public.workspace_members member
    join public.profiles profile on profile.id = member.user_id
    where member.workspace_id = p_workspace_id
      and member.status = 'active'::public.membership_status
      and member.removed_at is null
      and lower(btrim(profile.email)) = v_email
  ) then
    raise exception using errcode = '23514', message = 'PTA_MEMBER_ALREADY_ACTIVE';
  end if;

  v_raw_token := encode(extensions.gen_random_bytes(32), 'hex');
  v_token_hash := encode(extensions.digest(v_raw_token, 'sha256'), 'hex');

  select invitation.*
  into v_invitation
  from public.workspace_invitations invitation
  where invitation.workspace_id = p_workspace_id
    and invitation.email = v_email
    and invitation.accepted_at is null
    and invitation.cancelled_at is null
  for update;

  if found then
    v_was_existing := true;
    update public.workspace_invitations invitation
    set
      role = p_role,
      token_hash = v_token_hash,
      invited_by = v_actor,
      expires_at = statement_timestamp() + make_interval(days => p_expires_in_days)
    where invitation.id = v_invitation.id
    returning invitation.* into v_invitation;
  else
    insert into public.workspace_invitations (
      workspace_id,
      email,
      role,
      token_hash,
      invited_by,
      expires_at
    ) values (
      p_workspace_id,
      v_email,
      p_role,
      v_token_hash,
      v_actor,
      statement_timestamp() + make_interval(days => p_expires_in_days)
    )
    returning * into v_invitation;
  end if;

  insert into public.activity_logs (
    workspace_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    metadata_json
  ) values (
    p_workspace_id,
    v_actor,
    'workspace_invitation',
    v_invitation.id,
    case when v_was_existing then 'workspace.invitation_refreshed' else 'workspace.invitation_created' end,
    jsonb_build_object(
      'role', p_role,
      'expires_at', v_invitation.expires_at
    )
  );

  return jsonb_build_object(
    'invitation', private.workspace_invitation_management_json(v_invitation.id),
    'raw_token', v_raw_token
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_event_milestone(p_workspace_id uuid, p_milestone_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_milestone public.event_milestones%rowtype;
begin
  if v_actor is null
     or coalesce(private.current_workspace_role(p_workspace_id) not in ('owner', 'admin', 'manager'), true) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  select milestone.* into v_milestone
  from public.event_milestones milestone
  where milestone.workspace_id = p_workspace_id
    and milestone.id = p_milestone_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_MILESTONE_NOT_FOUND';
  end if;
  if v_milestone.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  delete from public.event_milestones milestone
  where milestone.workspace_id = p_workspace_id
    and milestone.id = p_milestone_id
    and milestone.version = p_expected_version;
  if not found then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    p_workspace_id, v_actor, 'event_milestone', v_milestone.id,
    'event.milestone_deleted',
    jsonb_build_object(
      'event_id', v_milestone.event_id,
      'title', v_milestone.title,
      'due_date', v_milestone.due_date,
      'event_phase_id', v_milestone.event_phase_id
    )
  );

  return jsonb_build_object('id', v_milestone.id, 'deleted', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_task_comment(p_comment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_comment public.task_comments%rowtype;
begin
  select task_comment.*
  into v_comment
  from public.task_comments task_comment
  where task_comment.id = p_comment_id
    and task_comment.deleted_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_COMMENT_NOT_FOUND';
  end if;
  v_role := private.task_collaboration_role(v_comment.task_id);
  if v_role is null then
    raise exception using errcode = 'P0002', message = 'PTA_COMMENT_NOT_FOUND';
  end if;
  if not (
    v_role in (
      'owner'::public.workspace_role,
      'admin'::public.workspace_role,
      'manager'::public.workspace_role
    )
    or (
      v_role = 'member'::public.workspace_role
      and v_comment.created_by = v_actor
    )
  ) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  update public.task_comments task_comment
  set
    body = null,
    deleted_by = v_actor,
    deleted_at = clock_timestamp(),
    updated_at = clock_timestamp()
  where task_comment.id = p_comment_id
  returning * into v_comment;

  return jsonb_build_object(
    'id', v_comment.id,
    'task_id', v_comment.task_id,
    'deleted', true,
    'deleted_at', v_comment.deleted_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_week_board_column(p_workspace_id uuid, p_lane_key text, p_destination_key text, p_expected_board_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role public.workspace_role := private.current_workspace_role(p_workspace_id);
  v_version integer; v_task record; v_position numeric; v_count integer:=0;
begin
  if auth.uid() is null or v_role is null or v_role not in ('owner','admin','manager') then
    raise exception using errcode='42501',message='PTA_BOARD_CONFIGURATION_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_workspace_id::text,713421));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('pta:task-board:'||p_workspace_id::text,0));
  select version into v_version from public.task_board_settings
    where workspace_id=p_workspace_id and board_kind='week' for update;
  if v_version is null or v_version is distinct from p_expected_board_version then
    raise exception using errcode='40001',message='PTA_VERSION_CONFLICT';
  end if;
  if p_lane_key='scheduled' or not exists(select 1 from public.task_week_lanes
    where workspace_id=p_workspace_id and lane_key=p_lane_key and is_active) then
    raise exception 'PTA_BOARD_COLUMN_NOT_FOUND';
  end if;
  if p_destination_key=p_lane_key or p_destination_key='scheduled' or not exists(
    select 1 from public.task_week_lanes where workspace_id=p_workspace_id and lane_key=p_destination_key and is_active
  ) then raise exception 'PTA_BOARD_DESTINATION_REQUIRED'; end if;
  if exists(select 1 from public.task_status_week_lane_links link join public.task_statuses status
    on status.workspace_id=link.workspace_id and status.id=link.status_id
    where link.workspace_id=p_workspace_id and link.week_lane_key=p_destination_key and status.system_category='blocked'
  ) then raise exception 'PTA_BOARD_DESTINATION_BLOCKED'; end if;
  delete from public.task_status_week_lane_links where workspace_id=p_workspace_id and week_lane_key=p_lane_key;
  update public.task_week_lanes set redirect_lane_key=p_destination_key
    where workspace_id=p_workspace_id and redirect_lane_key=p_lane_key;
  update public.task_week_lanes set is_active=false,redirect_lane_key=p_destination_key
    where workspace_id=p_workspace_id and lane_key=p_lane_key;
  select coalesce(max(week_position),0) into v_position from public.tasks
    where workspace_id=p_workspace_id and week_lane=p_destination_key;
  for v_task in select id,version from public.tasks where workspace_id=p_workspace_id and week_lane=p_lane_key
    order by week_position,id for update
  loop
    v_position:=v_position+1000;
    -- Preserve dates, projects and archived state. Normal task triggers update
    -- version and apply the destination's configured status connection.
    update public.tasks set week_lane=p_destination_key,week_position=v_position,updated_by=auth.uid()
      where workspace_id=p_workspace_id and id=v_task.id and version=v_task.version;
    if not found then raise exception using errcode='40001',message='PTA_VERSION_CONFLICT'; end if;
    v_count:=v_count+1;
  end loop;
  update public.task_board_settings set version=version+1,updated_at=clock_timestamp(),updated_by=auth.uid()
    where workspace_id=p_workspace_id and board_kind in ('week','status');
  insert into public.activity_logs(workspace_id,actor_id,entity_type,entity_id,action,changes_json)
    values(p_workspace_id,auth.uid(),'task_board',p_workspace_id,'week_board.column_deleted',
      jsonb_build_object('lane',p_lane_key,'destination',p_destination_key,'tasks_moved',v_count));
  return public.get_task_board_configuration(p_workspace_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_remove_task_attachment(p_attachment_id uuid, p_removal_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_role public.workspace_role;
  v_attachment public.task_attachments%rowtype;
begin
  select attachment.*
  into v_attachment
  from public.task_attachments attachment
  where attachment.id = p_attachment_id
    and attachment.state in (
      'deleting'::public.task_attachment_state,
      'deleted'::public.task_attachment_state
    )
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_ATTACHMENT_NOT_FOUND';
  end if;

  v_role := private.task_collaboration_role(v_attachment.task_id);
  if v_role is null
    or v_attachment.removal_token is distinct from p_removal_token
    or not (
      (
        v_attachment.delete_requested_by = v_actor
        and (
          v_role in (
            'owner'::public.workspace_role,
            'admin'::public.workspace_role,
            'manager'::public.workspace_role
          )
          or (
            v_role = 'member'::public.workspace_role
            and v_attachment.uploaded_by = v_actor
          )
        )
      )
      or v_role in (
        'owner'::public.workspace_role,
        'admin'::public.workspace_role,
        'manager'::public.workspace_role
      )
    ) then
    raise exception using errcode = 'P0002', message = 'PTA_ATTACHMENT_NOT_FOUND';
  end if;

  if v_attachment.state = 'deleted'::public.task_attachment_state then
    return jsonb_build_object(
      'id', v_attachment.id,
      'task_id', v_attachment.task_id,
      'removed', true,
      'deleted_at', v_attachment.deleted_at
    );
  end if;

  if exists (
    select 1
    from storage.objects object
    where object.bucket_id = v_attachment.bucket_id
      and object.name = v_attachment.object_path
  ) then
    raise exception using errcode = '55000', message = 'PTA_ATTACHMENT_OBJECT_STILL_EXISTS';
  end if;

  update public.task_attachments attachment
  set
    state = 'deleted'::public.task_attachment_state,
    deleted_by = v_actor,
    deleted_at = clock_timestamp()
  where attachment.id = p_attachment_id
  returning * into v_attachment;

  perform realtime.send(
    jsonb_build_object(
      'task_id', v_attachment.task_id,
      'attachment_id', v_attachment.id
    ),
    'attachment_changed',
    'task:' || v_attachment.task_id::text,
    true
  );

  return jsonb_build_object(
    'id', v_attachment.id,
    'task_id', v_attachment.task_id,
    'removed', true,
    'deleted_at', v_attachment.deleted_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_event_operational(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event public.events%rowtype;
  v_role public.workspace_role;
  v_task_count integer;
  v_done_task_count integer;
  v_open_task_count integer;
  v_overdue_task_count integer;
  v_blocked_task_count integer;
  v_critical_task_count integer;
  v_progress integer;
  v_timezone text;
  v_today date;
begin
  select * into v_event from (select * from public.events where private.can_read_event(id)) visible_event where id = p_event_id and archived_at is null;
  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_EVENT_NOT_FOUND';
  end if;
  v_role := private.current_workspace_role(v_event.workspace_id);
  if auth.uid() is null or v_role is null then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  select timezone into v_timezone from public.workspaces where id = v_event.workspace_id;
  v_today := (clock_timestamp() at time zone v_timezone)::date;

  select
    count(task.id) filter (where status.system_category <> 'cancelled')::integer,
    count(task.id) filter (where status.system_category = 'done')::integer,
    count(task.id) filter (where status.system_category not in ('done', 'cancelled'))::integer,
    count(task.id) filter (where status.system_category not in ('done', 'cancelled') and task.due_at < now())::integer,
    count(task.id) filter (where status.system_category = 'blocked')::integer,
    count(task.id) filter (where
      (status.system_category = 'blocked' and task.priority in ('high', 'urgent'))
      or (
        status.system_category not in ('done', 'cancelled')
        and task.due_at < now()
        and task.priority in ('high', 'urgent')
      )
    )::integer
  into v_task_count, v_done_task_count, v_open_task_count,
    v_overdue_task_count, v_blocked_task_count, v_critical_task_count
  from (select * from public.tasks where private.can_read_task(id)) task
  join public.task_statuses status
    on status.id = task.status_id and status.workspace_id = task.workspace_id
  where task.event_id = v_event.id and task.archived_at is null;

  v_progress := case
    when v_task_count = 0 then 0
    else round(100.0 * v_done_task_count / v_task_count)::integer
  end;

  return jsonb_build_object(
    'event', jsonb_build_object(
      'id', v_event.id, 'name', v_event.name, 'status', v_event.status,
      'summary', v_event.summary, 'objective', v_event.objective,
      'success_metric', v_event.success_metric, 'health_override', v_event.health_override,
      'product_id', v_event.product_id,
      'product_name', (select name from public.products where id = v_event.product_id),
      'owner_id', v_event.owner_id,
      'owner_name', (select full_name from public.profiles where id = v_event.owner_id),
      'start_date', v_event.start_date, 'end_date', v_event.end_date,
      'task_count', v_task_count, 'done_task_count', v_done_task_count,
      'open_task_count', v_open_task_count, 'overdue_task_count', v_overdue_task_count,
      'progress', case when v_task_count = 0 then null else v_progress end,
      'health', private.event_health(
        v_event.health_override, v_event.start_date, v_event.end_date,
        v_progress, v_overdue_task_count, v_critical_task_count,
        v_blocked_task_count, v_today
      ),
      'version', v_event.version, 'created_at', v_event.created_at, 'updated_at', v_event.updated_at
    ),
    'tasks', coalesce((select jsonb_agg(jsonb_build_object(
      'id', task.id, 'task_number', task.task_number, 'title', task.title,
      'priority', task.priority, 'due_date', task.due_date,
      'status_name', status.name, 'status_category', status.system_category,
      'assignee_name', assignee_profile.full_name
    ) order by task.updated_at desc)
      from (select * from public.tasks where private.can_read_task(id)) task
      join public.task_statuses status on status.id = task.status_id and status.workspace_id = task.workspace_id
      left join public.task_assignees assignee on assignee.task_id = task.id and assignee.workspace_id = task.workspace_id and assignee.is_primary
      left join public.profiles assignee_profile on assignee_profile.id = assignee.user_id
      where task.event_id = v_event.id and task.archived_at is null), '[]'::jsonb),
    'resources', coalesce((select jsonb_agg(jsonb_build_object(
      'id', resource.id, 'title', resource.title, 'type', resource.resource_type, 'updated_at', resource.updated_at
    ) order by resource.updated_at desc)
      from public.resource_events relation
      join public.resources resource on resource.id = relation.resource_id and resource.workspace_id = relation.workspace_id
      where relation.event_id = v_event.id and resource.archived_at is null and private.can_view_resource(resource.id)), '[]'::jsonb),
    'team', coalesce((select jsonb_agg(jsonb_build_object(
      'id', member.user_id, 'name', profile.full_name, 'role_label', member.role_label
    ) order by profile.full_name)
      from public.event_members member
      join public.profiles profile on profile.id = member.user_id
      where member.event_id = v_event.id), '[]'::jsonb),
    'milestones', coalesce((select jsonb_agg(jsonb_build_object(
      'id', milestone.id, 'title', milestone.title, 'due_date', milestone.due_date,
      'phase', milestone.phase, 'completed_at', milestone.completed_at,
      'position', milestone.position, 'version', milestone.version
    ) order by milestone.position, milestone.due_date nulls last)
      from public.event_milestones milestone where milestone.event_id = v_event.id), '[]'::jsonb),
    'history', coalesce((select jsonb_agg(log_row.item order by log_row.created_at desc)
      from (select log.created_at, jsonb_build_object(
        'id', log.id, 'action', log.action, 'actor_name', actor.full_name,
        'created_at', log.created_at
      ) item
      from public.activity_logs log
      left join public.profiles actor on actor.id = log.actor_id
      where log.workspace_id = v_event.workspace_id
        and (
          (log.entity_type = 'event' and log.entity_id = v_event.id)
          or (log.entity_type = 'event_milestone' and log.metadata_json->>'event_id' = v_event.id::text)
          or (log.entity_type = 'task' and exists (
            select 1 from (select * from public.tasks where private.can_read_task(id)) related_task
            where related_task.id = log.entity_id and related_task.event_id = v_event.id
          ))
        )
      order by log.created_at desc limit 50) log_row), '[]'::jsonb),
    'capabilities', jsonb_build_object(
      'can_edit', v_role in ('owner', 'admin', 'manager'),
      'can_create_task', v_role in ('owner', 'admin', 'manager', 'member')
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_project_board_configuration(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role public.workspace_role;
  v_board_version integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  v_role := private.current_workspace_role(p_workspace_id);
  if v_role is null then
    raise exception using errcode = '42501', message = 'PTA_WORKSPACE_FORBIDDEN';
  end if;

  select setting.version
  into v_board_version
  from public.project_board_settings setting
  where setting.workspace_id = p_workspace_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_PROJECT_BOARD_NOT_FOUND';
  end if;

  return jsonb_build_object(
    'schema_version', 1,
    'workspace_id', p_workspace_id,
    'version', v_board_version,
    'can_manage_columns', v_role in (
      'owner'::public.workspace_role,
      'admin'::public.workspace_role,
      'manager'::public.workspace_role
    ),
    'columns', coalesce((
      select jsonb_agg(jsonb_build_object(
        'key', board_column.column_key,
        'name', board_column.name,
        'color', board_column.color,
        'icon_key', board_column.icon_key,
          'cover_url', board_column.cover_url,
        'position', board_column.position,
        'version', board_column.version
      ) order by board_column.position, board_column.column_key)
      from public.project_board_columns board_column
      where board_column.workspace_id = p_workspace_id
    ), '[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_workspace_settings(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role public.workspace_role;
  v_workspace public.workspaces%rowtype;
  v_digest boolean;
  v_role_counts jsonb;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;

  v_role := private.current_workspace_role(p_workspace_id);
  if v_role is null then
    raise exception using errcode = '42501', message = 'PTA_WORKSPACE_FORBIDDEN';
  end if;

  select workspace.*
  into v_workspace
  from public.workspaces workspace
  where workspace.id = p_workspace_id
    and workspace.archived_at is null;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_WORKSPACE_NOT_FOUND';
  end if;

  select coalesce(preference.notification_digest, true)
  into v_digest
  from (select 1) seed
  left join public.workspace_preferences preference
    on preference.workspace_id = p_workspace_id;

  select coalesce(
    jsonb_object_agg(summary.role::text, summary.member_count),
    '{}'::jsonb
  )
  into v_role_counts
  from (
    select member.role, count(*)::integer as member_count
    from public.workspace_members member
    join public.profiles profile
      on profile.id = member.user_id
      and profile.is_active
    where member.workspace_id = p_workspace_id
      and member.status = 'active'::public.membership_status
      and member.removed_at is null
    group by member.role
  ) summary;

  return jsonb_build_object(
    'workspace_id', v_workspace.id,
    'name', v_workspace.name,
    'task_prefix', v_workspace.task_prefix,
    'accent_color', v_workspace.accent_color,
    'timezone', v_workspace.timezone,
    'locale', v_workspace.locale,
    'week_starts_on', v_workspace.week_starts_on,
    'working_days', to_jsonb(v_workspace.working_days),
    'default_due_time', to_char(v_workspace.default_due_time, 'HH24:MI'),
    'notification_digest', v_digest,
    'version', v_workspace.version,
    'role', v_role,
    'role_counts', v_role_counts,
    'permissions', jsonb_build_object(
      'can_edit', v_role in ('owner'::public.workspace_role, 'admin'::public.workspace_role),
      'can_manage_members', v_role in ('owner'::public.workspace_role, 'admin'::public.workspace_role),
      'can_transfer_ownership', v_role = 'owner'::public.workspace_role
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.inspect_workspace_invitation(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_email text;
  v_token_hash text;
  v_invitation public.workspace_invitations%rowtype;
  v_workspace_name text;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;

  select lower(btrim(auth_user.email))
  into v_actor_email
  from auth.users auth_user
  join public.profiles profile
    on profile.id = auth_user.id
    and profile.is_active
  where auth_user.id = v_actor;

  if v_actor_email is null then
    raise exception using errcode = '42501', message = 'PTA_PROFILE_INACTIVE';
  end if;
  if p_token is null or btrim(p_token) !~* '^[0-9a-f]{64}$' then
    return jsonb_build_object('status', 'invalid');
  end if;

  v_token_hash := encode(extensions.digest(lower(btrim(p_token)), 'sha256'), 'hex');
  select invitation.*
  into v_invitation
  from public.workspace_invitations invitation
  where invitation.token_hash = v_token_hash;

  if not found then
    return jsonb_build_object('status', 'invalid');
  end if;
  if v_invitation.email <> v_actor_email then
    return jsonb_build_object('status', 'email_mismatch');
  end if;
  if v_invitation.accepted_at is not null then
    return jsonb_build_object('status', 'accepted');
  end if;
  if v_invitation.cancelled_at is not null then
    return jsonb_build_object('status', 'cancelled');
  end if;
  if v_invitation.expires_at <= statement_timestamp() then
    return jsonb_build_object('status', 'expired');
  end if;

  select workspace.name
  into v_workspace_name
  from public.workspaces workspace
  where workspace.id = v_invitation.workspace_id
    and workspace.archived_at is null;

  if v_workspace_name is null then
    return jsonb_build_object('status', 'invalid');
  end if;

  return jsonb_build_object(
    'status', 'pending',
    'workspace_id', v_invitation.workspace_id,
    'workspace_name', v_workspace_name,
    'role', v_invitation.role,
    'expires_at', v_invitation.expires_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.list_team_directory(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
  if auth.uid() is null or private.current_workspace_role(p_workspace_id) is null then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  with task_counts as (select event_id,count(*) as n from public.tasks where workspace_id = p_workspace_id and archived_at is null and private.can_read_task(id) group by event_id), member_counts as (
    select team_id, count(*) as n from public.team_members
    where workspace_id = p_workspace_id and removed_at is null group by team_id
  ), project_counts as (
    select primary_team_id, count(*) as n from public.events
    where workspace_id = p_workspace_id and archived_at is null group by primary_team_id
  )
  select jsonb_build_object(
    'teams', coalesce((select jsonb_agg(jsonb_build_object(
      'id', t.id, 'name', t.name, 'description', t.description, 'color', t.color,
      'workspace_event_id', t.workspace_event_id, 'task_count', coalesce(tc.n,0), 'version', t.version, 'member_count', coalesce(m.n,0), 'project_count', coalesce(p.n,0)
    ) order by t.name, t.id) from public.teams t
      left join task_counts tc on tc.event_id = t.workspace_event_id left join member_counts m on m.team_id = t.id
      left join project_counts p on p.primary_team_id = t.id
      where t.workspace_id = p_workspace_id and t.archived_at is null and private.can_read_team(t.id)), '[]'::jsonb),
    'unassigned_count', coalesce((select n from project_counts where primary_team_id is null),0),
    'can_manage', private.can_manage_operating_model(p_workspace_id)
  ) into v_result;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.list_team_projects(p_workspace_id uuid, p_team_id uuid DEFAULT NULL::uuid, p_unassigned boolean DEFAULT false, p_search text DEFAULT ''::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
  if auth.uid() is null or private.current_workspace_role(p_workspace_id) is null then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_offset is null or p_offset < 0 or p_limit is null or p_limit < 1 or p_limit > 100
    or length(coalesce(p_search,'')) > 200 or (p_team_id is not null and p_unassigned) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_FILTER';
  end if;
  if p_team_id is not null and not exists (select 1 from public.teams
    where workspace_id = p_workspace_id and id = p_team_id and archived_at is null and private.can_read_team(id)) then
    raise exception using errcode = 'P0002', message = 'PTA_TEAM_NOT_FOUND';
  end if;
  with filtered as materialized (
    select e.id, e.name, e.status, e.version, e.primary_team_id, t.name as team_name, e.start_date, e.end_date
    from public.events e left join public.teams t on t.workspace_id = e.workspace_id and t.id = e.primary_team_id
    where e.workspace_id = p_workspace_id and e.archived_at is null and private.can_read_event(e.id)
      and (p_team_id is null or e.primary_team_id = p_team_id)
      and (not coalesce(p_unassigned,false) or e.primary_team_id is null)
      and (coalesce(btrim(p_search),'') = '' or strpos(lower(e.name),lower(btrim(p_search))) > 0)
  ), page as (select * from filtered order by name, id offset p_offset limit p_limit)
  select jsonb_build_object('projects', coalesce((select jsonb_agg(to_jsonb(page) order by name,id) from page),'[]'::jsonb),
    'total', (select count(*) from filtered)) into v_result;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.list_workspace_team_management(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_members jsonb;
  v_invitations jsonb;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;

  v_role := private.current_workspace_role(p_workspace_id);
  if v_role is null or v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'user_id', member.user_id,
        'full_name', profile.full_name,
        'email', profile.email,
        'initials', coalesce(
          nullif(btrim(profile.initials), ''),
          upper(left(btrim(profile.full_name), 1))
        ),
        'avatar_path', profile.avatar_path,
        'role', member.role,
        'membership_state', case
          when member.removed_at is not null then 'removed'
          else member.status::text
        end,
        'weekly_capacity_minutes', member.weekly_capacity_minutes,
        'joined_at', member.joined_at,
        'suspended_at', member.suspended_at,
        'removed_at', member.removed_at,
        'version', member.version,
        'is_self', member.user_id = v_actor
      )
      order by
        case when member.status = 'active'::public.membership_status then 0 else 1 end,
        lower(profile.full_name),
        member.user_id
    ),
    '[]'::jsonb
  )
  into v_members
  from public.workspace_members member
  join public.profiles profile on profile.id = member.user_id
  where member.workspace_id = p_workspace_id;

  select coalesce(
    jsonb_agg(
      private.workspace_invitation_management_json(invitation.id)
      order by invitation.created_at desc, invitation.id
    ),
    '[]'::jsonb
  )
  into v_invitations
  from public.workspace_invitations invitation
  where invitation.workspace_id = p_workspace_id;

  return jsonb_build_object(
    'workspace_id', p_workspace_id,
    'members', v_members,
    'invitations', v_invitations,
    'permissions', jsonb_build_object(
      'can_invite', true,
      'can_manage_members', true,
      'can_transfer_ownership', v_role = 'owner'::public.workspace_role
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.manage_task_board_column(p_workspace_id uuid, p_expected_board_version integer, p_action text, p_name text DEFAULT NULL::text, p_column_id uuid DEFAULT NULL::uuid, p_destination_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role := private.current_workspace_role(p_workspace_id);
  v_version integer;
  v_source public.task_statuses%rowtype;
  v_destination public.task_statuses%rowtype;
  v_task record;
  v_id uuid := gen_random_uuid();
begin
  if v_actor is null or v_role is null or v_role not in ('owner','admin','manager') then
    raise exception using errcode='42501', message='PTA_BOARD_CONFIGURATION_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_workspace_id::text,713421));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('pta:task-board:' || p_workspace_id::text,0));
  select version into v_version from public.task_board_settings
    where workspace_id=p_workspace_id and board_kind='status' for update;
  if v_version is null or v_version is distinct from p_expected_board_version then
    raise exception using errcode='40001', message='PTA_VERSION_CONFLICT';
  end if;
  if p_action='create' then
    if char_length(btrim(coalesce(p_name,''))) not between 1 and 80 then
      raise exception using errcode='22023', message='PTA_BOARD_COLUMN_NAME_INVALID';
    end if;
    insert into public.task_statuses(id,workspace_id,name,system_category,position,semantic_key)
      select v_id,p_workspace_id,btrim(p_name),'todo',coalesce(max(position),0)+10,
        'custom-' || replace(v_id::text,'-','') from public.task_statuses where workspace_id=p_workspace_id;
  elsif p_action='delete' then
    select * into v_source from public.task_statuses
      where workspace_id=p_workspace_id and id=p_column_id and is_active for update;
    if not found then raise exception 'PTA_BOARD_COLUMN_NOT_FOUND'; end if;
    select * into v_destination from public.task_statuses
      where workspace_id=p_workspace_id and id=p_destination_id and is_active and id<>p_column_id for update;
    if not found then raise exception 'PTA_BOARD_DESTINATION_REQUIRED'; end if;
    if v_destination.system_category='blocked' then raise exception 'PTA_BOARD_DESTINATION_BLOCKED'; end if;
    for v_task in select id,version from public.tasks
      where workspace_id=p_workspace_id and status_id=p_column_id and archived_at is null
      order by id for update
    loop
      perform public.move_task_in_board(p_workspace_id,v_task.id,p_destination_id,null,null,v_task.version,null);
    end loop;
    -- Archived tasks retain their archive state, but can later be restored to an active column.
    update public.tasks set status_id=p_destination_id,updated_by=v_actor
      where workspace_id=p_workspace_id and status_id=p_column_id and archived_at is not null;
    delete from public.task_status_week_lane_links where workspace_id=p_workspace_id and status_id=p_column_id;
    update public.task_statuses set is_active=false,is_default=false where workspace_id=p_workspace_id and id=p_column_id;
    if v_source.is_default then
      update public.task_statuses set is_default=true where workspace_id=p_workspace_id and id=p_destination_id;
    end if;
    v_id := p_column_id;
  else raise exception 'PTA_BOARD_ACTION_INVALID';
  end if;
  update public.task_board_settings set version=version+1,updated_at=clock_timestamp(),updated_by=v_actor
    where workspace_id=p_workspace_id and board_kind='status';
  insert into public.activity_logs(workspace_id,actor_id,entity_type,entity_id,action,changes_json)
    values(p_workspace_id,v_actor,'task_board',v_id,'task_board.column_' || p_action,
      jsonb_build_object('destination_id',p_destination_id));
  return public.get_task_board_configuration(p_workspace_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.move_event_milestone_in_timeline(p_workspace_id uuid, p_milestone_id uuid, p_expected_version integer, p_event_phase_id uuid, p_due_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_milestone public.event_milestones%rowtype;
begin
  if v_actor is null
     or coalesce(private.current_workspace_role(p_workspace_id) not in ('owner', 'admin', 'manager'), true) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  select milestone.* into v_milestone
  from public.event_milestones milestone
  where milestone.workspace_id = p_workspace_id and milestone.id = p_milestone_id
  for update;
  if not found then raise exception using errcode = 'P0002', message = 'PTA_MILESTONE_NOT_FOUND'; end if;
  if v_milestone.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if p_event_phase_id is not null and not exists (
    select 1 from public.event_phases phase
    where phase.workspace_id = p_workspace_id
      and phase.event_id = v_milestone.event_id
      and phase.id = p_event_phase_id
      and phase.archived_at is null
  ) then
    raise exception using errcode = '23514', message = 'PTA_PHASE_NOT_ACTIVE';
  end if;

  update public.event_milestones milestone set
    event_phase_id = p_event_phase_id,
    due_date = p_due_date,
    updated_by = v_actor
  where milestone.workspace_id = p_workspace_id
    and milestone.id = p_milestone_id
    and milestone.version = p_expected_version
  returning * into v_milestone;
  if not found then raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT'; end if;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, changes_json
  ) values (
    p_workspace_id, v_actor, 'event_milestone', v_milestone.id, 'event.milestone_moved',
    jsonb_build_object('event_phase_id', p_event_phase_id, 'due_date', p_due_date)
  );
  return jsonb_build_object(
    'id', v_milestone.id,
    'version', v_milestone.version,
    'event_phase_id', v_milestone.event_phase_id,
    'due_date', v_milestone.due_date
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.move_task_in_board(p_workspace_id uuid, p_task_id uuid, p_status_id uuid, p_before_task_id uuid, p_after_task_id uuid, p_expected_version integer, p_blocked_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_task public.tasks%rowtype;
  v_status_category public.task_status_category;
  v_before_position numeric(20, 10);
  v_after_position numeric(20, 10);
  v_position numeric(20, 10);
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_workspace_id::text, 713421)
  );

  select task.* into v_task
  from public.tasks task
  where task.workspace_id = p_workspace_id
    and task.id = p_task_id
    and task.archived_at is null
  for update;

  if not found or not private.can_edit_task(p_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_task.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if p_before_task_id = p_task_id or p_after_task_id = p_task_id
     or (p_before_task_id is not null and p_before_task_id = p_after_task_id) then
    raise exception using errcode = '22023', message = 'PTA_BOARD_NEIGHBOR_INVALID';
  end if;

  select status.system_category into v_status_category
  from public.task_statuses status
  where status.workspace_id = p_workspace_id
    and status.id = p_status_id
    and status.is_active
  for update;
  if not found then
    raise exception using errcode = '23503', message = 'PTA_INVALID_TASK_STATUS';
  end if;

  -- Serialize moves into the destination column. This makes fractional ranks
  -- deterministic and lets the rare rebalance remain atomic.
  perform task.id
  from public.tasks task
  where task.workspace_id = p_workspace_id
    and task.status_id = p_status_id
    and task.archived_at is null
    and task.id <> p_task_id
  order by task.board_position, task.task_number, task.id
  for update;

  if p_before_task_id is not null then
    select task.board_position into v_before_position
    from public.tasks task
    where task.workspace_id = p_workspace_id
      and task.status_id = p_status_id
      and task.id = p_before_task_id
      and task.archived_at is null;
    if not found then
      raise exception using errcode = '40001', message = 'PTA_BOARD_ORDER_CONFLICT';
    end if;
  end if;

  if p_after_task_id is not null then
    select task.board_position into v_after_position
    from public.tasks task
    where task.workspace_id = p_workspace_id
      and task.status_id = p_status_id
      and task.id = p_after_task_id
      and task.archived_at is null;
    if not found then
      raise exception using errcode = '40001', message = 'PTA_BOARD_ORDER_CONFLICT';
    end if;
  end if;

  if v_before_position is not null and v_after_position is not null
     and (
       v_before_position > v_after_position
       or exists (
         select 1
         from public.tasks task
         where task.workspace_id = p_workspace_id
           and task.status_id = p_status_id
           and task.archived_at is null
           and task.id <> p_task_id
           and task.id not in (p_before_task_id, p_after_task_id)
           and task.board_position >= v_before_position
           and task.board_position <= v_after_position
       )
     ) then
    raise exception using errcode = '40001', message = 'PTA_BOARD_ORDER_CONFLICT';
  elsif v_before_position is null and v_after_position is not null
        and exists (
          select 1 from public.tasks task
          where task.workspace_id = p_workspace_id
            and task.status_id = p_status_id
            and task.archived_at is null
            and task.id <> p_task_id
            and task.id <> p_after_task_id
            and task.board_position <= v_after_position
        ) then
    raise exception using errcode = '40001', message = 'PTA_BOARD_ORDER_CONFLICT';
  elsif v_before_position is not null and v_after_position is null
        and exists (
          select 1 from public.tasks task
          where task.workspace_id = p_workspace_id
            and task.status_id = p_status_id
            and task.archived_at is null
            and task.id <> p_task_id
            and task.id <> p_before_task_id
            and task.board_position >= v_before_position
        ) then
    raise exception using errcode = '40001', message = 'PTA_BOARD_ORDER_CONFLICT';
  end if;

  if v_before_position is null and v_after_position is null then
    select coalesce(max(task.board_position), 0) + 1000 into v_position
    from public.tasks task
    where task.workspace_id = p_workspace_id
      and task.status_id = p_status_id
      and task.archived_at is null
      and task.id <> p_task_id;
  elsif v_before_position is null then
    v_position := v_after_position / 2;
  elsif v_after_position is null then
    v_position := v_before_position + 1000;
  else
    v_position := v_before_position + ((v_after_position - v_before_position) / 2);
  end if;

  if v_position < 0
     or v_position = v_before_position
     or v_position = v_after_position then
    with ranked as (
      select
        task.id,
        row_number() over (
          order by task.board_position, task.task_number, task.id
        ) * 1000 as position
      from public.tasks task
      where task.workspace_id = p_workspace_id
        and task.status_id = p_status_id
        and task.archived_at is null
        and task.id <> p_task_id
    )
    update public.tasks task
    set board_position = ranked.position,
        updated_by = v_actor
    from ranked
    where task.id = ranked.id
      and task.board_position is distinct from ranked.position;

    select task.board_position into v_before_position
    from public.tasks task where task.id = p_before_task_id;
    select task.board_position into v_after_position
    from public.tasks task where task.id = p_after_task_id;

    if v_before_position is null and v_after_position is null then
      v_position := 1000;
    elsif v_before_position is null then
      v_position := v_after_position / 2;
    elsif v_after_position is null then
      v_position := v_before_position + 1000;
    else
      v_position := v_before_position + ((v_after_position - v_before_position) / 2);
    end if;
  end if;

  if v_status_category = 'blocked'
     and nullif(btrim(coalesce(p_blocked_reason, v_task.blocked_reason)), '') is null then
    raise exception using errcode = '23514', message = 'PTA_BLOCKED_REASON_REQUIRED';
  end if;

  update public.tasks task
  set
    status_id = p_status_id,
    board_position = v_position,
    blocked_reason = case
      when v_status_category = 'blocked'
        then nullif(btrim(coalesce(p_blocked_reason, v_task.blocked_reason)), '')
      else null
    end,
    updated_by = v_actor
  where task.workspace_id = p_workspace_id
    and task.id = p_task_id
    and task.version = p_expected_version
  returning * into v_task;

  if not found then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  return jsonb_build_object(
    'id', v_task.id,
    'workspace_id', v_task.workspace_id,
    'status_id', v_task.status_id,
    'board_position', v_task.board_position,
    'version', v_task.version,
    'updated_at', v_task.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.move_task_in_timeline(p_workspace_id uuid, p_event_id uuid, p_task_id uuid, p_expected_version integer, p_status_id uuid, p_event_phase_id uuid, p_start_date date, p_start_time time without time zone, p_due_date date, p_due_time time without time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_task public.tasks%rowtype;
begin
  if v_actor is null or not private.can_edit_task(p_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  select task.* into v_task
  from public.tasks task
  where task.workspace_id = p_workspace_id
    and task.event_id = p_event_id
    and task.id = p_task_id
    and task.archived_at is null
  for update;
  if not found then raise exception using errcode = '42501', message = 'PTA_FORBIDDEN'; end if;
  if v_task.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if not exists (
    select 1 from public.task_statuses status
    where status.workspace_id = p_workspace_id and status.id = p_status_id and status.is_active
  ) then
    raise exception using errcode = '23514', message = 'PTA_STATUS_NOT_ACTIVE';
  end if;
  if p_event_phase_id is not null and not exists (
    select 1 from public.event_phases phase
    where phase.workspace_id = p_workspace_id
      and phase.event_id = p_event_id
      and phase.id = p_event_phase_id
      and phase.archived_at is null
  ) then
    raise exception using errcode = '23514', message = 'PTA_PHASE_NOT_ACTIVE';
  end if;

  update public.tasks task set
    status_id = p_status_id,
    event_phase_id = p_event_phase_id,
    start_date = p_start_date,
    start_time = p_start_time,
    due_date = p_due_date,
    due_time = p_due_time,
    updated_by = v_actor
  where task.workspace_id = p_workspace_id
    and task.event_id = p_event_id
    and task.id = p_task_id
    and task.version = p_expected_version
  returning * into v_task;
  if not found then raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT'; end if;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, changes_json
  ) values (
    p_workspace_id, v_actor, 'task', v_task.id, 'task.timeline_moved',
    jsonb_build_object(
      'status_id', v_task.status_id,
      'event_phase_id', v_task.event_phase_id,
      'start_date', v_task.start_date,
      'start_time', v_task.start_time,
      'due_date', v_task.due_date,
      'due_time', v_task.due_time
    )
  );

  return jsonb_build_object(
    'id', v_task.id,
    'version', v_task.version,
    'status_id', v_task.status_id,
    'event_phase_id', v_task.event_phase_id,
    'start_date', v_task.start_date,
    'start_time', v_task.start_time,
    'due_date', v_task.due_date,
    'due_time', v_task.due_time,
    'updated_at', v_task.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.move_task_in_week(p_task_id uuid, p_week_lane text, p_due_date date, p_position numeric, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_task public.tasks%rowtype;
begin
  if v_actor is null or not private.can_edit_task(p_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  if p_week_lane not in (
    'backlog',
    'emergency',
    'important',
    'scheduled',
    'delivered',
    'revision',
    'ideas',
    'discarded'
  ) then
    raise exception using errcode = '22023', message = 'PTA_WEEK_LANE_INVALID';
  end if;

  if p_week_lane = 'scheduled' and p_due_date is null then
    raise exception using errcode = '22023', message = 'PTA_WEEK_DATE_REQUIRED';
  end if;

  if p_position is null or p_position < 0 then
    raise exception using errcode = '22023', message = 'PTA_WEEK_POSITION_INVALID';
  end if;

  update public.tasks task
  set
    week_lane = p_week_lane,
    due_date = case
      when p_week_lane = 'scheduled' then p_due_date
      when p_week_lane = 'backlog' then null
      else task.due_date
    end,
    due_time = case
      when p_week_lane = 'backlog' then null
      else task.due_time
    end,
    week_position = p_position,
    updated_by = v_actor
  where task.id = p_task_id
    and task.version = p_expected_version
  returning * into v_task;

  if not found then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  return jsonb_build_object(
    'id', v_task.id,
    'version', v_task.version,
    'week_lane', v_task.week_lane,
    'due_date', v_task.due_date,
    'week_position', v_task.week_position,
    'updated_at', v_task.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.move_task_to_day(p_task_id uuid, p_due_date date, p_position numeric, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := auth.uid(); v_task public.tasks%rowtype;
begin
  if v_actor is null or not private.can_edit_task(p_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_due_date is null or p_position is null or p_position < 0 then
