CREATE OR REPLACE FUNCTION public.prepare_task_attachment(p_task_id uuid, p_file_name text, p_file_extension text, p_mime_type text, p_file_size bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_role public.workspace_role;
  v_workspace_id uuid;
  v_id uuid := gen_random_uuid();
  v_name text := btrim(coalesce(p_file_name, ''));
  v_extension text := lower(btrim(coalesce(p_file_extension, '')));
  v_mime_type text := lower(btrim(coalesce(p_mime_type, '')));
  v_object_path text;
begin
  select task.workspace_id
  into v_workspace_id
  from public.tasks task
  where task.id = p_task_id
    and task.archived_at is null;

  v_role := private.task_collaboration_role(p_task_id);
  if v_workspace_id is null or v_role is null then
    raise exception using errcode = 'P0002', message = 'PTA_TASK_NOT_FOUND';
  end if;
  if v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role,
    'member'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  if char_length(v_name) not between 1 and 255
    or v_name ~ '[[:cntrl:]/\\]'
    or lower(v_name) not like '%.' || v_extension then
    raise exception using errcode = '22023', message = 'PTA_INVALID_ATTACHMENT_NAME';
  end if;
  if p_file_size is null or p_file_size not between 1 and 26214400 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_ATTACHMENT_SIZE';
  end if;
  if not private.is_valid_task_attachment_type(v_extension, v_mime_type) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_ATTACHMENT_TYPE';
  end if;

  -- Keep actor-wide and task-wide quotas atomic under concurrent prepares.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pta:attachment:actor:' || v_actor::text, 0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pta:attachment:task:' || p_task_id::text, 0)
  );

  if (
    select count(*)
    from public.task_attachments attachment
    where attachment.uploaded_by = v_actor
      and attachment.created_at > clock_timestamp() - interval '1 hour'
  ) >= 100 then
    raise exception using errcode = '54000', message = 'PTA_ATTACHMENT_UPLOAD_LIMIT';
  end if;

  if (
    select count(*)
    from public.task_attachments attachment
    where attachment.uploaded_by = v_actor
      and attachment.state = 'pending'::public.task_attachment_state
  ) >= 20 then
    raise exception using errcode = '54000', message = 'PTA_ATTACHMENT_PENDING_LIMIT';
  end if;

  if (
    select count(*)
    from public.task_attachments attachment
    where attachment.task_id = p_task_id
      and attachment.deleted_at is null
  ) >= 500 then
    raise exception using errcode = '54000', message = 'PTA_TASK_ATTACHMENT_LIMIT';
  end if;

  v_object_path := v_workspace_id::text
    || '/tasks/' || p_task_id::text
    || '/' || v_id::text || '.' || v_extension;

  insert into public.task_attachments (
    id,
    workspace_id,
    task_id,
    object_path,
    file_name,
    file_extension,
    mime_type,
    file_size,
    uploaded_by
  ) values (
    v_id,
    v_workspace_id,
    p_task_id,
    v_object_path,
    v_name,
    v_extension,
    v_mime_type,
    p_file_size,
    v_actor
  );

  return jsonb_build_object(
    'id', v_id,
    'bucket_id', 'task-attachments',
    'object_path', v_object_path,
    'file_name', v_name,
    'mime_type', v_mime_type,
    'file_size', p_file_size,
    'state', 'pending'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_task_media(p_task_id uuid, p_file_name text, p_file_extension text, p_mime_type text, p_file_size bigint, p_description text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
 if auth.uid() is null then raise exception 'PTA_FORBIDDEN'; end if;
 if char_length(coalesce(p_description,'')) > 1000 then raise exception 'PTA_INVALID_DESCRIPTION'; end if;
 v_result := public.prepare_task_attachment(p_task_id,p_file_name,p_file_extension,p_mime_type,p_file_size);
 update public.task_attachments set description=btrim(coalesce(p_description,'')) where id=(v_result->>'id')::uuid;
 return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.reactivate_workspace_member(p_workspace_id uuid, p_user_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_role public.workspace_role;
  v_member public.workspace_members%rowtype;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:workspace-team:' || p_workspace_id::text, 0)
  );
  v_actor_role := private.current_workspace_role(p_workspace_id);
  if v_actor_role is null or v_actor_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;

  select member.*
  into v_member
  from public.workspace_members member
  where member.workspace_id = p_workspace_id
    and member.user_id = p_user_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_MEMBER_NOT_FOUND';
  end if;
  if v_member.removed_at is not null then
    raise exception using errcode = '23514', message = 'PTA_MEMBER_REMOVED';
  end if;
  if v_member.status = 'active'::public.membership_status then
    return jsonb_build_object(
      'member', private.workspace_member_management_json(p_workspace_id, p_user_id)
    );
  end if;
  if v_member.role = 'owner'::public.workspace_role then
    raise exception using errcode = '23514', message = 'PTA_OWNER_REACTIVATION_REQUIRES_TRANSFER';
  end if;
  if v_member.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if not exists (
    select 1
    from public.profiles profile
    where profile.id = p_user_id
      and profile.is_active
  ) then
    raise exception using errcode = '23514', message = 'PTA_PROFILE_INACTIVE';
  end if;

  update public.workspace_members member
  set
    status = 'active'::public.membership_status,
    suspended_at = null
  where member.workspace_id = p_workspace_id
    and member.user_id = p_user_id;

  insert into public.activity_logs (
    workspace_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    changes_json
  ) values (
    p_workspace_id,
    v_actor,
    'workspace_member',
    p_user_id,
    'workspace.member_reactivated',
    jsonb_build_object(
      'status', jsonb_build_object('from', 'suspended', 'to', 'active')
    )
  );

  return jsonb_build_object(
    'member', private.workspace_member_management_json(p_workspace_id, p_user_id)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.record_resource_visit(p_resource_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace_id uuid;
  v_last_visited_at timestamptz;
begin
  if p_resource_id is null or not private.can_view_resource(p_resource_id) then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_NOT_FOUND';
  end if;

  select workspace_id into v_workspace_id from public.resources where id = p_resource_id;

  insert into public.resource_visits (
    workspace_id,
    resource_id,
    user_id,
    first_visited_at,
    last_visited_at,
    visit_count
  ) values (
    v_workspace_id,
    p_resource_id,
    (select auth.uid()),
    clock_timestamp(),
    clock_timestamp(),
    1
  )
  on conflict (workspace_id, resource_id, user_id) do update
    set last_visited_at = clock_timestamp(),
        visit_count = public.resource_visits.visit_count + 1
  returning last_visited_at into v_last_visited_at;

  return jsonb_build_object(
    'resource_id', p_resource_id,
    'last_visited_at', v_last_visited_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_task_checklist(p_checklist_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_checklist public.task_checklists%rowtype;
  v_item_count integer;
begin
  select checklist.* into v_checklist
  from public.task_checklists checklist
  where checklist.id = p_checklist_id
  for update;

  if not found or v_actor is null or not private.can_edit_task(v_checklist.task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_checklist.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  select count(*)::integer into v_item_count
  from public.task_checklist_items item
  where item.workspace_id = v_checklist.workspace_id
    and item.task_id = v_checklist.task_id
    and item.checklist_id = v_checklist.id;

  delete from public.task_checklists checklist where checklist.id = v_checklist.id;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    v_checklist.workspace_id, v_actor, 'task', v_checklist.task_id,
    'task.checklist_removed',
    jsonb_build_object(
      'checklist_id', v_checklist.id,
      'title', v_checklist.title,
      'item_count', v_item_count
    )
  );

  return jsonb_build_object(
    'id', v_checklist.id,
    'removed', true,
    'item_count', v_item_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_task_checklist_item(p_item_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_item public.task_checklist_items%rowtype;
begin
  select item.* into v_item
  from public.task_checklist_items item
  where item.id = p_item_id
  for update;

  if not found or v_actor is null or not private.can_edit_task(v_item.task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_item.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  delete from public.task_checklist_items item where item.id = v_item.id;
  update public.task_checklists checklist
  set updated_at = now()
  where checklist.id = v_item.checklist_id;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    v_item.workspace_id, v_actor, 'task', v_item.task_id,
    'task.checklist_item_removed',
    jsonb_build_object('item_id', v_item.id, 'checklist_id', v_item.checklist_id)
  );

  return jsonb_build_object('id', v_item.id, 'removed', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_task_link(p_link_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_link public.task_links%rowtype;
begin
  select link.*
  into v_link
  from public.task_links link
  where link.id = p_link_id
    and link.deleted_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_LINK_NOT_FOUND';
  end if;
  v_role := private.task_collaboration_role(v_link.task_id);
  if v_role is null then
    raise exception using errcode = 'P0002', message = 'PTA_LINK_NOT_FOUND';
  end if;
  if not (
    v_role in (
      'owner'::public.workspace_role,
      'admin'::public.workspace_role,
      'manager'::public.workspace_role
    )
    or (
      v_role = 'member'::public.workspace_role
      and v_link.created_by = v_actor
    )
  ) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  update public.task_links link
  set
    deleted_by = v_actor,
    deleted_at = clock_timestamp(),
    updated_at = clock_timestamp()
  where link.id = p_link_id
    and link.deleted_at is null
  returning * into v_link;

  perform realtime.send(
    jsonb_build_object('task_id', v_link.task_id),
    'link_removed',
    'task:' || v_link.task_id::text,
    true
  );

  return jsonb_build_object(
    'id', v_link.id,
    'task_id', v_link.task_id,
    'removed', true,
    'deleted_at', v_link.deleted_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_team_member(p_team_id uuid, p_user_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_team public.teams%rowtype;
  v_actor_workspace_role public.workspace_role;
  v_member public.team_members%rowtype;
  v_new_primary_team_id uuid;
  v_was_primary boolean;
begin
  if auth.uid() is null or not private.can_read_team(p_team_id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;

  select team.* into v_team
  from public.teams team
  where team.id = p_team_id
    and team.archived_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_TEAM_NOT_FOUND';
  end if;
  if not private.can_manage_team_members(v_team.id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:operating-model:' || v_team.workspace_id::text, 0)
  );
  perform pg_advisory_xact_lock(
    hashtextextended(
      'pta:team-member:' || v_team.workspace_id::text || ':' || p_user_id::text,
      0
    )
  );

  v_actor_workspace_role := private.current_workspace_role(v_team.workspace_id);
  select member.* into v_member
  from public.team_members member
  where member.workspace_id = v_team.workspace_id
    and member.team_id = v_team.id
    and member.user_id = p_user_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_TEAM_MEMBER_NOT_FOUND';
  end if;
  if v_member.removed_at is not null then
    return jsonb_build_object(
      'team_id', v_member.team_id,
      'user_id', v_member.user_id,
      'version', v_member.version,
      'removed_at', v_member.removed_at
    );
  end if;
  if v_member.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  v_was_primary := v_member.is_primary;
  if v_actor_workspace_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role
  ) and v_member.role = 'lead'::public.team_member_role then
    raise exception using errcode = '42501', message = 'PTA_TEAM_LEAD_CHANGE_FORBIDDEN';
  end if;
  if exists (
    select 1
    from public.task_assignees assignee
    join public.tasks task
      on task.workspace_id = assignee.workspace_id
      and task.id = assignee.task_id
      and task.team_id = v_member.team_id
      and task.archived_at is null
    where assignee.workspace_id = v_member.workspace_id
      and assignee.user_id = v_member.user_id
  ) then
    raise exception using errcode = '23514', message = 'PTA_TEAM_MEMBER_HAS_ACTIVE_TASKS';
  end if;

  select other_membership.team_id
  into v_new_primary_team_id
  from public.team_members other_membership
  join public.teams other_team
    on other_team.workspace_id = other_membership.workspace_id
    and other_team.id = other_membership.team_id
    and other_team.archived_at is null
  where other_membership.workspace_id = v_member.workspace_id
    and other_membership.user_id = v_member.user_id
    and other_membership.team_id <> v_member.team_id
    and other_membership.removed_at is null
  order by other_team.is_default desc, other_membership.joined_at, other_membership.team_id
  limit 1;

  if v_new_primary_team_id is null then
    raise exception using errcode = '23514', message = 'PTA_MEMBER_REQUIRES_ACTIVE_TEAM';
  end if;

  update public.team_member_functions assignment
  set
    is_primary = false,
    archived_at = statement_timestamp(),
    archived_by = v_actor
  where assignment.workspace_id = v_member.workspace_id
    and assignment.team_id = v_member.team_id
    and assignment.user_id = v_member.user_id
    and assignment.archived_at is null;

  update public.team_members member
  set
    is_primary = false,
    removed_at = statement_timestamp(),
    removed_by = v_actor
  where member.workspace_id = v_member.workspace_id
    and member.team_id = v_member.team_id
    and member.user_id = v_member.user_id
  returning member.* into v_member;

  if v_was_primary then
    update public.team_members member
    set is_primary = true
    where member.workspace_id = v_member.workspace_id
      and member.team_id = v_new_primary_team_id
      and member.user_id = v_member.user_id;
  end if;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    v_member.workspace_id,
    v_actor,
    'team_member',
    v_member.team_id,
    'team.member_removed',
    jsonb_build_object('user_id', v_member.user_id)
  );

  return jsonb_build_object(
    'team_id', v_member.team_id,
    'user_id', v_member.user_id,
    'version', v_member.version,
    'removed_at', v_member.removed_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_workspace_member(p_workspace_id uuid, p_user_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_role public.workspace_role;
  v_member public.workspace_members%rowtype;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:workspace-team:' || p_workspace_id::text, 0)
  );
  v_actor_role := private.current_workspace_role(p_workspace_id);
  if v_actor_role is null or v_actor_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;

  select member.*
  into v_member
  from public.workspace_members member
  where member.workspace_id = p_workspace_id
    and member.user_id = p_user_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_MEMBER_NOT_FOUND';
  end if;
  if v_member.role = 'owner'::public.workspace_role then
    raise exception using errcode = '23514', message = 'PTA_LAST_OWNER_REQUIRED';
  end if;
  if v_member.removed_at is not null then
    return jsonb_build_object(
      'member', private.workspace_member_management_json(p_workspace_id, p_user_id)
    );
  end if;
  if v_member.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  update public.workspace_members member
  set
    status = 'suspended'::public.membership_status,
    suspended_at = coalesce(member.suspended_at, statement_timestamp()),
    removed_at = statement_timestamp(),
    removed_by = v_actor
  where member.workspace_id = p_workspace_id
    and member.user_id = p_user_id;

  with cancelled as (
    update public.workspace_invitations invitation
    set
      cancelled_at = statement_timestamp(),
      cancelled_by = v_actor
    where invitation.workspace_id = p_workspace_id
      and invitation.accepted_at is null
      and invitation.cancelled_at is null
      and invitation.email = (
        select lower(btrim(profile.email))
        from public.profiles profile
        where profile.id = p_user_id
      )
    returning invitation.id, invitation.role
  )
  insert into public.activity_logs (
    workspace_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    metadata_json
  )
  select
    p_workspace_id,
    v_actor,
    'workspace_invitation',
    cancelled.id,
    'workspace.invitation_cancelled',
    jsonb_build_object('role', cancelled.role, 'reason', 'member_removed')
  from cancelled;

  insert into public.activity_logs (
    workspace_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    changes_json
  ) values (
    p_workspace_id,
    v_actor,
    'workspace_member',
    p_user_id,
    'workspace.member_removed',
    jsonb_build_object(
      'status', jsonb_build_object('from', v_member.status, 'to', 'removed')
    )
  );

  return jsonb_build_object(
    'member', private.workspace_member_management_json(p_workspace_id, p_user_id)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_project_board_columns(p_workspace_id uuid, p_ordered_keys text[], p_expected_board_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_board_version integer;
  v_column_count integer;
  v_distinct_count integer;
  v_matched_count integer;
begin
  v_role := private.current_workspace_role(p_workspace_id);
  if v_actor is null or v_role is null or v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_PROJECT_BOARD_CONFIGURATION_FORBIDDEN';
  end if;
  select count(distinct ordered_key.key)::integer
  into v_distinct_count
  from unnest(coalesce(p_ordered_keys, array[]::text[])) as ordered_key(key);

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pta:project-board:' || p_workspace_id::text, 0)
  );
  select setting.version
  into v_board_version
  from public.project_board_settings setting
  where setting.workspace_id = p_workspace_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_PROJECT_BOARD_NOT_FOUND';
  end if;
  if v_board_version is distinct from p_expected_board_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  select count(*)::integer
  into v_column_count
  from public.project_board_columns board_column
  where board_column.workspace_id = p_workspace_id;
  select count(*)::integer
  into v_matched_count
  from public.project_board_columns board_column
  where board_column.workspace_id = p_workspace_id
    and board_column.column_key = any(
      coalesce(p_ordered_keys, array[]::text[])
    );
  if cardinality(coalesce(p_ordered_keys, array[]::text[])) <> v_column_count
     or v_distinct_count <> v_column_count
     or v_matched_count <> v_column_count then
    raise exception using errcode = '22023', message = 'PTA_PROJECT_BOARD_COLUMN_ORDER_INVALID';
  end if;

  update public.project_board_columns board_column
  set position = ordered.ordinality::integer * 1000
  from unnest(p_ordered_keys) with ordinality ordered(key, ordinality)
  where board_column.workspace_id = p_workspace_id
    and board_column.column_key = ordered.key;
  update public.project_board_settings setting
  set version = setting.version + 1,
      updated_at = clock_timestamp(),
      updated_by = v_actor
  where setting.workspace_id = p_workspace_id;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, changes_json
  ) values (
    p_workspace_id, v_actor, 'project_board', p_workspace_id,
    'project_board.columns_reordered',
    jsonb_build_object('ordered_keys', p_ordered_keys)
  );
  return public.get_project_board_configuration(p_workspace_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_resource_categories(p_workspace_id uuid, p_category_ids uuid[], p_expected_snapshot text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role public.workspace_role;
  v_ids uuid[] := coalesce(p_category_ids, '{}'::uuid[]);
  v_active_count integer;
begin
  v_role := private.current_workspace_role(p_workspace_id);
  if p_workspace_id is null
    or v_role is null
    or v_role not in (
      'owner'::public.workspace_role,
      'admin'::public.workspace_role,
      'manager'::public.workspace_role
    ) then
    raise exception using errcode = 'P0002', message = 'PTA_WORKSPACE_NOT_FOUND';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_workspace_id::text, 0)
  );

  if p_expected_snapshot is null
    or private.resource_categories_snapshot(p_workspace_id)
      is distinct from p_expected_snapshot then
    raise exception using errcode = '40001', message = 'PTA_RESOURCE_CATEGORY_CONFLICT';
  end if;

  select count(*) into v_active_count
  from public.resource_categories category
  where category.workspace_id = p_workspace_id
    and category.archived_at is null;

  if cardinality(v_ids) <> v_active_count
    or (select count(distinct id) from unnest(v_ids) id) <> v_active_count
    or exists (
      select 1
      from unnest(v_ids) id
      left join public.resource_categories category
        on category.workspace_id = p_workspace_id
        and category.id = id
        and category.archived_at is null
      where category.id is null
    ) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_CATEGORY_ORDER';
  end if;

  update public.resource_categories category
  set
    position = (ordered.ordinality - 1)::integer,
    updated_at = clock_timestamp()
  from unnest(v_ids) with ordinality ordered(id, ordinality)
  where category.workspace_id = p_workspace_id
    and category.id = ordered.id
    and category.position is distinct from (ordered.ordinality - 1)::integer;

  return public.list_resource_categories(p_workspace_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_task_board_columns(p_workspace_id uuid, p_board_kind text, p_ordered_keys text[], p_expected_board_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_board_version integer;
  v_active_count integer;
  v_distinct_count integer;
  v_matched_count integer;
begin
  v_role := private.current_workspace_role(p_workspace_id);
  if v_actor is null or v_role is null or v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_BOARD_CONFIGURATION_FORBIDDEN';
  end if;
  if p_board_kind not in ('status', 'week') then
    raise exception using errcode = '22023', message = 'PTA_BOARD_KIND_INVALID';
  end if;
  select count(distinct ordered_key.key)::integer into v_distinct_count
  from unnest(coalesce(p_ordered_keys, array[]::text[])) as ordered_key(key);

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'pta:task-board:' || p_workspace_id::text || ':' || p_board_kind,
      0
    )
  );
  select setting.version into v_board_version
  from public.task_board_settings setting
  where setting.workspace_id = p_workspace_id
    and setting.board_kind = p_board_kind
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_BOARD_NOT_FOUND';
  end if;
  if v_board_version is distinct from p_expected_board_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  if p_board_kind = 'status' then
    select count(*)::integer into v_active_count
    from public.task_statuses status
    where status.workspace_id = p_workspace_id and status.is_active;
    select count(*)::integer into v_matched_count
    from public.task_statuses status
    where status.workspace_id = p_workspace_id
      and status.is_active
      and status.semantic_key = any(coalesce(p_ordered_keys, array[]::text[]));
  else
    select count(*)::integer into v_active_count
    from public.task_week_lanes lane
    where lane.workspace_id = p_workspace_id and lane.is_active;
    select count(*)::integer into v_matched_count
    from public.task_week_lanes lane
    where lane.workspace_id = p_workspace_id
      and lane.is_active
      and lane.lane_key = any(coalesce(p_ordered_keys, array[]::text[]));
  end if;

  if cardinality(coalesce(p_ordered_keys, array[]::text[])) <> v_active_count
     or v_distinct_count <> v_active_count
     or v_matched_count <> v_active_count then
    raise exception using errcode = '22023', message = 'PTA_BOARD_COLUMN_ORDER_INVALID';
  end if;

  if p_board_kind = 'status' then
    update public.task_statuses status
    set position = ordered.ordinality::integer * 1000
    from unnest(p_ordered_keys) with ordinality ordered(key, ordinality)
    where status.workspace_id = p_workspace_id
      and status.semantic_key = ordered.key
      and status.is_active;
  else
    update public.task_week_lanes lane
    set position = ordered.ordinality::integer * 1000
    from unnest(p_ordered_keys) with ordinality ordered(key, ordinality)
    where lane.workspace_id = p_workspace_id
      and lane.lane_key = ordered.key
      and lane.is_active;
  end if;

  update public.task_board_settings setting
  set version = setting.version + 1,
      updated_at = clock_timestamp(),
      updated_by = v_actor
  where setting.workspace_id = p_workspace_id
    and setting.board_kind = p_board_kind;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, changes_json
  ) values (
    p_workspace_id, v_actor, 'task_board', p_workspace_id,
    'task_board.columns_reordered',
    jsonb_build_object('board_kind', p_board_kind, 'ordered_keys', p_ordered_keys)
  );
  return public.get_task_board_configuration(p_workspace_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_job_function(p_workspace_id uuid, p_job_function_id uuid, p_expected_version integer, p_name text, p_category text, p_description text DEFAULT NULL::text, p_position integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_function public.job_functions%rowtype;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if not private.can_manage_operating_model(p_workspace_id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 2 and 100 then
    raise exception using errcode = '22023', message = 'PTA_JOB_FUNCTION_NAME_INVALID';
  end if;
  if p_category is null or char_length(btrim(p_category)) not between 2 and 80 then
    raise exception using errcode = '22023', message = 'PTA_JOB_FUNCTION_CATEGORY_INVALID';
  end if;
  if p_description is not null and char_length(p_description) > 1000 then
    raise exception using errcode = '22023', message = 'PTA_JOB_FUNCTION_DESCRIPTION_TOO_LONG';
  end if;
  if p_position is null or p_position < 0 then
    raise exception using errcode = '22023', message = 'PTA_JOB_FUNCTION_POSITION_INVALID';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:operating-model:' || p_workspace_id::text, 0)
  );

  if p_job_function_id is null then
    if p_expected_version is not null then
      raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
    end if;

    insert into public.job_functions (
      workspace_id,
      name,
      category,
      description,
      position,
      is_system,
      created_by
    ) values (
      p_workspace_id,
      btrim(p_name),
      btrim(p_category),
      nullif(btrim(p_description), ''),
      p_position,
      false,
      v_actor
    )
    returning * into v_function;
  else
    if p_expected_version is null or p_expected_version < 1 then
      raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
    end if;

    select job_function.*
    into v_function
    from public.job_functions job_function
    where job_function.workspace_id = p_workspace_id
      and job_function.id = p_job_function_id
    for update;

    if not found or v_function.archived_at is not null then
      raise exception using errcode = 'P0002', message = 'PTA_JOB_FUNCTION_NOT_FOUND';
    end if;
    if v_function.version <> p_expected_version then
      raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
    end if;
    if v_function.is_system and (
      btrim(p_name) <> v_function.name
      or btrim(p_category) <> v_function.category
      or nullif(btrim(p_description), '') is distinct from v_function.description
    ) then
      raise exception using errcode = '23514', message = 'PTA_SYSTEM_JOB_FUNCTION_IMMUTABLE';
    end if;

    update public.job_functions job_function
    set
      name = btrim(p_name),
      category = btrim(p_category),
      description = nullif(btrim(p_description), ''),
      position = p_position
    where job_function.workspace_id = p_workspace_id
      and job_function.id = p_job_function_id
    returning job_function.* into v_function;
  end if;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    p_workspace_id,
    v_actor,
    'job_function',
    v_function.id,
    case when p_job_function_id is null then 'job_function.created' else 'job_function.updated' end,
    jsonb_build_object(
      'name', v_function.name,
      'category', v_function.category,
      'is_system', v_function.is_system
    )
  );

  return jsonb_build_object(
    'id', v_function.id,
    'workspace_id', v_function.workspace_id,
    'system_key', v_function.system_key,
    'name', v_function.name,
    'category', v_function.category,
    'description', v_function.description,
    'position', v_function.position,
    'is_system', v_function.is_system,
    'version', v_function.version
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.save_task_link_with_description(p_task_id uuid, p_url text, p_label text DEFAULT NULL::text, p_description text DEFAULT ''::text, p_link_id uuid DEFAULT NULL::uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb; v_link public.task_links%rowtype;
begin
 if auth.uid() is null or private.task_collaboration_role(p_task_id) is null then raise exception 'PTA_TASK_NOT_FOUND'; end if;
 if char_length(coalesce(p_description,'')) > 1000 then raise exception 'PTA_INVALID_DESCRIPTION'; end if;
 if p_link_id is null then
  v_result := public.add_task_link(p_task_id,p_url,p_label);
 else
  select * into v_link from public.task_links where id=p_link_id and task_id=p_task_id and deleted_at is null for update;
  if not found then raise exception 'PTA_LINK_NOT_FOUND'; end if;
  if p_expected_updated_at is null or v_link.updated_at is distinct from p_expected_updated_at then raise exception 'PTA_VERSION_CONFLICT'; end if;
  v_result := public.update_task_link(p_link_id,p_url,p_label);
 end if;
 update public.task_links set description=btrim(coalesce(p_description,'')), updated_at=clock_timestamp() where id=(v_result->>'id')::uuid;
 return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.search_resource_relation_options(p_workspace_id uuid, p_entity_type text, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_query text := nullif(btrim(p_query), '');
  v_normalized_query text;
  v_limit integer := coalesce(p_limit, 30);
  v_result jsonb;
begin
  if p_workspace_id is null
    or private.current_workspace_role(p_workspace_id) is null then
    raise exception using errcode = 'P0002', message = 'PTA_WORKSPACE_NOT_FOUND';
  end if;

  if p_entity_type is null
    or p_entity_type not in ('task', 'product', 'event', 'tag') then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_RELATION_TYPE';
  end if;

  if v_query is not null and char_length(v_query) > 100 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_SEARCH_QUERY';
  end if;

  if v_limit < 1 or v_limit > 50 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_RELATION_LIMIT';
  end if;

  v_normalized_query := lower(extensions.unaccent(coalesce(v_query, '')));

  if p_entity_type = 'task' then
    select coalesce(
      jsonb_agg(option - 'sort' order by option ->> 'sort' desc),
      '[]'::jsonb
    )
    into v_result
    from (
      select jsonb_build_object(
        'id', task.id,
        'label', task.title,
        'meta', workspace.task_prefix || '-' || lpad(task.task_number::text, 6, '0'),
        'color', null,
        'sort', lpad(task.task_number::text, 20, '0')
      ) as option
      from (select * from public.tasks where private.can_read_task(id)) task
      join public.workspaces workspace on workspace.id = task.workspace_id
      where task.workspace_id = p_workspace_id
        and task.archived_at is null
        and (
          v_query is null
          or lower(extensions.unaccent(task.title)) like '%' || v_normalized_query || '%'
          or lower(workspace.task_prefix || '-' || lpad(task.task_number::text, 6, '0')) like '%' || v_normalized_query || '%'
        )
      order by task.updated_at desc, task.id
      limit v_limit
    ) options;
  elsif p_entity_type = 'product' then
    select coalesce(jsonb_agg(option order by option ->> 'label'), '[]'::jsonb)
    into v_result
    from (
      select jsonb_build_object(
        'id', product.id,
        'label', product.name,
        'meta', null,
        'color', null
      ) as option
      from public.products product
      where product.workspace_id = p_workspace_id
        and product.archived_at is null
        and (
          v_query is null
          or lower(extensions.unaccent(product.name)) like '%' || v_normalized_query || '%'
        )
      order by product.name, product.id
      limit v_limit
    ) options;
  elsif p_entity_type = 'event' then
    select coalesce(jsonb_agg(option order by option ->> 'label'), '[]'::jsonb)
    into v_result
    from (
      select jsonb_build_object(
        'id', event.id,
        'label', event.name,
        'meta', case
          when event.start_date is null then null
          else to_char(event.start_date, 'DD/MM/YYYY')
        end,
        'color', null
      ) as option
      from (select * from public.events where private.can_read_event(id)) event
      where event.workspace_id = p_workspace_id
        and event.archived_at is null
        and (
          v_query is null
          or lower(extensions.unaccent(event.name)) like '%' || v_normalized_query || '%'
        )
      order by event.start_date desc nulls last, event.name, event.id
      limit v_limit
    ) options;
  else
    select coalesce(jsonb_agg(option order by option ->> 'label'), '[]'::jsonb)
    into v_result
    from (
      select jsonb_build_object(
        'id', tag.id,
        'label', tag.name,
        'meta', null,
        'color', tag.color
      ) as option
      from public.tags tag
      where tag.workspace_id = p_workspace_id
        and tag.archived_at is null
        and (
          v_query is null
          or lower(extensions.unaccent(tag.name)) like '%' || v_normalized_query || '%'
        )
      order by tag.name, tag.id
      limit v_limit
    ) options;
  end if;

  return jsonb_build_object('items', v_result);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_project_team(p_workspace_id uuid, p_project_id uuid, p_team_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_project public.events%rowtype; v_old_team uuid;
begin
  if auth.uid() is null or not private.can_manage_operating_model(p_workspace_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;
  -- Lock the destination before the project, consistently with archival.
  if p_team_id is not null then
    perform 1 from public.teams where workspace_id = p_workspace_id and id = p_team_id
      and archived_at is null for share;
    if not found then raise exception using errcode = '23514', message = 'PTA_TEAM_NOT_ACTIVE'; end if;
  end if;
  select * into v_project from public.events where workspace_id = p_workspace_id
    and id = p_project_id and archived_at is null for update;
  if not found then raise exception using errcode = 'P0002', message = 'PTA_EVENT_NOT_FOUND'; end if;
  if v_project.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if v_project.primary_team_id is not distinct from p_team_id then
    return jsonb_build_object('id', v_project.id, 'version', v_project.version);
  end if;
  v_old_team := v_project.primary_team_id;
  update public.events set primary_team_id = p_team_id, updated_by = auth.uid()
    where workspace_id = p_workspace_id and id = p_project_id returning * into v_project;
  insert into public.activity_logs(workspace_id,actor_id,entity_type,entity_id,action,changes_json)
    values(p_workspace_id,auth.uid(),'event',p_project_id,'event.team_changed',
      jsonb_build_object('previous_team_id',v_old_team,'primary_team_id',p_team_id));
  return jsonb_build_object('id',v_project.id,'version',v_project.version);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_resource_favorite(p_resource_id uuid, p_is_favorite boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace_id uuid;
begin
  if p_resource_id is null
    or p_is_favorite is null
    or not private.can_view_resource(p_resource_id) then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_NOT_FOUND';
  end if;

  select workspace_id into v_workspace_id from public.resources where id = p_resource_id;

  if p_is_favorite then
    insert into public.resource_favorites (workspace_id, resource_id, user_id)
    values (v_workspace_id, p_resource_id, (select auth.uid()))
    on conflict (workspace_id, resource_id, user_id) do nothing;
  else
    delete from public.resource_favorites
    where workspace_id = v_workspace_id
      and resource_id = p_resource_id
      and user_id = (select auth.uid());
  end if;

  return jsonb_build_object('resource_id', p_resource_id, 'is_favorite', p_is_favorite);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_task_board_lane_link(p_workspace_id uuid, p_status_id uuid, p_week_lane_key text, p_direction text, p_enabled boolean, p_expected_board_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_board_version integer;
begin
  v_role := private.current_workspace_role(p_workspace_id);
  if v_actor is null or v_role is null or v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_BOARD_CONFIGURATION_FORBIDDEN';
  end if;
  if p_direction not in ('both', 'status_to_week', 'week_to_status')
     or p_enabled is null then
    raise exception using errcode = '22023', message = 'PTA_BOARD_LINK_DIRECTION_INVALID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pta:task-board:' || p_workspace_id::text, 0)
  );
  select setting.version into v_board_version
  from public.task_board_settings setting
  where setting.workspace_id = p_workspace_id
    and setting.board_kind = 'status'
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_BOARD_NOT_FOUND';
  end if;
  if v_board_version is distinct from p_expected_board_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if not exists (
    select 1 from public.task_statuses status
    where status.workspace_id = p_workspace_id
      and status.id = p_status_id
      and status.is_active
  ) or not exists (
    select 1 from public.task_week_lanes lane
    where lane.workspace_id = p_workspace_id
      and lane.lane_key = p_week_lane_key
      and lane.is_active
  ) then
    raise exception using errcode = '23503', message = 'PTA_BOARD_LINK_TARGET_INVALID';
  end if;

  if p_enabled then
    if exists(select 1 from public.task_status_week_lane_links link where link.workspace_id = p_workspace_id and link.week_lane_key = p_week_lane_key and link.status_id <> p_status_id) then
      raise exception using errcode = '22023', message = 'PTA_BOARD_LANE_ALREADY_CONNECTED';
    end if;
    delete from public.task_status_week_lane_links link
      where link.workspace_id = p_workspace_id and link.status_id = p_status_id and link.week_lane_key <> p_week_lane_key;
    insert into public.task_status_week_lane_links (
      workspace_id, status_id, week_lane_key, direction
    ) values (
      p_workspace_id, p_status_id, p_week_lane_key, p_direction
    )
    on conflict (workspace_id, status_id, week_lane_key) do update
      set direction = excluded.direction,
          version = task_status_week_lane_links.version + 1,
          updated_at = clock_timestamp();
  else
    delete from public.task_status_week_lane_links link
    where link.workspace_id = p_workspace_id
      and link.status_id = p_status_id
      and link.week_lane_key = p_week_lane_key;
  end if;

  update public.task_board_settings setting
  set version = setting.version + 1,
      updated_at = clock_timestamp(),
      updated_by = v_actor
  where setting.workspace_id = p_workspace_id
    and setting.board_kind in ('status', 'week');

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, changes_json
  ) values (
    p_workspace_id, v_actor, 'task_board', p_workspace_id,
    'task_board.lane_link_updated',
    jsonb_build_object(
      'status_id', p_status_id,
      'week_lane_key', p_week_lane_key,
      'direction', p_direction,
      'enabled', p_enabled
    )
  );
  return public.get_task_board_configuration(p_workspace_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_task_card_archived(p_workspace_id uuid, p_task_id uuid, p_expected_version integer, p_archived boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_task public.tasks%rowtype; v_role public.workspace_role; v_version integer;
begin
  v_role := private.current_workspace_role(p_workspace_id);
  if auth.uid() is null or v_role is null or v_role = 'viewer' then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  select * into v_task from public.tasks where workspace_id = p_workspace_id and id = p_task_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'PTA_TASK_NOT_FOUND'; end if;
  if v_task.version is distinct from p_expected_version then raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT'; end if;
  if p_archived is null then raise exception using errcode = '22023', message = 'PTA_INVALID_ARCHIVE_STATE'; end if;
  if p_archived and not private.can_edit_task(p_task_id) then raise exception using errcode = '42501', message = 'PTA_FORBIDDEN'; end if;
  if not p_archived and v_role not in ('owner','admin','manager') and v_task.archived_by is distinct from auth.uid() then raise exception using errcode = '42501', message = 'PTA_FORBIDDEN'; end if;
  update public.tasks set archived_at = case when p_archived then clock_timestamp() else null end,
    archived_by = case when p_archived then auth.uid() else null end, updated_by = auth.uid()
    where workspace_id = p_workspace_id and id = p_task_id returning version into v_version;
  insert into public.activity_logs(workspace_id,actor_id,entity_type,entity_id,action)
    values(p_workspace_id,auth.uid(),'task',p_task_id,case when p_archived then 'task.archived' else 'task.restored' end);
  return v_version;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_task_custom_field_value(p_task_id uuid, p_field_id uuid, p_expected_task_version integer, p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_task public.tasks%rowtype;
  v_field public.task_custom_field_definitions%rowtype;
  v_text text;
  v_option_id uuid;
begin
  select task.* into v_task
  from public.tasks task
  where task.id = p_task_id and task.archived_at is null
  for update;

  if not found or v_actor is null or not private.can_edit_task(p_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_task.version <> p_expected_task_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  select field.* into v_field
  from public.task_custom_field_definitions field
  where field.id = p_field_id
    and field.workspace_id = v_task.workspace_id
    and field.archived_at is null;
  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_CUSTOM_FIELD_NOT_FOUND';
  end if;

  if p_value is null or p_value = 'null'::jsonb then
    delete from public.task_custom_field_values value
    where value.workspace_id = v_task.workspace_id
      and value.task_id = p_task_id
      and value.field_id = p_field_id;
  else
    if v_field.field_type = 'text' then
      if jsonb_typeof(p_value) <> 'string' or char_length(p_value #>> '{}') > 500 then
        raise exception using errcode = '22023', message = 'PTA_INVALID_CUSTOM_FIELD_VALUE';
      end if;
    elsif v_field.field_type = 'number' then
      if jsonb_typeof(p_value) <> 'number' then
        raise exception using errcode = '22023', message = 'PTA_INVALID_CUSTOM_FIELD_VALUE';
      end if;
    elsif v_field.field_type = 'date' then
      v_text := p_value #>> '{}';
      if jsonb_typeof(p_value) <> 'string' or v_text !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception using errcode = '22023', message = 'PTA_INVALID_CUSTOM_FIELD_VALUE';
      end if;
    elsif v_field.field_type = 'boolean' then
      if jsonb_typeof(p_value) <> 'boolean' then
        raise exception using errcode = '22023', message = 'PTA_INVALID_CUSTOM_FIELD_VALUE';
      end if;
    elsif v_field.field_type = 'single_select' then
      if jsonb_typeof(p_value) <> 'string' then
        raise exception using errcode = '22023', message = 'PTA_INVALID_CUSTOM_FIELD_VALUE';
      end if;
      begin
        v_option_id := (p_value #>> '{}')::uuid;
      exception when invalid_text_representation then
        raise exception using errcode = '22023', message = 'PTA_INVALID_CUSTOM_FIELD_VALUE';
      end;
      if not exists (
        select 1 from public.task_custom_field_options option
        where option.workspace_id = v_task.workspace_id
          and option.field_id = p_field_id
          and option.id = v_option_id
          and option.archived_at is null
      ) then
        raise exception using errcode = '22023', message = 'PTA_INVALID_CUSTOM_FIELD_VALUE';
      end if;
    end if;

    insert into public.task_custom_field_values (
      workspace_id, task_id, field_id, text_value, number_value,
      date_value, boolean_value, option_id, updated_by
    ) values (
      v_task.workspace_id,
      p_task_id,
      p_field_id,
      case when v_field.field_type = 'text' then p_value #>> '{}' end,
      case when v_field.field_type = 'number' then (p_value #>> '{}')::numeric end,
      case when v_field.field_type = 'date' then (p_value #>> '{}')::date end,
      case when v_field.field_type = 'boolean' then (p_value #>> '{}')::boolean end,
      case when v_field.field_type = 'single_select' then v_option_id end,
      v_actor
    )
    on conflict (workspace_id, task_id, field_id) do update set
      text_value = excluded.text_value,
      number_value = excluded.number_value,
      date_value = excluded.date_value,
      boolean_value = excluded.boolean_value,
      option_id = excluded.option_id,
      updated_by = excluded.updated_by,
      updated_at = clock_timestamp();
  end if;

  update public.tasks task
  set updated_by = v_actor
  where task.id = p_task_id and task.version = p_expected_task_version
  returning * into v_task;
  if not found then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    v_task.workspace_id, v_actor, 'task', v_task.id, 'task.custom_field_updated',
    jsonb_build_object('field_id', p_field_id)
  );

  return jsonb_build_object('id', v_task.id, 'version', v_task.version, 'updated_at', v_task.updated_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_task_primary_assignee(p_task_id uuid, p_user_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := auth.uid(); v_task public.tasks%rowtype;
begin
  if v_actor is null or not private.can_edit_task(p_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  select * into v_task from public.tasks where id = p_task_id for update;
  if not found or not private.can_edit_task(p_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if private.current_workspace_role(v_task.workspace_id) not in ('owner', 'admin', 'manager') then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_task.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if p_user_id is not null and not exists (
    select 1 from public.workspace_members wm
    join public.profiles p on p.id = wm.user_id and p.is_active
    where wm.workspace_id = v_task.workspace_id
      and wm.user_id = p_user_id
      and wm.status = 'active'
      and wm.role <> 'viewer'
  ) then raise exception using errcode = '23514', message = 'PTA_ASSIGNEE_NOT_ACTIVE_MEMBER'; end if;
  delete from public.task_assignees
  where workspace_id = v_task.workspace_id and task_id = p_task_id and is_primary;
  if p_user_id is not null then
    insert into public.task_assignees (workspace_id, task_id, user_id, is_primary, assigned_by)
    values (v_task.workspace_id, p_task_id, p_user_id, true, v_actor)
    on conflict (workspace_id, task_id, user_id) do update set
      is_primary = true,
      assigned_by = excluded.assigned_by,
      assigned_at = clock_timestamp();
  end if;
  update public.tasks set updated_by = v_actor where id = p_task_id returning * into v_task;
  return jsonb_build_object('id', v_task.id, 'primary_assignee_id', p_user_id, 'version', v_task.version);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_team_member_functions(p_team_id uuid, p_user_id uuid, p_job_function_ids uuid[], p_primary_job_function_id uuid, p_expected_team_member_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_team public.teams%rowtype;
  v_member public.team_members%rowtype;
  v_function_ids uuid[] := coalesce(p_job_function_ids, '{}'::uuid[]);
  v_functions jsonb;
begin
  if auth.uid() is null or not private.can_read_team(p_team_id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if p_expected_team_member_version is null or p_expected_team_member_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;
  if exists (select 1 from unnest(v_function_ids) function_id where function_id is null) then
    raise exception using errcode = '22023', message = 'PTA_JOB_FUNCTION_LIST_INVALID';
  end if;
  if cardinality(v_function_ids) <> (
    select count(distinct function_id) from unnest(v_function_ids) function_id
  ) then
    raise exception using errcode = '22023', message = 'PTA_JOB_FUNCTION_LIST_DUPLICATED';
  end if;
  if p_primary_job_function_id is not null
     and not p_primary_job_function_id = any(v_function_ids) then
    raise exception using errcode = '22023', message = 'PTA_PRIMARY_JOB_FUNCTION_NOT_SELECTED';
  end if;

  select team.* into v_team
  from public.teams team
  where team.id = p_team_id
    and team.archived_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_TEAM_NOT_FOUND';
  end if;
  if not private.can_manage_team_members(v_team.id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;
  if (
    select count(*)
    from public.job_functions job_function
    where job_function.workspace_id = v_team.workspace_id
      and job_function.id = any(v_function_ids)
      and job_function.archived_at is null
  ) <> cardinality(v_function_ids) then
    raise exception using errcode = '23514', message = 'PTA_JOB_FUNCTION_NOT_ACTIVE';
  end if;

  select member.* into v_member
  from public.team_members member
  where member.workspace_id = v_team.workspace_id
    and member.team_id = v_team.id
    and member.user_id = p_user_id
    and member.removed_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_TEAM_MEMBER_NOT_FOUND';
  end if;
  if v_member.version <> p_expected_team_member_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  update public.team_members member
  set role = member.role
  where member.workspace_id = v_member.workspace_id
    and member.team_id = v_member.team_id
    and member.user_id = v_member.user_id
  returning member.* into v_member;

  update public.team_member_functions assignment
  set is_primary = false
  where assignment.workspace_id = v_member.workspace_id
    and assignment.team_id = v_member.team_id
    and assignment.user_id = v_member.user_id
    and assignment.is_primary
    and assignment.archived_at is null;

  update public.team_member_functions assignment
  set
    is_primary = false,
    archived_at = statement_timestamp(),
    archived_by = v_actor
  where assignment.workspace_id = v_member.workspace_id
    and assignment.team_id = v_member.team_id
    and assignment.user_id = v_member.user_id
    and assignment.archived_at is null
    and not assignment.job_function_id = any(v_function_ids);

  insert into public.team_member_functions (
    workspace_id,
    team_id,
    user_id,
    job_function_id,
    is_primary,
    assigned_by
  )
  select
    v_member.workspace_id,
    v_member.team_id,
    v_member.user_id,
    selected.function_id,
    selected.function_id = p_primary_job_function_id,
    v_actor
  from unnest(v_function_ids) selected(function_id)
  on conflict (workspace_id, team_id, user_id, job_function_id) do update
  set
    is_primary = excluded.is_primary,
    archived_at = null,
    archived_by = null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', job_function.id,
        'system_key', job_function.system_key,
        'name', job_function.name,
        'is_primary', assignment.is_primary,
        'assignment_version', assignment.version
      )
      order by assignment.is_primary desc, job_function.position, job_function.id
    ),
    '[]'::jsonb
  )
  into v_functions
  from public.team_member_functions assignment
  join public.job_functions job_function
    on job_function.workspace_id = assignment.workspace_id
    and job_function.id = assignment.job_function_id
  where assignment.workspace_id = v_member.workspace_id
    and assignment.team_id = v_member.team_id
    and assignment.user_id = v_member.user_id
    and assignment.archived_at is null;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    v_member.workspace_id,
    v_actor,
    'team_member',
    v_member.team_id,
    'team.member_functions_changed',
    jsonb_build_object(
      'user_id', v_member.user_id,
      'job_function_ids', to_jsonb(v_function_ids),
      'primary_job_function_id', p_primary_job_function_id
    )
  );

  return jsonb_build_object(
    'workspace_id', v_member.workspace_id,
    'team_id', v_member.team_id,
    'user_id', v_member.user_id,
    'team_member_version', v_member.version,
    'functions', v_functions
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.suspend_workspace_member(p_workspace_id uuid, p_user_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_role public.workspace_role;
  v_member public.workspace_members%rowtype;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:workspace-team:' || p_workspace_id::text, 0)
  );
  v_actor_role := private.current_workspace_role(p_workspace_id);
  if v_actor_role is null or v_actor_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;

  select member.*
  into v_member
  from public.workspace_members member
  where member.workspace_id = p_workspace_id
    and member.user_id = p_user_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_MEMBER_NOT_FOUND';
  end if;
  if v_member.role = 'owner'::public.workspace_role then
    raise exception using errcode = '23514', message = 'PTA_LAST_OWNER_REQUIRED';
  end if;
  if v_member.removed_at is not null then
    raise exception using errcode = '23514', message = 'PTA_MEMBER_REMOVED';
  end if;
  if v_member.status = 'suspended'::public.membership_status then
    return jsonb_build_object(
      'member', private.workspace_member_management_json(p_workspace_id, p_user_id)
    );
  end if;
  if v_member.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  update public.workspace_members member
  set
    status = 'suspended'::public.membership_status,
    suspended_at = statement_timestamp()
  where member.workspace_id = p_workspace_id
    and member.user_id = p_user_id;

  insert into public.activity_logs (
    workspace_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    changes_json
  ) values (
    p_workspace_id,
    v_actor,
    'workspace_member',
    p_user_id,
    'workspace.member_suspended',
    jsonb_build_object(
      'status', jsonb_build_object('from', 'active', 'to', 'suspended')
    )
  );

  return jsonb_build_object(
    'member', private.workspace_member_management_json(p_workspace_id, p_user_id)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.toggle_event_milestone(p_milestone_id uuid, p_expected_version integer, p_completed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_milestone public.event_milestones%rowtype;
  v_role public.workspace_role;
begin
  select * into v_milestone from public.event_milestones where id = p_milestone_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'PTA_MILESTONE_NOT_FOUND'; end if;
  v_role := private.current_workspace_role(v_milestone.workspace_id);
  if v_actor is null or v_role is null or v_role not in ('owner', 'admin', 'manager') then raise exception using errcode = '42501', message = 'PTA_FORBIDDEN'; end if;
  update public.event_milestones milestone set
    completed_at = case when p_completed then clock_timestamp() else null end,
    updated_by = v_actor
  where milestone.id = p_milestone_id and milestone.version = p_expected_version
  returning * into v_milestone;
  if not found then raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT'; end if;
  insert into public.activity_logs (workspace_id, actor_id, entity_type, entity_id, action, metadata_json)
  values (v_milestone.workspace_id, v_actor, 'event_milestone', v_milestone.id,
    case when p_completed then 'event.milestone_completed' else 'event.milestone_reopened' end,
    jsonb_build_object('event_id', v_milestone.event_id));
  return jsonb_build_object('id', v_milestone.id, 'version', v_milestone.version, 'completed_at', v_milestone.completed_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.toggle_task_checklist_item(p_item_id uuid, p_is_completed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_item public.task_checklist_items%rowtype;
begin
  select item.*
  into v_item
  from public.task_checklist_items item
  where item.id = p_item_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_CHECKLIST_ITEM_NOT_FOUND';
  end if;
  v_role := private.task_collaboration_role(v_item.task_id);
  if v_role is null then
    raise exception using errcode = 'P0002', message = 'PTA_CHECKLIST_ITEM_NOT_FOUND';
  end if;
  if v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role,
    'member'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_is_completed is null then
    raise exception using errcode = '22023', message = 'PTA_INVALID_CHECKLIST_STATE';
  end if;

  if v_item.is_completed is distinct from p_is_completed then
    update public.task_checklist_items item
    set
      is_completed = p_is_completed,
      completed_by = case when p_is_completed then v_actor else null end,
      completed_at = case when p_is_completed then clock_timestamp() else null end,
      updated_at = clock_timestamp()
    where item.id = p_item_id
    returning * into v_item;

    update public.task_checklists checklist
    set updated_at = clock_timestamp()
    where checklist.workspace_id = v_item.workspace_id
      and checklist.task_id = v_item.task_id
      and checklist.id = v_item.checklist_id;
  end if;

  return jsonb_build_object(
    'id', v_item.id,
    'checklist_id', v_item.checklist_id,
    'task_id', v_item.task_id,
    'is_completed', v_item.is_completed,
    'completed_by', v_item.completed_by,
    'completed_at', v_item.completed_at,
    'updated_at', v_item.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.transfer_workspace_ownership(p_workspace_id uuid, p_new_owner_id uuid, p_expected_owner_version integer, p_expected_new_owner_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_role public.workspace_role;
  v_owner public.workspace_members%rowtype;
  v_new_owner public.workspace_members%rowtype;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if p_expected_owner_version is null or p_expected_owner_version < 1
     or p_expected_new_owner_version is null or p_expected_new_owner_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:workspace-team:' || p_workspace_id::text, 0)
  );
  v_actor_role := private.current_workspace_role(p_workspace_id);
  if v_actor_role is distinct from 'owner'::public.workspace_role then
    raise exception using errcode = '42501', message = 'PTA_OWNER_REQUIRED';
  end if;

  perform 1
  from public.workspace_members member
  where member.workspace_id = p_workspace_id
    and member.user_id in (v_actor, p_new_owner_id)
  order by member.user_id
  for update;

  select member.*
  into v_owner
  from public.workspace_members member
  where member.workspace_id = p_workspace_id
    and member.user_id = v_actor;

  select member.*
  into v_new_owner
  from public.workspace_members member
  where member.workspace_id = p_workspace_id
    and member.user_id = p_new_owner_id;

  if v_new_owner.user_id is null then
    raise exception using errcode = 'P0002', message = 'PTA_MEMBER_NOT_FOUND';
  end if;
  if p_new_owner_id = v_actor then
    return jsonb_build_object(
      'previous_owner', private.workspace_member_management_json(p_workspace_id, v_actor),
      'new_owner', private.workspace_member_management_json(p_workspace_id, v_actor)
    );
  end if;
  if v_owner.version <> p_expected_owner_version
     or v_new_owner.version <> p_expected_new_owner_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if v_new_owner.status <> 'active'::public.membership_status
     or v_new_owner.removed_at is not null then
    raise exception using errcode = '23514', message = 'PTA_NEW_OWNER_MUST_BE_ACTIVE';
  end if;
  if not exists (
    select 1
    from public.profiles profile
    where profile.id = p_new_owner_id
      and profile.is_active
  ) then
    raise exception using errcode = '23514', message = 'PTA_NEW_OWNER_MUST_BE_ACTIVE';
  end if;

  update public.workspace_members member
  set role = 'admin'::public.workspace_role
  where member.workspace_id = p_workspace_id
    and member.user_id = v_actor;

  update public.workspace_members member
  set role = 'owner'::public.workspace_role
  where member.workspace_id = p_workspace_id
    and member.user_id = p_new_owner_id;

  if (
    select count(*)
    from public.workspace_members member
    join public.profiles profile
      on profile.id = member.user_id
      and profile.is_active
    where member.workspace_id = p_workspace_id
      and member.role = 'owner'::public.workspace_role
      and member.status = 'active'::public.membership_status
      and member.removed_at is null
  ) <> 1 then
    raise exception using errcode = '23514', message = 'PTA_LAST_OWNER_REQUIRED';
  end if;

  insert into public.activity_logs (
    workspace_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    changes_json,
    metadata_json
  ) values (
    p_workspace_id,
    v_actor,
    'workspace_member',
    p_new_owner_id,
    'workspace.ownership_transferred',
    jsonb_build_object(
      'previous_owner_role', jsonb_build_object('from', 'owner', 'to', 'admin'),
      'new_owner_role', jsonb_build_object('from', v_new_owner.role, 'to', 'owner')
    ),
    jsonb_build_object('previous_owner_id', v_actor)
  );

  return jsonb_build_object(
    'previous_owner', private.workspace_member_management_json(p_workspace_id, v_actor),
    'new_owner', private.workspace_member_management_json(p_workspace_id, p_new_owner_id)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.unlink_task_subtask(p_parent_task_id uuid, p_child_task_id uuid, p_expected_parent_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_parent public.tasks%rowtype;
begin
  select task.* into v_parent
  from public.tasks task
  where task.id = p_parent_task_id and task.archived_at is null
  for update;

  if not found or v_actor is null or not private.can_edit_task(p_parent_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_parent.version <> p_expected_parent_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if not exists (
    select 1 from public.task_subtasks relation
    where relation.workspace_id = v_parent.workspace_id
      and relation.parent_task_id = p_parent_task_id
      and relation.child_task_id = p_child_task_id
  ) then
    raise exception using errcode = 'P0002', message = 'PTA_SUBTASK_NOT_FOUND';
  end if;

  delete from public.task_subtasks relation
  where relation.workspace_id = v_parent.workspace_id
    and relation.parent_task_id = p_parent_task_id
    and relation.child_task_id = p_child_task_id;

  update public.tasks task
  set version = task.version + 1, updated_at = now()
  where task.id = v_parent.id
  returning task.* into v_parent;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    v_parent.workspace_id, v_actor, 'task', v_parent.id,
    'task.subtask_unlinked', jsonb_build_object('child_task_id', p_child_task_id)
  );

  return jsonb_build_object(
    'parent_task_id', v_parent.id,
    'child_task_id', p_child_task_id,
    'parent_version', v_parent.version,
    'unlinked', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_event_milestone(p_workspace_id uuid, p_milestone_id uuid, p_expected_version integer, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_milestone public.event_milestones%rowtype;
  v_phase_id uuid;
begin
  if v_actor is null
     or coalesce(private.current_workspace_role(p_workspace_id) not in ('owner', 'admin', 'manager'), true) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception using errcode = '22023', message = 'PTA_PATCH_MUST_BE_OBJECT';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_patch) patch(key)
    where patch.key <> all (array['title', 'due_date', 'event_phase_id']::text[])
  ) then
    raise exception using errcode = '22023', message = 'PTA_PATCH_HAS_UNSUPPORTED_FIELDS';
  end if;

  select milestone.* into v_milestone
  from public.event_milestones milestone
  where milestone.workspace_id = p_workspace_id
    and milestone.id = p_milestone_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_MILESTONE_NOT_FOUND';
  end if;
  if v_milestone.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  v_phase_id := case
    when p_patch ? 'event_phase_id' then nullif(p_patch->>'event_phase_id', '')::uuid
    else v_milestone.event_phase_id
  end;
  if v_phase_id is not null and not exists (
    select 1 from public.event_phases phase
    where phase.workspace_id = p_workspace_id
      and phase.event_id = v_milestone.event_id
      and phase.id = v_phase_id
      and phase.archived_at is null
  ) then
    raise exception using errcode = '23514', message = 'PTA_PHASE_NOT_ACTIVE';
  end if;

  update public.event_milestones milestone set
    title = case when p_patch ? 'title' then p_patch->>'title' else milestone.title end,
    due_date = case when p_patch ? 'due_date' then nullif(p_patch->>'due_date', '')::date else milestone.due_date end,
    event_phase_id = v_phase_id,
    updated_by = v_actor
  where milestone.workspace_id = p_workspace_id
    and milestone.id = p_milestone_id
    and milestone.version = p_expected_version
  returning * into v_milestone;
  if not found then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, changes_json
  ) values (
    p_workspace_id, v_actor, 'event_milestone', v_milestone.id,
    'event.milestone_updated', p_patch
  );

  return jsonb_build_object(
    'id', v_milestone.id,
    'version', v_milestone.version,
    'title', v_milestone.title,
    'due_date', v_milestone.due_date,
    'event_phase_id', v_milestone.event_phase_id,
    'updated_at', v_milestone.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_event_operational(p_event_id uuid, p_expected_version integer, p_patch jsonb, p_member_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_event public.events%rowtype;
  v_role public.workspace_role;
  v_owner_id uuid;
  v_product_id uuid;
begin
  select * into v_event from public.events where id = p_event_id and archived_at is null for update;
  if not found then raise exception using errcode = 'P0002', message = 'PTA_EVENT_NOT_FOUND'; end if;
  v_role := private.current_workspace_role(v_event.workspace_id);
  if v_actor is null or v_role is null or v_role not in ('owner', 'admin', 'manager') then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_event.version <> p_expected_version then raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT'; end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then raise exception using errcode = '22023', message = 'PTA_PATCH_MUST_BE_OBJECT'; end if;
  if exists (select 1 from jsonb_object_keys(p_patch) as patch_key(key) where patch_key.key <> all(array['name', 'status', 'summary', 'objective', 'success_metric', 'health_override', 'product_id', 'owner_id', 'start_date', 'end_date']::text[])) then
    raise exception using errcode = '22023', message = 'PTA_PATCH_HAS_UNSUPPORTED_FIELDS';
  end if;
  v_owner_id := case when p_patch ? 'owner_id' then nullif(p_patch->>'owner_id', '')::uuid else v_event.owner_id end;
  v_product_id := case when p_patch ? 'product_id' then nullif(p_patch->>'product_id', '')::uuid else v_event.product_id end;
  if v_owner_id is not null and not private.portfolio_member_is_active(v_event.workspace_id, v_owner_id) then raise exception using errcode = '23514', message = 'PTA_OWNER_NOT_ACTIVE_MEMBER'; end if;
  if v_product_id is not null and not exists (select 1 from public.products where id = v_product_id and workspace_id = v_event.workspace_id and archived_at is null) then raise exception using errcode = '23514', message = 'PTA_PRODUCT_NOT_ACTIVE'; end if;
  if v_product_id is distinct from v_event.product_id and exists (
    select 1 from public.tasks task
    where task.event_id = v_event.id
      and task.archived_at is null
      and task.product_id is distinct from v_product_id
  ) then
    raise exception using errcode = '23514', message = 'PTA_EVENT_PRODUCT_HAS_TASKS_MISMATCH';
  end if;
  if p_member_ids is not null and not private.portfolio_members_valid(v_event.workspace_id, p_member_ids) then raise exception using errcode = '23514', message = 'PTA_TEAM_MEMBER_NOT_ACTIVE'; end if;

  update public.events event set
    name = case when p_patch ? 'name' then p_patch->>'name' else event.name end,
    status = case when p_patch ? 'status' then p_patch->>'status' else event.status end,
    summary = case when p_patch ? 'summary' then p_patch->>'summary' else event.summary end,
    objective = case when p_patch ? 'objective' then p_patch->>'objective' else event.objective end,
    success_metric = case when p_patch ? 'success_metric' then p_patch->>'success_metric' else event.success_metric end,
    health_override = case when p_patch ? 'health_override' then nullif(p_patch->>'health_override', '') else event.health_override end,
    product_id = v_product_id,
    owner_id = v_owner_id,
    start_date = case when p_patch ? 'start_date' then nullif(p_patch->>'start_date', '')::date else event.start_date end,
    end_date = case when p_patch ? 'end_date' then nullif(p_patch->>'end_date', '')::date else event.end_date end,
    updated_by = v_actor
  where event.id = p_event_id and event.version = p_expected_version
  returning * into v_event;
  if not found then raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT'; end if;

  if p_member_ids is not null then
    delete from public.event_members where event_id = v_event.id;
    insert into public.event_members (workspace_id, event_id, user_id, added_by)
    select v_event.workspace_id, v_event.id, member_id, v_actor
    from (select distinct member_id from unnest(p_member_ids) member_id where member_id is not null) requested;
  end if;
  insert into public.activity_logs (workspace_id, actor_id, entity_type, entity_id, action, changes_json)
  values (v_event.workspace_id, v_actor, 'event', v_event.id, 'event.updated', jsonb_build_object('fields', (select jsonb_agg(patch_key.key) from jsonb_object_keys(p_patch) as patch_key(key))));
  return jsonb_build_object('id', v_event.id, 'version', v_event.version, 'updated_at', v_event.updated_at);
end;
$function$

