CREATE OR REPLACE FUNCTION public.update_operating_team(p_team_id uuid, p_expected_version integer, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_team public.teams%rowtype;
begin
  if auth.uid() is null or not private.can_read_team(p_team_id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception using errcode = '22023', message = 'PTA_PATCH_MUST_BE_OBJECT';
  end if;
  if exists (
    select 1
    from jsonb_object_keys(p_patch) as patch_key(key_name)
    where patch_key.key_name <> all (array['name', 'slug', 'description', 'color']::text[])
  ) then
    raise exception using errcode = '22023', message = 'PTA_PATCH_HAS_UNSUPPORTED_FIELDS';
  end if;

  select team.*
  into v_team
  from public.teams team
  where team.id = p_team_id
  for update;

  if not found or v_team.archived_at is not null then
    raise exception using errcode = 'P0002', message = 'PTA_TEAM_NOT_FOUND';
  end if;
  if not private.can_manage_operating_model(v_team.workspace_id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;
  if v_team.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  update public.teams team
  set
    name = case when p_patch ? 'name' then p_patch ->> 'name' else team.name end,
    slug = case when p_patch ? 'slug' then p_patch ->> 'slug' else team.slug end,
    description = case when p_patch ? 'description' then p_patch ->> 'description' else team.description end,
    color = case when p_patch ? 'color' then p_patch ->> 'color' else team.color end
  where team.id = p_team_id
  returning team.* into v_team;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    v_team.workspace_id,
    v_actor,
    'team',
    v_team.id,
    'team.updated',
    jsonb_build_object(
      'fields', (
        select jsonb_agg(patch_key.key_name)
        from jsonb_object_keys(p_patch) as patch_key(key_name)
      )
    )
  );

  return to_jsonb(v_team) - 'archived_by';
end;
$function$

CREATE OR REPLACE FUNCTION public.update_own_profile(p_full_name text, p_pronouns text, p_job_title text, p_department text, p_bio text, p_avatar_path text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_name text := btrim(coalesce(p_full_name, ''));
  v_pronouns text := nullif(btrim(coalesce(p_pronouns, '')), '');
  v_job_title text := nullif(btrim(coalesce(p_job_title, '')), '');
  v_department text := nullif(btrim(coalesce(p_department, '')), '');
  v_bio text := nullif(btrim(coalesce(p_bio, '')), '');
  v_avatar_path text := nullif(btrim(coalesce(p_avatar_path, '')), '');
  v_name_parts text[];
  v_initials text;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;

  select profile.*
  into v_profile
  from public.profiles profile
  where profile.id = v_actor
  for update;

  if not found or not v_profile.is_active then
    raise exception using errcode = '42501', message = 'PTA_PROFILE_INACTIVE';
  end if;

  if v_profile.updated_at is distinct from p_expected_updated_at then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  if char_length(v_name) not between 2 and 120 then
    raise exception using errcode = '22023', message = 'PTA_PROFILE_NAME_INVALID';
  end if;
  if v_pronouns is not null and char_length(v_pronouns) > 50 then
    raise exception using errcode = '22023', message = 'PTA_PROFILE_PRONOUNS_INVALID';
  end if;
  if v_job_title is not null and char_length(v_job_title) > 100 then
    raise exception using errcode = '22023', message = 'PTA_PROFILE_JOB_TITLE_INVALID';
  end if;
  if v_department is not null and char_length(v_department) > 100 then
    raise exception using errcode = '22023', message = 'PTA_PROFILE_DEPARTMENT_INVALID';
  end if;
  if v_bio is not null and char_length(v_bio) > 500 then
    raise exception using errcode = '22023', message = 'PTA_PROFILE_BIO_INVALID';
  end if;
  if v_avatar_path is not null and (
    char_length(v_avatar_path) > 2048
    or v_avatar_path !~ '^https://[^[:space:]]+$'
  ) then
    raise exception using errcode = '22023', message = 'PTA_PROFILE_AVATAR_INVALID';
  end if;

  v_name_parts := regexp_split_to_array(v_name, '\s+');
  v_initials := upper(
    left(v_name_parts[1], 1)
    || case
      when cardinality(v_name_parts) > 1
        then left(v_name_parts[cardinality(v_name_parts)], 1)
      else ''
    end
  );

  update public.profiles
  set
    full_name = v_name,
    initials = v_initials,
    pronouns = v_pronouns,
    job_title = v_job_title,
    department = v_department,
    bio = v_bio,
    avatar_path = v_avatar_path
  where id = v_actor
  returning * into v_profile;

  return jsonb_build_object(
    'id', v_profile.id,
    'full_name', v_profile.full_name,
    'email', v_profile.email,
    'initials', v_profile.initials,
    'avatar_path', v_profile.avatar_path,
    'pronouns', v_profile.pronouns,
    'job_title', v_profile.job_title,
    'department', v_profile.department,
    'bio', v_profile.bio,
    'locale', v_profile.locale,
    'updated_at', v_profile.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_product_operational(p_product_id uuid, p_expected_version integer, p_patch jsonb, p_member_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_product public.products%rowtype;
  v_role public.workspace_role;
  v_owner_id uuid;
begin
  select * into v_product from public.products where id = p_product_id and archived_at is null for update;
  if not found then raise exception using errcode = 'P0002', message = 'PTA_PRODUCT_NOT_FOUND'; end if;
  v_role := private.current_workspace_role(v_product.workspace_id);
  if v_actor is null or v_role is null or v_role not in ('owner', 'admin', 'manager') then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_product.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception using errcode = '22023', message = 'PTA_PATCH_MUST_BE_OBJECT';
  end if;
  if exists (select 1 from jsonb_object_keys(p_patch) as patch_key(key) where patch_key.key <> all(array['name', 'status', 'description', 'owner_id']::text[])) then
    raise exception using errcode = '22023', message = 'PTA_PATCH_HAS_UNSUPPORTED_FIELDS';
  end if;

  v_owner_id := case when p_patch ? 'owner_id' then nullif(p_patch->>'owner_id', '')::uuid else v_product.owner_id end;
  if v_owner_id is not null and not private.portfolio_member_is_active(v_product.workspace_id, v_owner_id) then
    raise exception using errcode = '23514', message = 'PTA_OWNER_NOT_ACTIVE_MEMBER';
  end if;
  if p_member_ids is not null and not private.portfolio_members_valid(v_product.workspace_id, p_member_ids) then
    raise exception using errcode = '23514', message = 'PTA_TEAM_MEMBER_NOT_ACTIVE';
  end if;

  update public.products product set
    name = case when p_patch ? 'name' then p_patch->>'name' else product.name end,
    status = case when p_patch ? 'status' then p_patch->>'status' else product.status end,
    description_json = case when p_patch ? 'description' then jsonb_build_object('text', coalesce(p_patch->>'description', '')) else product.description_json end,
    owner_id = v_owner_id,
    updated_by = v_actor
  where product.id = p_product_id and product.version = p_expected_version
  returning * into v_product;
  if not found then raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT'; end if;

  if p_member_ids is not null then
    delete from public.product_members where product_id = v_product.id;
    insert into public.product_members (workspace_id, product_id, user_id, added_by)
    select v_product.workspace_id, v_product.id, member_id, v_actor
    from (select distinct member_id from unnest(p_member_ids) member_id where member_id is not null) requested;
  end if;

  insert into public.activity_logs (workspace_id, actor_id, entity_type, entity_id, action, changes_json)
  values (v_product.workspace_id, v_actor, 'product', v_product.id, 'product.updated', jsonb_build_object('fields', (select jsonb_agg(patch_key.key) from jsonb_object_keys(p_patch) as patch_key(key))));
  return jsonb_build_object('id', v_product.id, 'version', v_product.version, 'updated_at', v_product.updated_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_project_board_column(p_workspace_id uuid, p_column_key text, p_name text, p_color text, p_icon_key text, p_expected_board_version integer, p_expected_column_version integer, p_cover_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_board_version integer;
  v_column_version integer;
begin
  v_role := private.current_workspace_role(p_workspace_id);
  if v_actor is null or v_role is null or v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_PROJECT_BOARD_CONFIGURATION_FORBIDDEN';
  end if;
  if p_cover_url is not null and (p_cover_url !~ '^https://[^[:space:]]+$' or char_length(p_cover_url) > 2048) then
    raise exception using errcode = '22023', message = 'PTA_BOARD_COVER_INVALID';
  end if;
  if char_length(btrim(coalesce(p_name, ''))) not between 1 and 80 then
    raise exception using errcode = '22023', message = 'PTA_PROJECT_BOARD_COLUMN_NAME_INVALID';
  end if;
  if coalesce(p_color, '') !~ '^[a-z][a-z0-9_-]{0,31}$'
     or coalesce(p_icon_key, '') !~ '^[a-z][a-z0-9-]{0,63}$' then
    raise exception using errcode = '22023', message = 'PTA_PROJECT_BOARD_COLUMN_STYLE_INVALID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pta:project-board:' || p_workspace_id::text, 0)
  );
  select setting.version
  into v_board_version
  from public.project_board_settings setting
  where setting.workspace_id = p_workspace_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_PROJECT_BOARD_NOT_FOUND';
  end if;
  if v_board_version is distinct from p_expected_board_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  select board_column.version
  into v_column_version
  from public.project_board_columns board_column
  where board_column.workspace_id = p_workspace_id
    and board_column.column_key = p_column_key
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_PROJECT_BOARD_COLUMN_NOT_FOUND';
  end if;
  if v_column_version is distinct from p_expected_column_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  update public.project_board_columns board_column
  set name = btrim(p_name),
      color = p_color,
      icon_key = p_icon_key,
      cover_url = p_cover_url
  where board_column.workspace_id = p_workspace_id
    and board_column.column_key = p_column_key;
  update public.project_board_settings setting
  set version = setting.version + 1,
      updated_at = clock_timestamp(),
      updated_by = v_actor
  where setting.workspace_id = p_workspace_id;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, changes_json
  ) values (
    p_workspace_id, v_actor, 'project_board', p_workspace_id,
    'project_board.column_updated',
    jsonb_build_object('column_key', p_column_key)
  );
  return public.get_project_board_configuration(p_workspace_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_resource(p_resource_id uuid, p_expected_version integer, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_resource public.resources%rowtype;
  v_role public.workspace_role;
  v_category_id uuid;
  v_lock_category_id uuid;
  v_type public.resource_type;
  v_task_ids uuid[];
  v_product_ids uuid[];
  v_event_ids uuid[];
  v_tag_ids uuid[];
  v_permissions jsonb;
begin
  if p_resource_id is null or not private.can_edit_resource(p_resource_id) then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_NOT_FOUND';
  end if;

  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;

  if p_patch is null
    or jsonb_typeof(p_patch) is distinct from 'object'
    or p_patch = '{}'::jsonb
    or exists (
      select 1 from jsonb_object_keys(p_patch) patch_key
      where patch_key not in (
        'title',
        'description',
        'external_url',
        'resource_type',
        'category_id',
        'is_restricted',
        'task_ids',
        'product_ids',
        'event_ids',
        'tag_ids',
        'permissions'
      )
    ) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_PATCH';
  end if;

  select * into v_resource
  from public.resources
  where id = p_resource_id and archived_at is null;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_NOT_FOUND';
  end if;

  v_role := private.current_workspace_role(v_resource.workspace_id);

  if p_patch ? 'title'
    and (
      jsonb_typeof(p_patch -> 'title') <> 'string'
      or char_length(btrim(p_patch ->> 'title')) not between 2 and 180
    ) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_TITLE';
  end if;

  if p_patch ? 'description'
    and p_patch -> 'description' <> 'null'::jsonb
    and (
      jsonb_typeof(p_patch -> 'description') <> 'string'
      or char_length(p_patch ->> 'description') > 5000
    ) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_DESCRIPTION';
  end if;

  if p_patch ? 'external_url'
    and (
      jsonb_typeof(p_patch -> 'external_url') <> 'string'
      or not private.is_valid_resource_url(p_patch ->> 'external_url')
    ) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_URL';
  end if;

  if p_patch ? 'resource_type' then
    if jsonb_typeof(p_patch -> 'resource_type') <> 'string'
      or not exists (
        select 1
        from unnest(enum_range(null::public.resource_type)) allowed_type
        where allowed_type::text = p_patch ->> 'resource_type'
      ) then
      raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_TYPE';
    end if;
    v_type := (p_patch ->> 'resource_type')::public.resource_type;
  end if;

  if p_patch ? 'category_id' then
    if p_patch -> 'category_id' = 'null'::jsonb then
      v_category_id := null;
    elsif jsonb_typeof(p_patch -> 'category_id') <> 'string'
      or p_patch ->> 'category_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_CATEGORY';
    else
      v_category_id := (p_patch ->> 'category_id')::uuid;
    end if;
  end if;

  if p_patch ? 'is_restricted'
    and jsonb_typeof(p_patch -> 'is_restricted') <> 'boolean' then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_RESTRICTION';
  end if;

  if p_patch ? 'is_restricted'
    and v_role not in ('owner'::public.workspace_role, 'admin'::public.workspace_role)
    and (p_patch ->> 'is_restricted')::boolean is distinct from v_resource.is_restricted then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_NOT_FOUND';
  end if;

  if p_patch ? 'task_ids' then v_task_ids := private.jsonb_uuid_array(p_patch, 'task_ids'); end if;
  if p_patch ? 'product_ids' then v_product_ids := private.jsonb_uuid_array(p_patch, 'product_ids'); end if;
  if p_patch ? 'event_ids' then v_event_ids := private.jsonb_uuid_array(p_patch, 'event_ids'); end if;
  if p_patch ? 'tag_ids' then v_tag_ids := private.jsonb_uuid_array(p_patch, 'tag_ids'); end if;

  if p_patch ? 'permissions' then
    if v_role not in ('owner'::public.workspace_role, 'admin'::public.workspace_role) then
      raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_NOT_FOUND';
    end if;
    v_permissions := p_patch -> 'permissions';
  end if;

  if v_resource.version is distinct from p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  for v_lock_category_id in
    select candidate.category_id
    from (
      values (
        v_resource.category_id
      ), (
        case
          when p_patch ? 'category_id' then v_category_id
          else v_resource.category_id
        end
      )
    ) as candidate(category_id)
    where candidate.category_id is not null
    group by candidate.category_id
    order by candidate.category_id
  loop
    perform private.lock_resource_category_write(
      v_resource.workspace_id,
      v_lock_category_id
    );
  end loop;

  update public.resources
  set
    title = case when p_patch ? 'title' then p_patch ->> 'title' else title end,
    description = case
      when not (p_patch ? 'description') then description
      when p_patch -> 'description' = 'null'::jsonb then null
      else p_patch ->> 'description'
    end,
    external_url = case when p_patch ? 'external_url' then p_patch ->> 'external_url' else external_url end,
    resource_type = coalesce(v_type, resource_type),
    category_id = case when p_patch ? 'category_id' then v_category_id else category_id end,
    is_restricted = case
      when p_patch ? 'is_restricted' then (p_patch ->> 'is_restricted')::boolean
      else is_restricted
    end
  where id = p_resource_id
    and version = p_expected_version
    and archived_at is null;

  if not found then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  perform private.replace_resource_relations(
    v_resource.workspace_id,
    p_resource_id,
    v_task_ids,
    v_product_ids,
    v_event_ids,
    v_tag_ids,
    v_permissions
  );

  return public.get_resource_detail(p_resource_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_resource_category(p_category_id uuid, p_expected_updated_at timestamp with time zone, p_name text, p_color text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_category public.resource_categories%rowtype;
  v_role public.workspace_role;
  v_name text := btrim(coalesce(p_name, ''));
  v_color text := lower(btrim(coalesce(p_color, 'stone')));
  v_base_slug text;
  v_slug text;
  v_suffix integer := 2;
begin
  select * into v_category
  from public.resource_categories category
  where category.id = p_category_id
    and category.archived_at is null;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_CATEGORY_NOT_FOUND';
  end if;

  v_role := private.current_workspace_role(v_category.workspace_id);
  if v_role is null
    or v_role not in (
      'owner'::public.workspace_role,
      'admin'::public.workspace_role,
      'manager'::public.workspace_role
    ) then
    raise exception using errcode = 'P0002', message = 'PTA_RESOURCE_CATEGORY_NOT_FOUND';
  end if;

  if p_expected_updated_at is null
    or v_category.updated_at is distinct from p_expected_updated_at then
    raise exception using errcode = '40001', message = 'PTA_RESOURCE_CATEGORY_CONFLICT';
  end if;

  if char_length(v_name) not between 2 and 80 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_CATEGORY_NAME';
  end if;

  if v_color not in (
    'stone', 'blue', 'cyan', 'green', 'lime',
    'orange', 'pink', 'purple', 'red', 'yellow'
  ) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_CATEGORY_COLOR';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_category.workspace_id::text, 0)
  );
  perform private.lock_resource_category_write(
    v_category.workspace_id,
    v_category.id
  );

  if exists (
    select 1
    from public.resource_categories category
    where category.workspace_id = v_category.workspace_id
      and category.id <> v_category.id
      and lower(category.name) = lower(v_name)
  ) then
    raise exception using errcode = '23505', message = 'PTA_RESOURCE_CATEGORY_EXISTS';
  end if;

  v_base_slug := trim(
    both '-' from regexp_replace(
      lower(extensions.unaccent(v_name)),
      '[^a-z0-9]+',
      '-',
      'g'
    )
  );
  if v_base_slug = '' then
    raise exception using errcode = '22023', message = 'PTA_INVALID_RESOURCE_CATEGORY_NAME';
  end if;

  v_slug := v_base_slug;
  while exists (
    select 1
    from public.resource_categories category
    where category.workspace_id = v_category.workspace_id
      and category.id <> v_category.id
      and category.slug = v_slug
  ) loop
    v_slug := v_base_slug || '-' || v_suffix::text;
    v_suffix := v_suffix + 1;
  end loop;

  update public.resource_categories category
  set
    name = v_name,
    slug = v_slug,
    color = v_color,
    updated_at = clock_timestamp()
  where category.id = v_category.id
    and category.updated_at = p_expected_updated_at
  returning * into v_category;

  if not found then
    raise exception using errcode = '40001', message = 'PTA_RESOURCE_CATEGORY_CONFLICT';
  end if;

  return jsonb_build_object(
    'id', v_category.id,
    'name', v_category.name,
    'color', v_category.color,
    'position', v_category.position,
    'updated_at', v_category.updated_at,
    'resource_count', (
      select count(*)
      from public.resources resource
      where resource.workspace_id = v_category.workspace_id
        and resource.category_id = v_category.id
        and resource.archived_at is null
        and private.can_view_resource(resource.id)
    )
  );
exception
  when unique_violation then
    raise exception using errcode = '23505', message = 'PTA_RESOURCE_CATEGORY_EXISTS';
end;
$function$

CREATE OR REPLACE FUNCTION public.update_task(p_task_id uuid, p_expected_version integer, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_current public.tasks%rowtype;
  v_task public.tasks%rowtype;
  v_type_id uuid;
  v_product_id uuid;
  v_event_id uuid;
  v_event_product_id uuid;
begin
  if v_actor is null or not private.can_edit_task(p_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  select task.*
  into v_current
  from public.tasks task
  where task.id = p_task_id
    and task.archived_at is null
  for update;

  if not found then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;

  if v_current.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception using errcode = '22023', message = 'PTA_PATCH_MUST_BE_OBJECT';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(p_patch) as patch_key(key)
    where patch_key.key <> all (
      array[
        'title',
        'status_id',
        'priority',
        'due_date',
        'due_time',
        'blocked_reason',
        'type_id',
        'product_id',
        'event_id'
      ]::text[]
    )
  ) then
    raise exception using errcode = '22023', message = 'PTA_PATCH_HAS_UNSUPPORTED_FIELDS';
  end if;

  v_type_id := case
    when p_patch ? 'type_id'
      then nullif(p_patch ->> 'type_id', '')::uuid
    else v_current.type_id
  end;
  v_product_id := case
    when p_patch ? 'product_id'
      then nullif(p_patch ->> 'product_id', '')::uuid
    else v_current.product_id
  end;
  v_event_id := case
    when p_patch ? 'event_id'
      then nullif(p_patch ->> 'event_id', '')::uuid
    else v_current.event_id
  end;

  if p_patch ? 'type_id' and v_type_id is not null and not exists (
    select 1
    from public.task_types task_type
    where task_type.workspace_id = v_current.workspace_id
      and task_type.id = v_type_id
      and task_type.is_active
  ) then
    raise exception using errcode = '23514', message = 'PTA_TYPE_NOT_ACTIVE';
  end if;

  if (p_patch ? 'product_id' or p_patch ? 'event_id')
     and v_product_id is not null
     and not exists (
       select 1
       from public.products product
       where product.workspace_id = v_current.workspace_id
         and product.id = v_product_id
         and product.archived_at is null
     ) then
    raise exception using errcode = '23514', message = 'PTA_PRODUCT_NOT_ACTIVE';
  end if;

  if (p_patch ? 'product_id' or p_patch ? 'event_id')
     and v_event_id is not null then
    select event.product_id
    into v_event_product_id
    from public.events event
    where event.workspace_id = v_current.workspace_id
      and event.id = v_event_id
      and event.archived_at is null;

    if not found then
      raise exception using errcode = '23514', message = 'PTA_EVENT_NOT_ACTIVE';
    end if;

    if v_event_product_id is not null then
      if v_product_id is null and not (p_patch ? 'product_id') then
        v_product_id := v_event_product_id;
      elsif v_product_id is distinct from v_event_product_id then
        raise exception using errcode = '23514', message = 'PTA_EVENT_PRODUCT_MISMATCH';
      end if;
    end if;
  end if;

  update public.tasks task
  set
    title = case
      when p_patch ? 'title' then p_patch ->> 'title'
      else task.title
    end,
    status_id = case
      when p_patch ? 'status_id' then (p_patch ->> 'status_id')::uuid
      else task.status_id
    end,
    priority = case
      when p_patch ? 'priority'
        then (p_patch ->> 'priority')::public.task_priority
      else task.priority
    end,
    due_date = case
      when p_patch ? 'due_date'
        then nullif(p_patch ->> 'due_date', '')::date
      else task.due_date
    end,
    due_time = case
      when p_patch ? 'due_time'
        then nullif(p_patch ->> 'due_time', '')::time
      else task.due_time
    end,
    blocked_reason = case
      when p_patch ? 'blocked_reason' then p_patch ->> 'blocked_reason'
      else task.blocked_reason
    end,
    type_id = case
      when p_patch ? 'type_id' then v_type_id
      else task.type_id
    end,
    product_id = case
      when p_patch ? 'product_id' or p_patch ? 'event_id' then v_product_id
      else task.product_id
    end,
    event_id = case
      when p_patch ? 'event_id' then v_event_id
      else task.event_id
    end,
    updated_by = v_actor
  where task.id = p_task_id
    and task.version = p_expected_version
  returning task.* into v_task;

  if not found then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  return jsonb_build_object(
    'id', v_task.id,
    'version', v_task.version,
    'updated_at', v_task.updated_at,
    'type_id', v_task.type_id,
    'product_id', v_task.product_id,
    'event_id', v_task.event_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_task_board_column(p_workspace_id uuid, p_board_kind text, p_column_key text, p_name text, p_color text, p_icon_key text, p_expected_board_version integer, p_expected_column_version integer, p_cover_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_board_version integer;
  v_column_version integer;
begin
  v_role := private.current_workspace_role(p_workspace_id);
  if v_actor is null or v_role is null or v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_BOARD_CONFIGURATION_FORBIDDEN';
  end if;
  if p_board_kind not in ('status', 'week') then
    raise exception using errcode = '22023', message = 'PTA_BOARD_KIND_INVALID';
  end if;
  if p_cover_url is not null and (p_cover_url !~ '^https://[^[:space:]]+$' or char_length(p_cover_url) > 2048) then
    raise exception using errcode = '22023', message = 'PTA_BOARD_COVER_INVALID';
  end if;
  if char_length(btrim(coalesce(p_name, ''))) not between 1 and 80 then
    raise exception using errcode = '22023', message = 'PTA_BOARD_COLUMN_NAME_INVALID';
  end if;
  if coalesce(p_color, '') !~ '^[a-z][a-z0-9_-]{0,31}$'
     or coalesce(p_icon_key, '') !~ '^[a-z][a-z0-9-]{0,63}$' then
    raise exception using errcode = '22023', message = 'PTA_BOARD_COLUMN_STYLE_INVALID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'pta:task-board:' || p_workspace_id::text || ':' || p_board_kind,
      0
    )
  );
  select setting.version into v_board_version
  from public.task_board_settings setting
  where setting.workspace_id = p_workspace_id
    and setting.board_kind = p_board_kind
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_BOARD_NOT_FOUND';
  end if;
  if v_board_version is distinct from p_expected_board_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  if p_board_kind = 'status' then
    select status.version into v_column_version
    from public.task_statuses status
    where status.workspace_id = p_workspace_id
      and status.semantic_key = p_column_key
    for update;
    if not found then
      raise exception using errcode = 'P0002', message = 'PTA_BOARD_COLUMN_NOT_FOUND';
    end if;
    if v_column_version is distinct from p_expected_column_version then
      raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
    end if;
    update public.task_statuses status
    set name = btrim(p_name), color = p_color, icon_key = p_icon_key, cover_url = p_cover_url
    where status.workspace_id = p_workspace_id
      and status.semantic_key = p_column_key;
  else
    select lane.version into v_column_version
    from public.task_week_lanes lane
    where lane.workspace_id = p_workspace_id
      and lane.lane_key = p_column_key
    for update;
    if not found then
      raise exception using errcode = 'P0002', message = 'PTA_BOARD_COLUMN_NOT_FOUND';
    end if;
    if v_column_version is distinct from p_expected_column_version then
      raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
    end if;
    update public.task_week_lanes lane
    set name = btrim(p_name), color = p_color, icon_key = p_icon_key, cover_url = p_cover_url
    where lane.workspace_id = p_workspace_id
      and lane.lane_key = p_column_key;
  end if;

  update public.task_board_settings setting
  set version = setting.version + 1,
      updated_at = clock_timestamp(),
      updated_by = v_actor
  where setting.workspace_id = p_workspace_id
    and setting.board_kind = p_board_kind;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, changes_json
  ) values (
    p_workspace_id, v_actor, 'task_board', p_workspace_id,
    'task_board.column_updated',
    jsonb_build_object('board_kind', p_board_kind, 'column_key', p_column_key)
  );
  return public.get_task_board_configuration(p_workspace_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_task_checklist(p_checklist_id uuid, p_title text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_checklist public.task_checklists%rowtype;
begin
  select checklist.* into v_checklist
  from public.task_checklists checklist
  where checklist.id = p_checklist_id
  for update;

  if not found or not private.can_edit_task(v_checklist.task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_checklist.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if v_checklist.is_default then
    raise exception using errcode = '23514', message = 'PTA_DEFAULT_CHECKLIST_IMMUTABLE';
  end if;
  if p_title is null or char_length(btrim(p_title)) not between 1 and 200 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_CHECKLIST_TITLE';
  end if;

  update public.task_checklists checklist
  set title = btrim(p_title), updated_at = clock_timestamp()
  where checklist.id = p_checklist_id
  returning checklist.* into v_checklist;

  return jsonb_build_object(
    'id', v_checklist.id,
    'title', v_checklist.title,
    'updated_at', v_checklist.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_task_checklist_item(p_item_id uuid, p_content text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item public.task_checklist_items%rowtype;
begin
  select item.* into v_item
  from public.task_checklist_items item
  where item.id = p_item_id
  for update;

  if not found or not private.can_edit_task(v_item.task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_item.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;
  if p_content is null or char_length(btrim(p_content)) not between 1 and 500 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_CHECKLIST_ITEM';
  end if;

  update public.task_checklist_items item
  set content = btrim(p_content), updated_at = clock_timestamp()
  where item.id = p_item_id
  returning item.* into v_item;

  update public.task_checklists checklist
  set updated_at = clock_timestamp()
  where checklist.workspace_id = v_item.workspace_id
    and checklist.task_id = v_item.task_id
    and checklist.id = v_item.checklist_id;

  return jsonb_build_object(
    'id', v_item.id,
    'content', v_item.content,
    'updated_at', v_item.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_task_comment(p_comment_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_comment public.task_comments%rowtype;
begin
  select task_comment.*
  into v_comment
  from public.task_comments task_comment
  where task_comment.id = p_comment_id
    and task_comment.deleted_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_COMMENT_NOT_FOUND';
  end if;
  v_role := private.task_collaboration_role(v_comment.task_id);
  if v_role is null then
    raise exception using errcode = 'P0002', message = 'PTA_COMMENT_NOT_FOUND';
  end if;
  if v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role,
    'member'::public.workspace_role
  ) or v_comment.created_by <> v_actor then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_body is null or char_length(btrim(p_body)) not between 1 and 10000 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_COMMENT';
  end if;

  if v_comment.body = btrim(p_body) then
    return jsonb_build_object(
      'id', v_comment.id,
      'task_id', v_comment.task_id,
      'parent_comment_id', v_comment.parent_comment_id,
      'body', v_comment.body,
      'created_by', v_comment.created_by,
      'created_at', v_comment.created_at,
      'updated_at', v_comment.updated_at,
      'edited_at', v_comment.edited_at
    );
  end if;

  update public.task_comments task_comment
  set
    body = btrim(p_body),
    updated_at = clock_timestamp(),
    edited_at = clock_timestamp()
  where task_comment.id = p_comment_id
  returning * into v_comment;

  return jsonb_build_object(
    'id', v_comment.id,
    'task_id', v_comment.task_id,
    'parent_comment_id', v_comment.parent_comment_id,
    'body', v_comment.body,
    'created_by', v_comment.created_by,
    'created_at', v_comment.created_at,
    'updated_at', v_comment.updated_at,
    'edited_at', v_comment.edited_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_task_description(p_task_id uuid, p_expected_version integer, p_description jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_task public.tasks%rowtype;
begin
  select task.*
  into v_task
  from public.tasks task
  where task.id = p_task_id
  for update;

  if not found or not private.can_edit_task(p_task_id) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_EXPECTED_VERSION';
  end if;
  if p_description is null
    or not private.is_valid_task_description(p_description) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_TASK_DESCRIPTION';
  end if;
  if octet_length(p_description::text) > 256000 then
    raise exception using errcode = '22023', message = 'PTA_DESCRIPTION_TOO_LARGE';
  end if;

  update public.tasks task
  set
    description_json = p_description,
    updated_by = v_actor
  where task.id = p_task_id
    and task.version = p_expected_version
  returning * into v_task;

  if not found then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  return jsonb_build_object(
    'id', v_task.id,
    'description_json', v_task.description_json,
    'version', v_task.version,
    'updated_at', v_task.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_task_link(p_link_id uuid, p_url text, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_url text := btrim(p_url);
  v_label text := nullif(btrim(p_label), '');
  v_link public.task_links%rowtype;
begin
  select link.*
  into v_link
  from public.task_links link
  where link.id = p_link_id
    and link.deleted_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_LINK_NOT_FOUND';
  end if;
  v_role := private.task_collaboration_role(v_link.task_id);
  if v_role is null then
    raise exception using errcode = 'P0002', message = 'PTA_LINK_NOT_FOUND';
  end if;
  if not (
    v_role in (
      'owner'::public.workspace_role,
      'admin'::public.workspace_role,
      'manager'::public.workspace_role
    )
    or (
      v_role = 'member'::public.workspace_role
      and v_link.created_by = v_actor
    )
  ) then
    raise exception using errcode = '42501', message = 'PTA_FORBIDDEN';
  end if;
  if v_url is null
    or char_length(v_url) not between 8 and 2048
    or v_url !~* '^https://[a-z0-9]([a-z0-9.-]*[a-z0-9])?(:[0-9]{1,5})?([/?#][^[:space:]]*)?$'
    or v_url ~* '%0d|%0a' then
    raise exception using errcode = '22023', message = 'PTA_INVALID_LINK_URL';
  end if;
  if v_label is not null and char_length(v_label) > 200 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_LINK_LABEL';
  end if;

  update public.task_links link
  set
    url = v_url,
    label = v_label,
    provider = private.task_link_provider(v_url),
    updated_at = clock_timestamp()
  where link.id = p_link_id
    and link.deleted_at is null
  returning * into v_link;

  return jsonb_build_object(
    'id', v_link.id,
    'task_id', v_link.task_id,
    'url', v_link.url,
    'label', v_link.label,
    'provider', v_link.provider,
    'created_by', v_link.created_by,
    'created_at', v_link.created_at,
    'updated_at', v_link.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_task_media_description(p_attachment_id uuid, p_description text, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item public.task_attachments%rowtype;
  v_role public.workspace_role;
begin
  if auth.uid() is null then raise exception 'PTA_FORBIDDEN'; end if;
  select * into v_item from public.task_attachments
  where id = p_attachment_id and state = 'ready' for update;
  if not found then raise exception 'PTA_ATTACHMENT_NOT_FOUND'; end if;
  v_role := private.task_collaboration_role(v_item.task_id);
  if v_role is null or not (
    v_role in ('owner', 'admin', 'manager') or
    (v_role = 'member' and v_item.uploaded_by = auth.uid())
  ) then raise exception 'PTA_FORBIDDEN'; end if;
  if p_expected_version is null or v_item.version <> p_expected_version then
    raise exception 'PTA_VERSION_CONFLICT';
  end if;
  if char_length(coalesce(p_description, '')) > 1000 then
    raise exception 'PTA_INVALID_DESCRIPTION';
  end if;
  update public.task_attachments
  set description = btrim(coalesce(p_description, '')), version = version + 1
  where id = p_attachment_id;
  perform realtime.send(
    jsonb_build_object('task_id', v_item.task_id, 'attachment_id', v_item.id),
    'attachment_changed', 'task:' || v_item.task_id::text, true
  );
  return jsonb_build_object('id', p_attachment_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_workspace_settings(p_workspace_id uuid, p_expected_version integer, p_name text, p_task_prefix text, p_accent_color text, p_timezone text, p_week_starts_on smallint, p_working_days smallint[], p_default_due_time time without time zone, p_notification_digest boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role public.workspace_role;
  v_workspace public.workspaces%rowtype;
  v_working_days smallint[];
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;

  v_role := private.current_workspace_role(p_workspace_id);
  if v_role is null or v_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role
  ) then
    raise exception using errcode = '42501', message = 'PTA_WORKSPACE_SETTINGS_FORBIDDEN';
  end if;

  if char_length(btrim(coalesce(p_name, ''))) not between 2 and 120 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_WORKSPACE_NAME';
  end if;
  if upper(btrim(coalesce(p_task_prefix, ''))) !~ '^[A-Z0-9]{2,8}$' then
    raise exception using errcode = '22023', message = 'PTA_INVALID_TASK_PREFIX';
  end if;
  if coalesce(p_accent_color, '') !~ '^#[0-9A-Fa-f]{6}$' then
    raise exception using errcode = '22023', message = 'PTA_INVALID_ACCENT_COLOR';
  end if;
  if not exists (
    select 1 from pg_catalog.pg_timezone_names zone where zone.name = p_timezone
  ) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_TIMEZONE';
  end if;
  if p_week_starts_on not between 0 and 6 then
    raise exception using errcode = '22023', message = 'PTA_INVALID_WEEK_START';
  end if;

  select array_agg(day order by day)::smallint[]
  into v_working_days
  from (
    select distinct unnest(p_working_days) as day
  ) normalized;

  if coalesce(cardinality(v_working_days), 0) = 0
    or not (v_working_days <@ array[0, 1, 2, 3, 4, 5, 6]::smallint[]) then
    raise exception using errcode = '22023', message = 'PTA_INVALID_WORKING_DAYS';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('pta:workspace-settings:' || p_workspace_id::text, 0)
  );

  select workspace.*
  into v_workspace
  from public.workspaces workspace
  where workspace.id = p_workspace_id
    and workspace.archived_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_WORKSPACE_NOT_FOUND';
  end if;
  if v_workspace.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
  end if;

  update public.workspaces workspace
  set name = btrim(p_name),
      task_prefix = upper(btrim(p_task_prefix)),
      accent_color = upper(p_accent_color),
      timezone = p_timezone,
      week_starts_on = p_week_starts_on,
      working_days = v_working_days,
      default_due_time = p_default_due_time,
      version = workspace.version + 1
  where workspace.id = p_workspace_id;

  insert into public.workspace_preferences (
    workspace_id,
    notification_digest,
    updated_at
  ) values (
    p_workspace_id,
    p_notification_digest,
    statement_timestamp()
  )
  on conflict (workspace_id) do update
    set notification_digest = excluded.notification_digest,
        updated_at = excluded.updated_at;

  insert into public.activity_logs (
    workspace_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    changes_json
  ) values (
    p_workspace_id,
    v_actor,
    'workspace',
    p_workspace_id,
    'workspace.settings_updated',
    jsonb_build_object(
      'previous_version', v_workspace.version,
      'version', v_workspace.version + 1
    )
  );

  return public.get_workspace_settings(p_workspace_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.upsert_team_member(p_team_id uuid, p_user_id uuid, p_role team_member_role DEFAULT 'member'::team_member_role, p_is_primary boolean DEFAULT false, p_expected_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_team public.teams%rowtype;
  v_actor_workspace_role public.workspace_role;
  v_existing public.team_members%rowtype;
  v_member public.team_members%rowtype;
begin
  if auth.uid() is null or not private.can_read_team(p_team_id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;
  if v_actor is null then
    raise exception using errcode = '42501', message = 'PTA_AUTH_REQUIRED';
  end if;

  select team.* into v_team
  from public.teams team
  where team.id = p_team_id
    and team.archived_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PTA_TEAM_NOT_FOUND';
  end if;
  if not private.can_manage_team_members(v_team.id) then
    raise exception using errcode = '42501', message = 'PTA_TEAM_FORBIDDEN';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('pta:operating-model:' || v_team.workspace_id::text, 0)
  );

  if not exists (
    select 1
    from public.workspace_members member
    join public.profiles profile on profile.id = member.user_id and profile.is_active
    where member.workspace_id = v_team.workspace_id
      and member.user_id = p_user_id
      and member.status = 'active'::public.membership_status
      and member.removed_at is null
      and member.role <> 'viewer'::public.workspace_role
  ) then
    raise exception using errcode = '23514', message = 'PTA_MEMBER_NOT_ACTIVE';
  end if;

  v_actor_workspace_role := private.current_workspace_role(v_team.workspace_id);
  if v_actor_workspace_role not in (
    'owner'::public.workspace_role,
    'admin'::public.workspace_role,
    'manager'::public.workspace_role
  ) and p_role = 'lead'::public.team_member_role then
    raise exception using errcode = '42501', message = 'PTA_TEAM_LEAD_GRANT_FORBIDDEN';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'pta:team-member:' || v_team.workspace_id::text || ':' || p_user_id::text,
      0
    )
  );

  if coalesce(p_is_primary, false) then
    update public.team_members other_membership
    set is_primary = false
    where other_membership.workspace_id = v_team.workspace_id
      and other_membership.user_id = p_user_id
      and other_membership.team_id <> v_team.id
      and other_membership.is_primary
      and other_membership.removed_at is null;
  end if;

  select member.* into v_existing
  from public.team_members member
  where member.workspace_id = v_team.workspace_id
    and member.team_id = v_team.id
    and member.user_id = p_user_id
  for update;

  if found then
    if p_expected_version is null or v_existing.version <> p_expected_version then
      raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
    end if;
    if v_actor_workspace_role not in (
      'owner'::public.workspace_role,
      'admin'::public.workspace_role,
      'manager'::public.workspace_role
    ) and v_existing.role = 'lead'::public.team_member_role then
      raise exception using errcode = '42501', message = 'PTA_TEAM_LEAD_CHANGE_FORBIDDEN';
    end if;

    update public.team_members member
    set
      role = p_role,
      is_primary = coalesce(p_is_primary, false),
      removed_at = null,
      removed_by = null
    where member.workspace_id = v_team.workspace_id
      and member.team_id = v_team.id
      and member.user_id = p_user_id
    returning member.* into v_member;
  else
    if p_expected_version is not null then
      raise exception using errcode = '40001', message = 'PTA_VERSION_CONFLICT';
    end if;
    insert into public.team_members (
      workspace_id, team_id, user_id, role, is_primary, added_by
    ) values (
      v_team.workspace_id,
      v_team.id,
      p_user_id,
      p_role,
      coalesce(p_is_primary, false),
      v_actor
    )
    returning * into v_member;
  end if;

  if v_member.is_primary then
    update public.team_members other_membership
    set is_primary = false
    where other_membership.workspace_id = v_member.workspace_id
      and other_membership.user_id = v_member.user_id
      and other_membership.team_id <> v_member.team_id
      and other_membership.is_primary
      and other_membership.removed_at is null;
  elsif not exists (
    select 1
    from public.team_members primary_membership
    where primary_membership.workspace_id = v_member.workspace_id
      and primary_membership.user_id = v_member.user_id
      and primary_membership.is_primary
      and primary_membership.removed_at is null
  ) then
    update public.team_members member
    set is_primary = true
    where member.workspace_id = v_member.workspace_id
      and member.team_id = v_member.team_id
      and member.user_id = v_member.user_id
    returning member.* into v_member;
  end if;

  insert into public.activity_logs (
    workspace_id, actor_id, entity_type, entity_id, action, metadata_json
  ) values (
    v_member.workspace_id,
    v_actor,
    'team_member',
    v_member.team_id,
    'team.member_saved',
    jsonb_build_object(
      'user_id', v_member.user_id,
      'team_role', v_member.role,
      'is_primary', v_member.is_primary
    )
  );

  return jsonb_build_object(
    'workspace_id', v_member.workspace_id,
    'team_id', v_member.team_id,
    'user_id', v_member.user_id,
    'role', v_member.role,
    'is_primary', v_member.is_primary,
    'version', v_member.version
  );
end;
$function$
